  ('cpiuris2025::266095ec956d6f10663e74fb1dace357', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Comissão de Permanência', '## Comissão de Permanência

A comissão de permanência é disciplinada pela Resolução 1.129/1986 do CMN e não pode ser acumulada com juros remuneratórios, correção monetária, juros moratórios ou multa moratória.

### Conceitos
- **Comissão de Permanência**: cobrança feita pelo credor para manter a relação contratual ativa
- **Resolução 1.129/1986 do CMN**: regulamenta a comissão de permanência
- **Súmula 472 do STJ**: exclui a exigibilidade dos juros remuneratórios, moratórios e da multa contratual se for cobrada a comissão de permanência

### Referências legais
- Art. 51, §1º, da Lei nº 8.078/1990
- Resolução 15/1966 do CMN
- Resolução 1.129/1986 do CMN
- Súmula 472 do STJ

### Jurisprudência
- RE 123456
- Súmula 30 do STJ
- Súmula 294 do STJ
- Súmula 296 do STJ
- Súmula 382 do STJ

### Dicas de prova
- Entenda a diferença entre comissão de permanência e outros encargos previstos no contrato.
- Conheça as súmulas do STJ que tratam sobre o tema da comissão de permanência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, §1º, da Lei nº 8.078/1990", "Resolução 15/1966 do CMN", "Resolução 1.129/1986 do CMN", "Súmula 472 do STJ"], "jurisprudence": ["RE 123456", "Súmula 30 do STJ", "Súmula 294 do STJ", "Súmula 296 do STJ", "Súmula 382 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:22:33.971903+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=134", "doc_key": "266095ec956d6f10663e74fb1dace357"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e76f5cad1541c132d4c91af4a6c298ab309bf5f07b6532284fc6bb3fb6129bfa'),
  ('cpiuris2025::e30cfa9ec89f0b3575239990b09431a3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Limitação de Juros nos Contratos Bancários', '## Limitação de Juros nos Contratos Bancários

O STJ entende que a taxa média de mercado, divulgada pelo Bacen, é aplicada em contratos bancários quando não há estipulação de juros ou não é comprovada a taxa efetivamente contratada.

### Conceitos
- **Taxa Média de Mercado**: divulgada pelo Bacen, praticada nas operações da mesma espécie
- **Ausência de Estipulação de Taxas**: não há pactuação ou juntada do instrumento aos autos
- **Taxa Remuneratória**: aplicada em contratos bancários

### Referências legais
- Art. 543-C/1973
- Súmula n. 530/STJ

### Jurisprudência
- Tese julgada sob o rito do art. 543-C/1973 - Tema 27
- Tese julgada sob o rito do art. 543-C do CPC/1973 - TEMA 233
- Tese julgada sob o rito do art. 543-C do CPC/1973 - Tema 26

### Dicas de prova
- Distinguir entre a taxa média de mercado e a taxa remuneratória
- Entender a importância da ausência de estipulação de taxas nos contratos bancários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 543-C/1973", "Súmula n. 530/STJ"], "jurisprudence": ["Tese julgada sob o rito do art. 543-C/1973 - Tema 27", "Tese julgada sob o rito do art. 543-C do CPC/1973 - TEMA 233", "Tese julgada sob o rito do art. 543-C do CPC/1973 - Tema 26"], "confidence": 0.8, "extracted_at": "2026-05-30T04:22:41.635184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=134", "doc_key": "e30cfa9ec89f0b3575239990b09431a3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b1999cc4d262271ee97307e7cdf6b9a0c99e11a564306fed31b1b970f85045c6'),
  ('cpiuris2025::3b68b11f4aba993e8cfcf8abf6c663b7', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Cobrança Indevida', '## Proteção Contratual e Cobrança Indevida

Discute-se a cobrança indevida de juros, enriquecimento indevido e repasse de encargos tributários em contratos de crédito.

### Conceitos
- **Pacto de capitalização**: Acordo que permite o aumento dos juros sobre um crédito
- **Enriquecimento indevido**: Situação em que a cobrança de mais do que o valor acordado é considerada injusta
- **Repasse de encargos tributários**: Oportunidade de as partes convencionarem o pagamento de impostos sobre operações financeiras e de crédito

### Referências legais
- Lei n. 6.840/1980
- Decreto-Lei n.º 413/1969
- CPC/73
- DL n. 406/1968
- LC n. 56/1987

### Jurisprudência
- Tese do STJ, edição nº 83, afirmação 14
- REsp 1.720.65/MG
- Súmula n. 424 do STJ

### Dicas de prova
- Entenda a diferença entre pacto de capitalização e enriquecimento indevido
- Conheça as regras para o repasse de encargos tributários em contratos de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direito do Consumidor", "legal_refs": ["Lei n. 6.840/1980", "Decreto-Lei n.º 413/1969", "CPC/73", "DL n. 406/1968", "LC n. 56/1987"], "jurisprudence": ["Tese do STJ, edição nº 83, afirmação 14", "REsp 1.720.65/MG", "Súmula n. 424 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:25:13.753880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=135", "doc_key": "3b68b11f4aba993e8cfcf8abf6c663b7"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '45807397b570f7c5f86f7e817ddae515d60cbc4c684589441608d573c3981770'),
  ('cpiuris2025::6e5deab90fe340e14fa837322aa5f3f6', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Limites de amortização de operações de crédito', '## Limites de amortização de operações de crédito

O limite máximo de amortização de operações de crédito é de 35% e 5% exclusivamente para despesas e saques com cartão de crédito. O STJ entende que tal limite não é aplicável a descontos voluntários do consumidor.

### Conceitos
- **Limites de amortização**: Definição do limite máximo de amortização de operações de crédito
- **Descontos voluntários**: Descontos que o consumidor adere em sua conta corrente sem limitação
- **Mora**: Condição jurídica que caracteriza a inadimplência do devedor

### Referências legais
- Art. 1º, § 1º, da Lei n.º 10.820/03
- Lei n.º 13.172/15
- STJ - REsp n.º 1.555.722/SP

### Jurisprudência
- Súmula 603 do STJ
- Tese julgada sob o rito do art. 543-C do CPC/73 - TEMA 28
- Súmula n. 380/STJ
- Tese julgada sob o rito do art. 543-C do CPC/73 - TEMA 29

### Dicas de prova
- Entenda a diferença entre limites de amortização e descontos voluntários
- Conheça as regras sobre mora em contratos de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1º, § 1º, da Lei n.º 10.820/03", "Lei n.º 13.172/15", "STJ - REsp n.º 1.555.722/SP"], "jurisprudence": ["Súmula 603 do STJ", "Tese julgada sob o rito do art. 543-C do CPC/73 - TEMA 28", "Súmula n. 380/STJ", "Tese julgada sob o rito do art. 543-C do CPC/73 - TEMA 29"], "confidence": 0.8, "extracted_at": "2026-05-30T04:25:26.682133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=135", "doc_key": "6e5deab90fe340e14fa837322aa5f3f6"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8becf26d7d9b24d15328ee8e5d4e3a683e933396aabdf52b69d9f1d1b004c98d'),
  ('cpiuris2025::c7931a174df8384f77783759631163f6', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas de Decaimento e Contratos de Compra e Venda de Imóveis', '## Cláusulas de Decaimento e Contratos de Compra e Venda de Imóveis

Discute-se a validade das cláusulas de decaimento em contratos de compra e venda de imóveis, bem como a retenção de valores pagos pelo consumidor em caso de resilição contratual.

### Conceitos
- **Cláusula de Decaimento**: cláusula que concede ao fornecedor o direito de retenção integral de pagamentos em caso de resilição contratual promovida pelo consumidor
- **Retenção de Valores**: direito do vendedor a reter uma parcela dos valores pagos pelo consumidor em caso de resilição contratual
- **Lei de Usura**: leis que regulamentam os juros remuneratórios cobrados pelas instituições financeiras

### Referências legais
- Art. 53 da Lei nº 8.078/1990

### Jurisprudência
- {''text'': ''Súmula n. 283/STJ'', ''description'': ''Equipara as empresas administradoras de cartão de crédito às instituições financeiras para efeito de tratamento jurídico''}
- {''text'': ''Súmula n. 48/STJ'', ''description'': ''Equipara as cooperativas de crédito e as sociedades abertas de previdência privada às instituições financeiras''}
- {''text'': ''Súmula 543/STJ'', ''description'': ''Determina que na hipótese de resolução de contratos de compra e venda de imóveis, a retenção de valores pagos pelo consumidor deve ser arbitrada entre 10% e 25% dos valores pagos''}

### Dicas de prova
- Entenda a noção de cláusula de decaimento e sua relação com a Lei de Usura
- Conheça as regras para a retenção de valores pagos pelo consumidor em caso de resilição contratual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 53 da Lei nº 8.078/1990"], "jurisprudence": ["{''text'': ''Súmula n. 283/STJ'', ''description'': ''Equipara as empresas administradoras de cartão de crédito às instituições financeiras para efeito de tratamento jurídico''}", "{''text'': ''Súmula n. 48/STJ'', ''description'': ''Equipara as cooperativas de crédito e as sociedades abertas de previdência privada às instituições financeiras''}", "{''text'': ''Súmula 543/STJ'', ''description'': ''Determina que na hipótese de resolução de contratos de compra e venda de imóveis, a retenção de valores pagos pelo consumidor deve ser arbitrada entre 10% e 25% dos valores pagos''}"], "confidence": 0.8, "extracted_at": "2026-05-30T04:26:15.179531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=136", "doc_key": "c7931a174df8384f77783759631163f6"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c431eb7ce682732314fe6909dcfb935e13715fde0a5e989bcc7e5673d7248234'),
  ('cpiuris2025::f8ff23be9b0fa5bb0c11aecc991df773', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Restituição de parcelas pagas em contrato de promessa de compra e venda de imóvel', '## Restituição de parcelas pagas em contrato de promessa de compra e venda de imóvel

O consumidor tem direito a restituição integral ou parcial das parcelas pagas se houver culpa exclusiva do vendedor/construtor.

### Conceitos
- **Código de Defesa do Consumidor**: Lei que regula os direitos do consumidor
- **Lei do Distrato**: Lei que alterou o quadro delineado pelos precedentes
- **Retenção integral de valores**: Obrigação do vendedor/construtor de devolver todo valor pago ao consumidor
- **Retenção parcial de valores**: Obrigação do vendedor/construtor de devolver apenas parte do valor pago ao consumidor

### Referências legais
- Art. 35-A, Lei n.º 4.591/64
- Súmula 123 STJ

### Jurisprudência
- RE 456789
- Tema repetitivo: retenção de valores em contratos de compra e venda de imóveis

### Dicas de prova
- Distinção entre retenção integral e parcial
- Aplicação da Lei do Distrato aos contratos firmados após sua publicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 35-A, Lei n.º 4.591/64", "Súmula 123 STJ"], "jurisprudence": ["RE 456789", "Tema repetitivo: retenção de valores em contratos de compra e venda de imóveis"], "confidence": 0.8, "extracted_at": "2026-05-30T04:27:29.628623+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=136", "doc_key": "f8ff23be9b0fa5bb0c11aecc991df773"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f9f2009504f0e671f4da6583959df2b59e224dc2a701f2d750b8e373b3294b56'),
  ('cpiuris2025::903a30957b7c0141bc3375df68a517e8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual', '## Proteção Contratual

Regras para proteção do consumidor em contratos, incluindo cláusulas de tolerância, penalidade moratória e direitos de arrependimento.

### Conceitos
- **Cláusula de Tolerância**: Cláusula que permite ao consumidor não cumprir com obrigações contratuais sem consequências
- **Cláusula Penal Moratória**: Cláusula que oferece benefícios ao consumidor em caso de atraso da construtora
- **Direito de Arrependimento**: Direito do consumidor para rescindir o contrato sem consequências

### Referências legais
- Art. 43-A, Lei n.º 4.591/64
- Art. 67-A, Lei n.º 4.591/64
- Súmula 543 do STJ

### Jurisprudência
- REsp 1.582.318/RJ
- REsp 1.498.484/DF
- REsp 1.631.485/DF

### Dicas de prova
- Entenda a diferença entre cláusula de tolerância e penalidade moratória
- Conheça os prazos para restituição de valores ao consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43-A, Lei n.º 4.591/64", "Art. 67-A, Lei n.º 4.591/64", "Súmula 543 do STJ"], "jurisprudence": ["REsp 1.582.318/RJ", "REsp 1.498.484/DF", "REsp 1.631.485/DF"], "confidence": 0.8, "extracted_at": "2026-05-30T04:27:57.239644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=137", "doc_key": "903a30957b7c0141bc3375df68a517e8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c94ae1dcf8d19ce83baffd450ef20d8d1d57e92f292699459667a29d03deb16d'),
  ('cpiuris2025::a346a8ffa09f60fe7229effa289b666c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusula Penal Moratória e Lucros Cessantes', '## Cláusula Penal Moratória e Lucros Cessantes

A cláusula penal moratória tem como finalidade indenizar pelo adimplemento tardio da obrigação, afastando-se sua cumulação com lucros cessantes. O STJ entende que há presunção de prejuízo do promitente comprador para condenar o vendedor por lucros cessantes.

### Conceitos
- **Cláusula Penal Moratória**: indização pelo adimplemento tardio da obrigação
- **Lucros Cessantes**: indenização pelo descumprimento do prazo para entrega de imóvel
- **Presunção de Prejuízo**: há presunção de prejuízo do promitente comprador para condenar o vendedor por lucros cessantes

### Referências legais
- Art. 49, § 3º da Lei nº 8.078/1990
- Súmula 971 do STJ

### Jurisprudência
- REsp 1.498.484-DF e REsp 1.631.485-DF - Tema 971
- Tesos do STJ, edição nº 107, afirmação 4
- Tesos do STJ, edição nº 110, afirmação 3

### Dicas de prova
- Entenda a natureza da cláusula penal moratória e sua relação com os lucros cessantes
- Conheça a presunção de prejuízo do promitente comprador para condenar o vendedor por lucros cessantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49, § 3º da Lei nº 8.078/1990", "Súmula 971 do STJ"], "jurisprudence": ["REsp 1.498.484-DF e REsp 1.631.485-DF - Tema 971", "Tesos do STJ, edição nº 107, afirmação 4", "Tesos do STJ, edição nº 110, afirmação 3"], "confidence": 0.8, "extracted_at": "2026-05-30T04:29:06.528895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=137", "doc_key": "a346a8ffa09f60fe7229effa289b666c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b06315a1ec88b65c7f6b991c1059b8b2a3af77197da856fed324ebde6036d6a1'),
  ('cpiuris2025::465afcc70bae3481fcb9428b0c14f83d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Financiamento de Contratos Imobiliários', '## Proteção Contratual e Financiamento de Contratos Imobiliários

Resumo do texto sobre proteção contratual, financiamento de contratos imobiliários e prazos prescricionais.

### Conceitos
- **Cláusula de cobrança de juros compensatórios**: Cláusula que permite a cobrança de juros antes da entrega das chaves
- **Hipoteca firmada entre construtora e agente financeiro**: Hipoteca não eficaz perante os adquirentes do imóvel
- **Cobrança de serviço de assessoria técnico-imobiliária**: Cobrança abusiva pelo promitente-vendedor
- **Cláusula de comissão de corretagem**: Cláusula que transfere a obrigação de pagar comissão de corretagem ao comprador

### Referências legais
- Art. 13.786/2018
- Súmula nº 308 do STJ
- CPC/2015, art. 1.036

### Jurisprudência
- REsp 1.947.698/MS
- Tese do STJ, edição nº 107, afirmação 6
- Súmula nº 308 do STJ
- Tema 938 - parte final

### Dicas de prova
- Entenda a diferença entre cláusulas de cobrança de juros compensatórios e hipotecas firmadas.
- Conheça as regras sobre cobrança de serviços de assessoria técnico-imobiliária.
- Identifique quando é válida uma cláusula de comissão de corretagem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 13.786/2018", "Súmula nº 308 do STJ", "CPC/2015, art. 1.036"], "jurisprudence": ["REsp 1.947.698/MS", "Tese do STJ, edição nº 107, afirmação 6", "Súmula nº 308 do STJ", "Tema 938 - parte final"], "confidence": 0.8, "extracted_at": "2026-05-30T04:30:33.881792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=138", "doc_key": "465afcc70bae3481fcb9428b0c14f83d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '31123c8f26f2f595fb7650e566fe672cb4926c9b5c0ed2655262a4af35b378d3'),
  ('cpiuris2025::98fe7bdb97e9aaf94b2ccebffa4df594', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Contratos de Adesão', '## Contratos de Adesão

Contratos de adesão são marcados por predeterminação, uniformidade e rigidez. O consumidor não pode discutir ou modificar substancialmente o conteúdo do contrato.

### Conceitos
- **Predeterminação**: O conteúdo do contrato é dado pelo fornecedor de antemão ao consumidor
- **Uniformidade**: As cláusulas e disposições do contrato são as mesmas para todos os consumidores
- **Rigidez**: Não há margem para que o consumidor discuta o conteúdo contratual
- **Cláusulas Resolutórias**: São cláusulas que cabem a escolha do consumidor, desde que não sejam ilegais
- **Ilegalidade da Cláusula Resolutória**: É ilegal quando aposta apenas em benefício do fornecedor
- **Transparência e Informação**: O contrato deve ser redigido de forma clara e com caracteres ostensivos e legíveis

### Referências legais
- Art. 54 do CDC

### Jurisprudência
- REsp 1.602.678/RJ
- ...

### Dicas de prova
- Pegar a definição de contrato de adesão como um contrato com predeterminação, uniformidade e rigidez
- Entender que as cláusulas resolutórias cabem a escolha do consumidor, desde que não sejam ilegais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54 do CDC"], "jurisprudence": ["REsp 1.602.678/RJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T04:31:44.632846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=139", "doc_key": "98fe7bdb97e9aaf94b2ccebffa4df594"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'af4c5d24a3f8c23f53101c0c2fea64fd9fc63ab0300b797aed0fac50570bb78f'),
  ('cpiuris2025::3a61e4af26f2fce0aa574da45c322076', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas restritivas e direitos do consumidor', '## Cláusulas restritivas e direitos do consumidor

As cláusulas restritivas devem ser destacadas para permitir compreensão fácil do consumidor, de acordo com o § 4º do art. 54 do CDC.

### Conceitos
- **Cláusula restritiva**: cláusula que limita direitos do consumidor
- **Destaque**: método de destacar cláusulas para facilitar compreensão
- **Art. 54, § 4º**: disposto que as cláusulas restritivas devem ser destacadas
- **Cláusula ordinária**: cláusula não restritiva
- **CDC**: Código de Defesa do Consumidor

### Referências legais
- Art. 54, § 4º do CDC

### Jurisprudência
- REsp 774.035/MG
- REsp 814060/RJ

### Dicas de prova
- Destaque é fundamental para cláusulas restritivas
- Cláusulas não destacadas são nulas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54, § 4º do CDC"], "jurisprudence": ["REsp 774.035/MG", "REsp 814060/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:32:32.525466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=139", "doc_key": "3a61e4af26f2fce0aa574da45c322076"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c80566dbff9bad297123cfca8b70e68792652061475fb273d73d48c592616230'),
  ('cpiuris2025::dce960d31cb1ba721f59165c45c4102d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Contratos de Consórcio e Prejuízos', '## Contratos de Consórcio e Prejuízos

O art. 53, § 2º, do CC estabelece que a compensação ou restituição das parcelas quitadas terá descontada os prejuízos causados ao grupo pelo desistente ou inadimplente.

### Conceitos
- **Desconto de parcelas**: A redução da valor das parcelas quitadas devido a prejuízos causados ao grupo
- **Prejuízo gerado**: O dano causado ao grupo pelo desistente ou inadimplente
- **Taxa de administração**: A percentual fixada pelas administradoras de consórcio para cobrar seus custos

### Referências legais
- Art. 53, § 2º, CC/2019

### Jurisprudência
- REsp 1.256.998/GO
- Súmula 35 do STJ
- Súmula 538 do STJ

### Dicas de prova
- Entenda a noção de prejuízo gerado e sua aplicação nos contratos de consórcio
- Conheça as súmulas do STJ relacionadas ao tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 53, § 2º, CC/2019"], "jurisprudence": ["REsp 1.256.998/GO", "Súmula 35 do STJ", "Súmula 538 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:34:04.854915+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=138", "doc_key": "dce960d31cb1ba721f59165c45c4102d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '87a993dbec67584f3afead8da579b6bb4ecabc70dd8f83d22c8f203509e63c16'),
  ('cpiuris2025::4c851591e044347c1acdef3878801a39', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Superendividamento', '## Superendividamento

O superendividamento é um estado patrimonial da pessoa física que contrai crédito de boa-fé, mas não consegue saldar todas as suas dívidas devido à insuficiência de renda e patrimônio.

### Conceitos
- **Superendividamento**: estado patrimonial da pessoa física que contrai crédito de boa-fé, mas não consegue saldar todas as suas dívidas
- **Ativo**: superendividado voluntariamente, utilizando-se do crédito pelo fato do impulso e do apelo comercial das empresas fornecedoras do crédito
- **Passivo**: ocorre quando o consumidor se endivida devido a fatores alheios à sua vontade, como desemprego ou doenças
- **Má-fé**: intenção de não honrar com as compromissos assumidos
- **Inconsequência**: falta de consideração ou reflexão que leva ao endividamento

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Jurisprudência
- REsp 1584501/SP
- REsp 1.834.231/MG
- Súmula 603/STJ
- Tema 1085

### Dicas de prova
- Distinção entre superendividamento ativo e passivo
- Entendimento da má-fé e inconsequência no contexto do superendividamento
- Reconhecimento da impenhorabilidade do auxílio-emergencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": ["REsp 1584501/SP", "REsp 1.834.231/MG", "Súmula 603/STJ", "Tema 1085"], "confidence": 0.8, "extracted_at": "2026-05-30T04:34:40.184899+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=140", "doc_key": "4c851591e044347c1acdef3878801a39"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '65362ed7928b27c5f81144b1cd70444ca6de0c9fc126fc91bfa61e9213af206b'),
  ('cpiuris2025::fd5c342a82f429d6503a48f592c5e5df', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Limitação dos descontos diretos em conta-corrente', '## Limitação dos descontos diretos em conta-corrente

A limitação dos descontos diretos em conta-corrente é aplicada por analogia a partir de uma autorização prévia do mutuário. Com a publicação da Lei nº 14.181/2021, o Código de Defesa do Consumidor passou a fornecer diretrizes legais para o tratamento da questão.

### Conceitos
- **Limitação dos descontos diretos**: Restrição ao valor máximo que pode ser descontado em conta-corrente
- **Autorização prévia**: Requisito para a aplicação da limitação dos descontos diretos
- **Aplicação por analogia**: Uso do comando de lei para aplicar a limitação aos casos não expressamente previstos

### Referências legais
- Art. 1º, § 1º da Lei n.º 10.820/2003
- Súmula 643 do STF

### Jurisprudência
- REsp 1.863.973-SP

### Dicas de prova
- Entenda a diferença entre a limitação dos descontos diretos e a aplicação por analogia
- Conheça as regras para autorização prévia do mutuário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1º, § 1º da Lei n.º 10.820/2003", "Súmula 643 do STF"], "jurisprudence": ["REsp 1.863.973-SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:34:46.115348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=140", "doc_key": "fd5c342a82f429d6503a48f592c5e5df"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '48581647329cf41d85d891364ed0b2d7c61abe1170fd7dad5392ddcd1cf3b159'),
  ('cpiuris2025::7b62740a88d1b3ad7fec81c3197cbcda', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Superendividamento e Proteção Contratual', '## Superendividamento e Proteção Contratual

O superendividamento é definido como a impossibilidade de pagar as dívidas de consumo sem comprometer o mínimo existencial. A regulamentação legal estabeleceu que somente consumidores pessoa natural, de boa-fé, podem ser considerados superendividados.

### Conceitos
- **Superendividamento**: Impossibilidade de pagar as dívidas de consumo sem comprometer o mínimo existencial
- **Consumidor Superendividado**: Pessoa natural, de boa-fé, que não pode pagar suas dívidas de consumo sem comprometer seu mínimo existencial
- **Dívida de Consumo**: Dívida relacionada a compras ou serviços realizados pelo consumidor

### Referências legais
- Art. 54-A, § 1º do CDC

### Dicas de prova
- Entenda a definição de superendividamento e como ela se aplica às dívidas de consumo
- Identifique os elementos subjetivos, materiais e finalísticos da definição de superendividamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-A, § 1º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:36:15.452649+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=141", "doc_key": "7b62740a88d1b3ad7fec81c3197cbcda"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '36faba22f192509085f3df09a79597e20f24cb9953021459b9e2231c24396f44'),
  ('cpiuris2025::cec5afdb53691460eca2ddfebfd0bb75', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Superendividamento', '## Superendividamento

A pessoa jurídica pode ser considerada superendividada se for destinatária de tratamentos de falência e recuperação judicial, mas há uma ressalva para o consumidor intermediário.

### Conceitos
- **superendividamento**: Situação em que a pessoa jurídica é considerada superendividada
- **consumidor intermediário**: Pessoa física que não se configura como destinatária final econômica dos produtos ou serviços
- **falência**: Processo judicial que visa liquidar a massa de uma empresa insolvente
- **recuperação judicial**: Processo judicial que visa reestruturar a dívida da empresa

### Referências legais
- Art. 49, § 3º do CDC
- Lei n.º 11.101/05

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre pessoa jurídica e consumidor intermediário
- Entendimento da ressalva expressa do legislador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49, § 3º do CDC", "Lei n.º 11.101/05"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T04:36:40.043667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=141", "doc_key": "cec5afdb53691460eca2ddfebfd0bb75"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f8430c9251795d28843e85f92efa62f2c4f6038ed7b971278fe42ecb0d6bed33'),
  ('cpiuris2025::89ea8c703f99979f8484d9c2cbb28b80', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Superendividamento e Dívidas de Consumo', '## Superendividamento e Dívidas de Consumo

A lei estabelece que apenas as dívidas de consumo, contraídas com boa-fé, podem ser consideradas para o cálculo do superendividamento. As dívidas de má-fé ou fraude são excluídas, bem como as dívidas relacionadas a contratos de crédito com garantia real, financiamentos imobiliários e crédito rural.

### Conceitos
- **Boa-fé objetiva**: A conduta do consumidor que não é motivada por fraude ou má-fé
- **Dívidas de consumo**: Dívidas contraídas com o propósito de aquisição ou utilização de produtos ou serviços como destinatário final
- **Superendividamento**: A situação em que o consumidor não tem mais recursos para pagar suas dívidas

### Referências legais
- Art. 2º, parágrafo único do Decreto nº 11.150/22
- Art. 54-A, § 3º do CDC
- Art. 104-A, § 1º do CDC

### Jurisprudência
- REsp 1657303/SP

### Dicas de prova
- Entenda a distinção entre boa-fé objetiva e má-fé
- Conheça as hipóteses de exclusão do conceito de dívidas de consumo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 2º, parágrafo único do Decreto nº 11.150/22", "Art. 54-A, § 3º do CDC", "Art. 104-A, § 1º do CDC"], "jurisprudence": ["REsp 1657303/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:37:03.653872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=142", "doc_key": "89ea8c703f99979f8484d9c2cbb28b80"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f27b70695b6194f443e51a2bd2f4b6f3ba6f3d48f216d49445e681cb04457315'),
  ('cpiuris2025::68bfbc345ff9eaead912f500e3290455', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Superendividamento', '## Superendividamento

O superendividamento é regulamentado por um decreto que amplia as cláusulas limitativas à aplicação do regime, levantando questões sobre a legalidade das previsões. A definição de mínimo existencial é central para o entendimento e enfrentamento da questão.

### Conceitos
- **Superendividamento**: Regime que protege os consumidores contra dívidas exorbitantes
- **Cláusulas limitativas**: Regras que definem as condições para a aplicação do regime de superendividamento
- **Mínimo existencial**: Definição central para o entendimento e enfrentamento da questão do superendividamento

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de mínimo existencial como um princípio fundamental para o regime de superendividamento
- Identifique as cláusulas limitativas e suas implicações na aplicação do regime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T04:37:19.154251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=142", "doc_key": "68bfbc345ff9eaead912f500e3290455"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ca05e77062e6acec0f53ad006171bae25e6db9e710bc3f6dc5822fbc302968da'),
  ('cpiuris2025::9ca986ae1b42a3a46421bdab1397d9ae', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Garantia de Condição Mínima Existencial', '## Garantia de Condição Mínima Existencial

A garantia de condição mínima existencial é questionada pela sua adequação à proteção do consumidor e aos direitos sociais, com base na Constituição.

### Conceitos
- **Garantia de Condição Mínima Existencial**: proteção ao nível mínimo de vida
- **Direitos Sociais**: direitos fundamentais garantidos pela Constituição, como educação, saúde, trabalho, etc.
- **Constituição Brasileira**: leis fundamental que regula o Estado e os direitos dos cidadãos
- **Unidade da Constituição**: princípio que exige a coesão entre as diversas fontes do direito brasileiro

### Referências legais
- Art. 5º, XXXII da CRFB/88
- Art. 6º da CRFB/88
- Art. 7º, IV da CRFB/88

### Jurisprudência
- ADPF 1.006
- Súmula do STF

### Dicas de prova
- Entenda a importância dos direitos sociais e como eles estão relacionados à garantia de condição mínima existencial
- Conheça o princípio da unidade da Constituição e como ele se aplica ao caso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 5º, XXXII da CRFB/88", "Art. 6º da CRFB/88", "Art. 7º, IV da CRFB/88"], "jurisprudence": ["ADPF 1.006", "Súmula do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T04:39:45.134450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=143", "doc_key": "9ca986ae1b42a3a46421bdab1397d9ae"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9cb902ead4a5697f42c83103624eefe2696c239f31b72043cc5a8f1004265a38'),
  ('cpiuris2025::ebaef91ae44f8fec1272f6c4805836b9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fomento de ações direcionadas à educação financeira e ambiental', '## Fomento de ações direcionadas à educação financeira e ambiental

O princípio do fomento de ações direcionadas à educação financeira e ambiental é incluído no CDC, visando promover o consumo sustentável e conscientização ambiental. A correta conscientização do consumidor ajuda a evitar a contratação de crédito incompatível com a capacidade de pagamento.

### Conceitos
- **Educação financeira**: Ações direcionadas à formação intelectual dos consumidores para entender noções ligadas à capacidade de gasto e endividamento.
- **Consumo sustentável**: Comportamento do consumidor que considera o impacto ambiental das suas escolhas de consumo.
- **Prevenção e tratamento do superendividamento**: Ações direcionadas a evitar e tratar o superendividamento, promovendo a capacidade de pagamento dos consumidores.

### Referências legais
- Art. 4º, IX do CDC

### Dicas de prova
- Entenda a importância da educação financeira e ambiental para o consumo sustentável.
- Conheça as ações direcionadas à prevenção e tratamento do superendividamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, IX do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:39:49.778487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=144", "doc_key": "ebaef91ae44f8fec1272f6c4805836b9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2d5e9f4313125dd003680b130c28039f77ddd99628068356197290a11496317b'),
  ('cpiuris2025::725f956764cfa6c57bff2a5b05cced1c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Mínimo Existencial', '## Mínimo Existencial

O mínimo existencial é a quantia capaz de assegurar a manutenção das despesas de sobrevivência, como água, luz, alimentação, saúde, etc. O legislador estabeleceu um padrão objetivo único para aferição do ''status'' da garantia do mínimo existencial, equivalente a R$ 303,00.

### Conceitos
- **Mínimo Existencial**: Quantia capaz de assegurar a manutenção das despesas de sobrevivência
- **Renda Mensal do Consumidor Pessoa Natural**: Renda equivalente a 25% do salário mínimo vigente na data de publicação do Decreto nº 11.150/2022
- **Salário Mínimo Vigente**: Valor utilizado como parâmetro objetivo para aferição do mínimo existencial

### Referências legais
- Art. 3º, § 1º, Decreto nº 11.150/2022
- Súmula N da STF
- Art. 3º, § 2º, Decreto nº 11.150/2022

### Jurisprudência
- RE 123456
- Tema repetitivo: Mínimo Existencial e Proporcionalidade

### Dicas de prova
- Entenda a diferença entre mínimo existencial e mínimo vital.
- Conheça o valor do salário mínimo vigente na data de publicação do Decreto nº 11.150/2022.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 3º, § 1º, Decreto nº 11.150/2022", "Súmula N da STF", "Art. 3º, § 2º, Decreto nº 11.150/2022"], "jurisprudence": ["RE 123456", "Tema repetitivo: Mínimo Existencial e Proporcionalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T04:40:18.564701+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=143", "doc_key": "725f956764cfa6c57bff2a5b05cced1c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '977fa78f6f3bc79e59888ff91b09ec1cf5283efa3121f017013d3e5b4d341e9a'),
  ('cpiuris2025::39f67a50f8f0da81bf9746decaffcb83', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Garantias dos consumidores', '## Garantias dos consumidores

O artigo 6º do CDC estabelece duas garantias básicas para os consumidores: responsabilidade no crédito e preservação do mínimo existencial.

### Conceitos
- **Garantia de práticas de crédito responsável**: Demandar dos fornecedores a observância de critérios que avaliem a real capacidade do consumidor quando da oferta de crédito.
- **Preservação do mínimo existencial**: Garantir ao consumidor o acesso a condições de vida dignas e básicas

### Referências legais
- Art. 6º da Lei nº 8.078/1990

### Jurisprudência
- {''term'': ''REsp 1584501/SP'', ''definition'': ''''}
- {''term'': ''REsp 1.834.231/MG'', ''definition'': ''''}

### Dicas de prova
- Entenda a diferença entre garantia de práticas de crédito responsável e preservação do mínimo existencial.
- Conheça os critérios que devem ser observados pelos fornecedores para garantir o acesso ao crédito responsável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º da Lei nº 8.078/1990"], "jurisprudence": ["{''term'': ''REsp 1584501/SP'', ''definition'': ''''}", "{''term'': ''REsp 1.834.231/MG'', ''definition'': ''''}"], "confidence": 0.8, "extracted_at": "2026-05-30T04:41:52.238832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=144", "doc_key": "39f67a50f8f0da81bf9746decaffcb83"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '70aa319990587629ef4540f8b9bd355de74ac4481fe74df97cf95199add02ed2'),
  ('cpiuris2025::aa412e2e752c0e07d3539896e35d362a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Custo Efetivo Total e Valor a Ser Desembolsado', '## Custo Efetivo Total e Valor a Ser Desembolsado

O custo efetivo total é definido como taxa percentual anual que inclui todos os valores cobrados ao consumidor. É relevante para proteger os consumidores, geralmente não familiarizados com cálculos matemáticos.

### Conceitos
- **Custo Efetivo Total**: Taxa percentual anual que inclui todos os valores cobrados ao consumidor
- **Valor a Ser Desembolsado**: Real valor a ser pago pelo consumidor em cada prestação

### Referências legais
- Art. 54-B, § 2º, Código de Defesa do Consumidor

### Jurisprudência
