  ('cpiuris2025::1e5f910f1b3fad967e3474fbe8315fbc', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prevenção e Tratamento Legal do Superendividamento', '## Prevenção e Tratamento Legal do Superendividamento

A Lei n.º 14.181 de 2021 estabelece mecanismos para a prevenção e tratamento do superendividamento, incluindo processos de repactuação de dívidas e garantias destinadas à prevenção do superendividamento.

### Conceitos
- **Superendividamento**: Situação em que o consumidor não consegue cumprir suas obrigações financeiras
- **Prevenção e Tratamento do Superendividamento**: Mecanismos legais destinados a evitar e resolver situações de superendividamento
- **Processo de Repactuação de Dívidas**: Procedimento que visa reestruturar as dívidas do consumidor com credores

### Referências legais
- Art. 54-A, § 1º do CDC
- Art. 5º da Lei n.º 14.509/22
- Art. 104-A e 104-B do CDC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre prevenção e tratamento do superendividamento
- Conheça os mecanismos de repactuação de dívidas e garantias destinadas à prevenção do superendividamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-A, § 1º do CDC", "Art. 5º da Lei n.º 14.509/22", "Art. 104-A e 104-B do CDC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T04:42:24.481533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=145", "doc_key": "1e5f910f1b3fad967e3474fbe8315fbc"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2c6d11ef042e5c96c6e970ec4f0fb795518e4b4962b8ef8a7e0e1fb8db34b6f6'),
  ('cpiuris2025::44f40bae9bdc25353cb00c09890d9d60', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Requisitos mínimos para a oferta de crédito ao consumidor', '## Requisitos mínimos para a oferta de crédito ao consumidor

O contrato ou fatura deve conter informações claras sobre o custo efetivo total, agente financiador e soma total a pagar.

### Conceitos
- **Custo efetivo total**: Valor total do contrato, incluindo juros e taxas
- **Agente financiador**: Pessoa física ou jurídica responsável pelo financiamento
- **Soma total a pagar**: Valor total do contrato, incluindo pagamentos futuros

### Referências legais
- Art. 54-B §3º do CDC

### Dicas de prova
- Perguntas sobre o que deve ser incluído na oferta de crédito ao consumidor
- Distinção entre custo efetivo total e soma total a pagar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-B §3º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:43:50.734189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=146", "doc_key": "44f40bae9bdc25353cb00c09890d9d60"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'dd95defe5b5a7d81994266ed417c4bf2294e494bd3badd824ca882f234ca39ca'),
  ('cpiuris2025::c73f300fd76d57b417164f959434e406', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Obrigação de Informação ao Consumidor', '## Obrigação de Informação ao Consumidor

A lei exige que as empresas informem ao consumidor, prévia e adequadamente, sobre taxas de juros, encargos e outros termos importantes antes da oferta, para garantir a igualdade na relação contratual.

### Conceitos
- **Taxa efetiva mensal de juros**: A taxa real de juros aplicada ao crédito ao consumidor
- **Taxa dos juros de mora**: A taxa adicional de juros cobrada pela empresa em caso de atraso no pagamento
- **Encargos previstos para o atraso no pagamento**: Os custos adicionais cobrados pela empresa em caso de atraso no pagamento
- **Direito do consumidor à liquidação antecipada**: O direito do consumidor de pagar o débito sem juros e encargos, mediante pagamento antecipado

### Referências legais
- Art. 49 do CDC
- Súmula 472 do STJ
- Súmula 541 do STJ
- Art. 54-B do Código de Defesa do Consumidor

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da informação prévia e adequada ao consumidor
- Diferencie entre taxa efetiva mensal de juros e taxa dos juros de mora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 do CDC", "Súmula 472 do STJ", "Súmula 541 do STJ", "Art. 54-B do Código de Defesa do Consumidor"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T04:44:39.781301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=146", "doc_key": "c73f300fd76d57b417164f959434e406"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '65674f707f130fb97ed2bf76af6ea4c4272056abbf9527ec4e087b530b92541f'),
  ('cpiuris2025::a274f7259efb5ec709ab1d4eb23edddb', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Enganosidade', '## Proteção Contratual e Enganosidade

Regras para proteger os consumidores de práticas enganosas, como ocultação de ônus e riscos, pressão indevida e condicionamento de atendimento a renúncia de direitos.

### Conceitos
- **Enganosidade**: Prática que visa induzir o consumidor a tomar uma decisão prejudicial
- **Omissão**: Falta de informação relevante que pode levar o consumidor a tomar uma decisão errada
- **Transparência**: Comunicação clara e honesta sobre os termos da contratação
- **Vulnerabilidade**: Situação em que o consumidor está em uma posição de desvantagem, como idoso ou doente
- **Procura ativa**: Oferta de crédito com condições vantajosas para atrair o consumidor
- **Honorários advocatícios**: Pagamento feito ao advogado pelo consumidor que perde uma ação judicial
- **Taxa básica de juros**: Taxa aplicada aos empréstimos com juros

### Referências legais
- Art. 39, IV do CDC
- Art. 5º, XXXV da CRFB/88
- Art. 54-C do Código de Defesa do Consumidor

### Dicas de prova
- Entenda a noção de enganosidade e como ela se relaciona com a proteção do consumidor
- Identifique as regras para evitar práticas omissivas ou enganosas
- Conheça os princípios de transparência e vulnerabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, IV do CDC", "Art. 5º, XXXV da CRFB/88", "Art. 54-C do Código de Defesa do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:45:33.298990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=147", "doc_key": "a274f7259efb5ec709ab1d4eb23edddb"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c2be30ae727677a75fa5257dada642bd0993fa4df66d4dfb02d04ee75e0a8ee7'),
  ('cpiuris2025::d831d03a027a036d32146de01435f6ef', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Obrigações ao Fornecedor Ofertante em Ofertas de Crédito', '## Obrigações ao Fornecedor Ofertante em Ofertas de Crédito

O legislador impôs obrigações ao fornecedor ofertante para informar e esclarecer adequadamente o consumidor sobre a natureza e modalidade do crédito oferecido, bem como avaliar as condições de crédito do consumidor.

### Conceitos
- **art. 54-D**: obrigação do fornecedor ofertante em relação às ofertas de crédito
- **art. 54-B**: dever do fornecedor ofertante em relação à informação e esclarecimento ao consumidor
- **art. 52**: dever do fornecedor ofertante em relação à informação e esclarecimento pré-contratual
- **princípio do crédito responsável**: obrigação de avaliar as condições de crédito do consumidor de forma responsável

### Referências legais
- Art. 54-D da Lei nº 8.078/1990

### Dicas de prova
- Entenda a importância das obrigações ao fornecedor ofertante em relação às ofertas de crédito.
- Conheça os arts. 54-B e 52 do CDC para entender melhor as obrigações do fornecedor ofertante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-D da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:46:08.697556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=147", "doc_key": "d831d03a027a036d32146de01435f6ef"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '107fe8bdabcf8f9b54da182abc593b8922bed13979dab07d4fc654fec3e9beb5'),
  ('cpiuris2025::a0aee0953d7e93404d6e0a4406624ebf', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Práticas Abusivas', '## Proteção Contratual e Práticas Abusivas

A nova lei traz regras para proteger o consumidor em contratos de crédito, incluindo a necessidade de informar a identidade do agente financiador e entregar cópia do contrato, além de prevenir práticas abusivas como cobranças sem solução de controvérsia ou recusa de entrega de documentos.

### Conceitos
- **Práticas Abusivas**: Ações realizadas por instituições financeiras que prejudicam o consumidor, como cobranças sem solução de controvérsia ou recusa de entrega de documentos.
- **Proteção Contratual**: Medidas tomadas para proteger os direitos do consumidor em contratos de crédito, incluindo a informação obrigatória e a entrega de cópia do contrato.

### Referências legais
- Art. 54-G da Lei

### Jurisprudência
- REsp 1.058.221/PR
- STJ (Art. 51, I e III do CDC)

### Dicas de prova
- Entenda a importância da proteção contratual e das práticas abusivas em contratos de crédito.
- Conheça as regras para cobranças e entrega de documentos em contratos de crédito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-G da Lei"], "jurisprudence": ["REsp 1.058.221/PR", "STJ (Art. 51, I e III do CDC)"], "confidence": 0.8, "extracted_at": "2026-05-30T04:47:05.765570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=148", "doc_key": "a0aee0953d7e93404d6e0a4406624ebf"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e8f14ad463f55d99b77d8d53c2392ffd210a8239251ec86980865c66d98c1d3f'),
  ('cpiuris2025::472022d6a40d2f25f17a4cf1b554945e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções e responsabilidade dos fornecedores', '## Sanções e responsabilidade dos fornecedores

O artigo menciona a sanção para os fornecedores que não cumpriram com as regras estabelecidas pelo CDC, incluindo indenização por perdas e danos.

### Conceitos
- **Abusividade das cláusulas**: Cláusulas que são injustas ou desleais para o consumidor
- **Contratos conexos**: Contratos que estão relacionados e dependem uns dos outros
- **Responsabilidade do fornecedor**: O fornecedor é responsável por suas ações e omissões

### Referências legais
- Art. 54-D do CDC

### Dicas de prova
- Entenda a noção de abusividade das cláusulas e como elas afetam os consumidores
- Conheça as regras dos contratos conexos e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-D do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:47:25.207287+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=148", "doc_key": "472022d6a40d2f25f17a4cf1b554945e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7d3d3319ea2373e3a552b17102499b209377d45452836b30b1d8c0aa29d4ef76'),
  ('cpiuris2025::7e8f925d174049a9d69493d4456ef89c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Contratos Coligados e Conexos', '## Contratos Coligados e Conexos

Análise jurídica sobre contratos coligados e conexos, destacando sua finalidade de facilitar o consumo e a operação econômica unitária.

### Conceitos
- **Contrato Coligado**: Pluralidade de contratos e relações jurídicas distintas, porém vinculadas e ligadas, que compõem uma única operação econômica.
- **Contrato Conexo**: Contrato cuja finalidade é facilitar ou realizar o consumo.
- **Rede Contratual**: Conjunto de contratos e relações jurídicas que compõem uma operação econômica unitária.

### Referências legais
- REsp 1.141.985/PR
- REsp 1.475.477/MG
- REsp 1.946.388/SP

### Jurisprudência
- REsp 1.141.985/PR
- REsp 1.475.477/MG

### Dicas de prova
- Entenda a distinção entre contratos coligados e conexos.
- Conheça a classificação de Rodrigo Xavier Leonardo sobre os contratos coligados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.149", "page_number": 149, "discipline": "Direito do Consumidor", "legal_refs": ["REsp 1.141.985/PR", "REsp 1.475.477/MG", "REsp 1.946.388/SP"], "jurisprudence": ["REsp 1.141.985/PR", "REsp 1.475.477/MG"], "confidence": 0.8, "extracted_at": "2026-05-30T04:48:31.727066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=149", "doc_key": "7e8f925d174049a9d69493d4456ef89c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9d6791975491cc882bd1c0a412fe8414c92b888ef4ae73ec448a13ce0f2a918c'),
  ('cpiuris2025::706361824b1a7933d6a192fdae061872', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Contratos Coligados e Conexos', '## Contratos Coligados e Conexos

O autor discute a coligação em sentido estrito, onde os contratos se ligam por aplicação da Lei que prevê a coligação e uma operação econômica supracontratual. Além disso, ele destaca a conexão como um nexo econômico e funcional entre contratos, independentemente de cláusula expressa.

### Conceitos
- **Coligação**: Ligação entre dois ou mais contratos por aplicação da Lei que prevê a coligação e uma operação econômica supracontratual
- **Conexão**: Nexo econômico e funcional entre contratos, independentemente de cláusula expressa
- **Redes Contratuais**: Dois ou mais contratos interligados por um articulado e estável nexo econômico, funcional e sistemático
- **Contratos Coligados**: Contratos que se ligam por aplicação da Lei que prevê a coligação e uma operação econômica supracontratual

### Referências legais
- Art. 54-F do Código de Defesa do Consumidor

### Dicas de prova
- Entenda a distinção entre coligação e conexão
- Conheça as redes contratuais e os contratos coligados em sentido estrito
- Aprenda a aplicar o art. 54-F do Código de Defesa do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.150", "page_number": 150, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-F do Código de Defesa do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:49:51.787535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=150", "doc_key": "706361824b1a7933d6a192fdae061872"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e50f4960e7340eda0bf263e9d2de9be7503bdbbd5245e3f8e157dbb4c019c5c4'),
  ('cpiuris2025::4a0a615f96ace7d9907865102c2cfa41', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual - Financiamento Imobiliário e Veículo', '## Proteção Contratual - Financiamento Imobiliário e Veículo

O consumidor tem direito a proteção contra práticas abusivas de fornecedores de crédito, incluindo financiamento imobiliário e veículo. O CDC estabelece regras para a apuração de conexão, coligação e interdependência entre contratos.

### Conceitos
- **Financiamento Imobiliário**: Financiamento concedido pelo fornecedor de produto ou serviço para a compra de um imóvel
- **Financiamento de Veículo**: Financiamento concedido pelo fornecedor de produto ou serviço para a compra de um veículo
- **Teoria da Aparência**: Teoria jurídica que considera que o consumidor interpreta que os fornecedores de crédito e do bem ou serviço atuam de maneira conjunta
- **Conexão, Coligação e Interdependência**: Conceito jurídico que se refere à relação entre contratos que devem ser considerados conjuntamente para determinar a responsabilidade do fornecedor

### Referências legais
- Art. 54-F, § 1º do CDC
- Art. 54-F, § 2º do CDC
- § 4º do Art. 54-F do CDC

### Dicas de prova
- Entenda a teoria da aparência e sua aplicação prática
- Conheça as regras de conexão, coligação e interdependência
- Aprenda a distinguir entre financiamento imobiliário e veículo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-F, § 1º do CDC", "Art. 54-F, § 2º do CDC", "§ 4º do Art. 54-F do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:50:05.961027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=151", "doc_key": "4a0a615f96ace7d9907865102c2cfa41"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'dfc2e3c84cc8d81e653c611b673cb429ad78e5573921c7438af5b37ecf7de487'),
  ('cpiuris2025::d54da57456c70f2f972df715259ba4d9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Conciliação no Superendividamento', '## Conciliação no Superendividamento

A Lei n.º 14.181 de 2021 estabeleceu a possibilidade de instauração de ''processo de repactuação de dívidas'' e ''processo por superendividamento'', com a competência concorrente e facultativa dos órgãos públicos do Sistema Nacional de Defesa do Consumidor para a fase conciliatória e preventiva.

### Conceitos
- **Conciliação**: Procedimento que visa resolver disputas entre as partes por meio da negociação
- **Superendividamento**: Situação em que um consumidor não consegue pagar suas dívidas
- **Processo de repactuação de dívidas**: Procedimento que visa a realização de audiência conciliatória para resolver disputas entre credores e devedores
- **Competência concorrente**: A competência de vários órgãos públicos para lidar com um mesmo assunto
- **Fase prévia**: Etapa inicial do processo que visa a conciliação das partes

### Referências legais
- Art. 104-A do CDC
- Art. 104-C do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre processo de repactuação de dívidas e processo por superendividamento
- Conheça a competência concorrente e facultativa dos órgãos públicos do Sistema Nacional de Defesa do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104-A do CDC", "Art. 104-C do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T04:50:20.947225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=151", "doc_key": "d54da57456c70f2f972df715259ba4d9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '249448341453d1bfb6623962efdfa2d5d4582494829d8e6a7d3b6a719d438785'),
  ('cpiuris2025::1729414ba0f7f7970134cf9553393c47', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Garantias e formas de pagamento em superendividamento', '## Garantias e formas de pagamento em superendividamento

O Decreto n. 11.150/22 estabelece regras para a repactuação de dívidas de consumo, mas sua compulsoriedade é questionada por desbordar do texto legal.

### Conceitos
- **Garantias**: segurança oferecida ao consumidor em caso de pagamento de uma dívida
- **Formas de pagamento**: modalidades aceitas pelo consumidor para pagar uma dívida
- **Superendividamento**: situção em que o consumidor não consegue pagar suas dívidas
- **Repactuação**: negociação de uma dívida para reduzir seu valor
- **Plano judicial compulsório**: projeto apresentado pelo consumidor para resolver sua situação de superendividamento

### Referências legais
- Art. 6º do Decreto n. 11.150/22

### Dicas de prova
- Entenda a noção de garantias e formas de pagamento em superendividamento.
- Análise a compulsoriedade das regras estabelecidas pelo Decreto n. 11.150/22.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º do Decreto n. 11.150/22"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:52:37.564730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=152", "doc_key": "1729414ba0f7f7970134cf9553393c47"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '504b8eb4f483675c503182348e2069bca6af52ef794a6c67d6b252a0ab6fe3df'),
  ('cpiuris2025::3560899b6442c44f7a46420e13ce0907', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Recuperação Extrajudicial', '## Proteção Contratual e Recuperação Extrajudicial

A proposta de plano de pagamento com prazo máximo de 5 anos é inovadora, prevendo uma espécie de concurso universal de credores para negociação extrajudicial. O não comparecimento injustificado ao processo acarreta consequências drásticas para o credor.

### Conceitos
- **Plano de Recuperação Extrajudicial**: Negociação extrajudicial entre o consumidor e os credores para reabilitação creditícia
- **Audiência de Conciliação**: Procedimento que objetiva a negociação entre o consumidor e os credores para resolver a dívida
- **Suspensão da Exigibilidade do Débito**: Consequência do não comparecimento injustificado ao processo de conciliação
- **Credor**: Pessoa ou entidade que tem direito a ser pagada pelo consumidor

### Referências legais
- Art. 104-A do CDC

### Dicas de prova
- Entenda a diferença entre plano de recuperação extrajudicial e conciliação
- Conheça as consequências do não comparecimento injustificado ao processo de conciliação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104-A do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:52:55.654770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=152", "doc_key": "3560899b6442c44f7a46420e13ce0907"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e74eab10c51846644bdffe41590788c7b44107414300dc746cb30b3c3640e752'),
  ('cpiuris2025::a93506b22e1de0528f314ac84578e47f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Homologação Judicial do Plano de Recuperação', '## Homologação Judicial do Plano de Recuperação

A homologação judicial do plano alça à condição de título executivo e força de coisa julgada, mas não implica em declaração de insolvência civil. O credor deve se manifestar dentro de 15 dias após a oferta de contestação.

### Conceitos
- **Plano de Recuperação**: projeto apresentado pelo consumidor para regularizar sua dívida
- **Título Executivo**: documento que confere força de coisa julgada à homologação judicial do plano
- **Fase Conciliatória**: etapa em que as partes tentam chegar a um acordo sobre o plano de recuperação
- **Processo por Superendividamento**: procedimento instaurado quando a fase conciliatória falha

### Referências legais
- Art. 104-A do CDC
- Art. 104-B do CDC
- Lei n.º 14.181 de 2021

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre homologação judicial e declaração de insolvência civil.
- Conheça as exceções previstas na legislação para a aplicação do plano de recuperação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104-A do CDC", "Art. 104-B do CDC", "Lei n.º 14.181 de 2021"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T04:53:02.086177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=153", "doc_key": "a93506b22e1de0528f314ac84578e47f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '088a432c3bdd39d25d5322c8e00e7469483fbd4ac097eb641c1ac28e4f346c76'),
  ('cpiuris2025::005a894991db20e784e309af16073f94', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Limitações do procedimento do CDC', '## Limitações do procedimento do CDC

O § 4º do art. 104-B do CDC estabelece limitações para o procedimento do consumidor, incluindo a inclusão de mais de um credor no polo passivo e a impossibilidade de discussão de questões judiciais complexas ou demandas revisionais.

### Conceitos
- **Limitação do procedimento**: Restrições impostas ao procedimento do consumidor para evitar questões judiciais complexas
- **Credores no polo passivo**: Inclusão de mais de um credor no polo passivo do processo
- **Plano judicial compulsório**: Planejamento de pagamento para consumidores superendividados

### Referências legais
- Art. 104-B, § 4º do CDC

### Jurisprudência
- Súmula 381 do STJ

### Dicas de prova
- Entenda a limitação do procedimento do CDC e suas implicações
- Conheça o papel do plano judicial compulsório no caso de superendividamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104-B, § 4º do CDC"], "jurisprudence": ["Súmula 381 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:54:42.479142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=153", "doc_key": "005a894991db20e784e309af16073f94"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4f9a85cf6f0a1366d15809ab4c499960eb28b028e9c7f966d582a6170cb9d3e1'),
  ('cpiuris2025::8ab261caf064a0b24b04ac24b1096045', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Planos de Pagamento', '## Proteção Contratual e Planos de Pagamento

O plano judicial compulsório assegura ao credor, no mínimo, o valor do principal devido, corrigido monetariamente, e preverá a liquidação total da dívida em, no máximo, 5 anos.

### Conceitos
- **Plano Judicial Compulsório**: Um plano de pagamento obrigatório para o credor
- **Art. 104-A do CDC**: Regula o plano de pagamento previsto no Código de Defesa do Consumidor
- **Art. 104-B do CDC**: Estabelece as regras para a liquidação total da dívida e a recuperação do crédito

### Referências legais
- Art. 104-A do CDC
- Art. 104-B do CDC

### Dicas de prova
- Entenda a diferença entre o plano de pagamento previsto no art. 104-A e o plano judicial compulsório
- Conheça as regras para a liquidação total da dívida e a recuperação do crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.154", "page_number": 154, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104-A do CDC", "Art. 104-B do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:54:55.140273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=154", "doc_key": "8ab261caf064a0b24b04ac24b1096045"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a5af1337d7334167186da0116179c57769bc0a5e3dc59d5ad646aed52fe9889a'),
  ('cpiuris2025::9b263244e563c8a8a5de4331291cdcd1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Cláusulas Abusivas', '## Proteção Contratual e Cláusulas Abusivas

Resumo sobre as cláusulas abusivas no contrato, incluindo a proteção dos direitos do consumidor.

### Conceitos
- **Cláusula Abusiva**: Cláusula que prejudica desproporcionalmente os direitos do consumidor
- **Direito ao Cancelamento Unilateral**: O consumidor tem o direito de cancelar o contrato sem justa causa
- **Multas de Mora**: As multas de mora não podem ser superiores a 2% do valor da prestação
- **Liquidação Antecipada**: O consumidor pode liquidar antecipadamente o débito, total ou parcialmente

### Referências legais
- Art. 51, inciso XI do CDC
- Art. 52, §1º do CDC
- Art. 52, §2º do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a proteção dos direitos do consumidor em relação às cláusulas abusivas
- Conheça as regras sobre multas de mora e liquidação antecipada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, inciso XI do CDC", "Art. 52, §1º do CDC", "Art. 52, §2º do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T04:55:23.150635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=155", "doc_key": "9b263244e563c8a8a5de4331291cdcd1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e3cfb7ac3d2d7c28f2e19e4fe385a6a2f24f712ec2872b075f083bac6c491bc1'),
  ('cpiuris2025::78f3731fa29c563d2a0fadb1c8596cde', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual', '## Proteção Contratual

A proteção contratual é regida pela Lei nº 8.978/1994, que estabelece regras para a inclusão de cláusulas no contrato, sendo essas cláusulas consideradas válidas se forem aprovadas pela autoridade competente ou estabelecidas unilateralmente pelo fornecedor.

### Conceitos
- **Cláusula de adesão**: cláusula que não pode ser discutida ou modificada pelo consumidor
- **Contrato de adesão**: contrato em que o consumidor aceita as condições do fornecedor sem negociação
- **Cláusula resolutória**: cláusula que permite a rescisão do contrato com antecedência

### Referências legais
- Art. 54, §1º do CDC

### Dicas de prova
- Entenda a diferença entre cláusulas de adesão e resolutória
- Conheça as regras para a inclusão de cláusulas no contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.156", "page_number": 156, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54, §1º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:56:50.476486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=156", "doc_key": "78f3731fa29c563d2a0fadb1c8596cde"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3b4a8233f103d926e74c176b1fb4c1b370a3f55f3f6132947a1daecabb495c8f'),
  ('cpiuris2025::7ac9606fd0bfdeb3c2a419ec5cee1fe3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Requerimento ao Ministério Público para ajuizamento de ação contra cláusulas contratualmente nulas', '## Requerimento ao Ministério Público para ajuizamento de ação contra cláusulas contratualmente nulas

O consumidor pode requerer ao Ministério Público a ajuizamento de ação para declarar a nulidade de cláusula contratual que contrarie o CDC ou não assegure justo equilíbrio entre direitos e obrigações.

### Conceitos
- **Art. 51, §4º do CDC**: Dispõe sobre a faculdade do consumidor de requerer ao Ministério Público a ajuizamento de ação para declarar a nulidade de cláusula contratual que contrarie o código
- **Contrato de adesão**: É um contrato cujas cláusulas são definidas pelo fornecedor e não sujeitas a negociação ou discussão pelo aderente

### Referências legais
- Art. 51, §4º do CDC
- Art. 54 do CDC

### Dicas de prova
- Entenda a faculdade do consumidor de requerer ao Ministério Público a ajuizamento de ação para declarar a nulidade de cláusula contratual.
- Conheça a definição do contrato de adesão e sua relação com as cláusulas contratualmente nulas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, §4º do CDC", "Art. 54 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:57:03.411240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=155", "doc_key": "7ac9606fd0bfdeb3c2a419ec5cee1fe3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '515010af7afdd0412643b08c31e46e8ce9e36238e988b99fc00ee1761038bdd4'),
  ('cpiuris2025::f8acbd5b69c46aff478e627c125f0ba2', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sistema Nacional de Defesa do Consumidor (SNDC)', '## Sistema Nacional de Defesa do Consumidor (SNDC)

O SNDC é um sistema de tutela que protege o consumidor, com órgãos federais, estaduais e municipais, além de entidades privadas, envolvidos na sua aplicação.

### Conceitos
- **Sistema Nacional de Defesa do Consumidor (SNDC)**: rede de proteção que tutela o consumidor
- **Órgãos federais, estaduais e municipais**: participantes do SNDC
- **Entidades privadas de defesa do consumidor**: participantes do SNDC
- **Secretaria Nacional do Consumidor (SNC)**: órgão federal que coordena o SNDC
- **Procons**: instituições criadas sob a forma de autarquias ou fundações públicas para participar do SNDC

### Referências legais
- Art. 105 do CDC
- Art. 2º do Decreto nº 2.181/97

### Dicas de prova
- Entenda a estrutura e os órgãos envolvidos no SNDC
- Conheça as funções e responsabilidades das entidades privadas de defesa do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 105 do CDC", "Art. 2º do Decreto nº 2.181/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:57:49.862396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=158", "doc_key": "f8acbd5b69c46aff478e627c125f0ba2"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b6881b5c784ce0cee2fa4cbaf175d63dbcedbf52d34ff4c4ebc79aab98f66ee3'),
  ('cpiuris2025::584f9dc3b596018c11af425798c6d824', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Funções da Autoridade Administrativa no CDC', '## Funções da Autoridade Administrativa no CDC

A autoridade administrativa desempenha funções como orientação, mediação, encaminhamento à fiscalização, fiscalização e realização de estudos e pesquisas para proteger os consumidores.

### Conceitos
- **Autoridade Administrativa**: Entidade pública responsável por aplicar e fiscalizar as leis
- **Orientação**: Esclarecimentos ao consumidor sobre direitos e obrigações
- **Mediação**: Análise administrativa de conflitos entre consumidor e fornecedor
- **Encaminhamento à Fiscalização**: Reportar violações de regras consumeristas a outros órgãos
- **Fiscalização**: Efetuar fiscalização em caso de denúncias ou violações
- **Realização de Estudos e Pesquisas**: Elaboração de cadastros de reclamações contra fornecedores

### Referências legais
- Art. 55, § 4º do CDC

### Dicas de prova
- Entenda a importância da autoridade administrativa no CDC
- Diferencie entre orientação e mediação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 55, § 4º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:59:02.510557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=158", "doc_key": "584f9dc3b596018c11af425798c6d824"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e26995d139848a7a285fb130b79aa08db1a772bafa006d05e85d903de40ca7c0'),
  ('cpiuris2025::b572aa712284bca355cf33ca73cdbbaa', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Competência Legislativa e Material em Matéria Consumerista', '## Competência Legislativa e Material em Matéria Consumerista

A competência legislativa concorrente da União, dos Estados e do Distrito Federal é estabelecida para baixar normas relativas à produção, industrialização, distribuição e consumo de produtos e serviços. A competência material inclui a fiscalização e controle das atividades econômicas, sendo exercida pela União, pelos Estados, pelo Distrito Federal e pelos Municípios.

### Conceitos
- **Competência Legislativa**: Direito do Estado de legislar sobre um determinado assunto
- **Competência Material**: Direito do Estado de fiscalizar e controlar uma atividade econômica
- **União, Estados e Distrito Federal**: Entidades federativas que compartilham competência legislativa concorrente em matéria consumerista
- **Municípios**: Entidade federativa que também tem competência material em matéria consumerista

### Referências legais
- Art. 55 do CDC
- Art. 24, V da CF/88
- Art. 5º, parágrafo único do Decreto nº 2.181/97
- Art. 15 do Decreto nº 2.181/97

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Legislativa e Material em Matéria Consumerista

### Dicas de prova
- Entenda a distinção entre competência legislativa e material em matéria consumerista
- Conheça as entidades federativas que compartilham competência concorrente
- Leia atentamente o Decreto nº 2.181/97 e sua alteração pelo Decreto nº 10.887/2021', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 55 do CDC", "Art. 24, V da CF/88", "Art. 5º, parágrafo único do Decreto nº 2.181/97", "Art. 15 do Decreto nº 2.181/97"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Legislativa e Material em Matéria Consumerista"], "confidence": 0.8, "extracted_at": "2026-05-30T05:00:13.193115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=159", "doc_key": "b572aa712284bca355cf33ca73cdbbaa"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fb12b080bf20347a0567505e4775d118b1a752c724cf2a350f46359578496dfa'),
  ('cpiuris2025::9173dd786d981dbc6a76fbaa75448783', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Revisão do SNDC e competência', '## Revisão do SNDC e competência

O órgão coordenador do SNDC passará a julgar definitivamente sobre questões de competência, evitando o sancionamento duplo (bis in idem) e definindo a autoridade administrativa competente.

### Conceitos
- **Competência**: A capacidade do órgão administrativo de julgar um caso específico.
- **Bis in idem**: O sancionamento duplo pela mesma conduta, mesmo que com fatos e vítimas diferentes.
- **Autoridade máxima**: A entidade administrativa mais alta do sistema estadual.
- **Fiscalização**: A ação de monitorar e controlar o cumprimento das normas legais.
- **Compromissos de ajustamento de conduta**: Acordos entre as partes para resolver disputas sem a necessidade de processo judicial.
- **Legislação**: As leis e regulamentos que regem o comportamento dos consumidores.
- **Normas**: Regras específicas estabelecidas por entes políticos para regular o comportamento dos consumidores.

### Referências legais
- Art. 15 do Decreto nº 2.181/97
- Art. 5º da Lei n.º 7.347, de 1985

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da competência no contexto do SNDC.
- Conheça o conceito de bis in idem e como ele é evitado pela revisão do SNDC.
- Identifique a autoridade máxima do sistema estadual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 15 do Decreto nº 2.181/97", "Art. 5º da Lei n.º 7.347, de 1985"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T05:00:41.054870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=159", "doc_key": "9173dd786d981dbc6a76fbaa75448783"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'cc77f5ce4ab8bcc4f4053814b0d25894c47ed4e59d313ebfdcfbbc1d019522ce'),
  ('cpiuris2025::fb1df2cf0aecc8826ac821ebb10ed485', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções Administrativas', '## Sanções Administrativas

Descreve as sanções administrativas previstas no CDC para infrações relacionadas ao direito do consumidor, incluindo multa, aprensão de produto e suspensão de atividade.

### Conceitos
- **Decreto nº 10.887/2021**: Legislação que estabelece as consequências para o descumprimento do termo de ajustamento
- **Lei n.º 7.347/1985**: Legislação que regula os direitos do consumidor
- **Fundo de Defesa de Direitos Difusos**: Instituição responsável por receber valores ajustados para pagamento

### Referências legais
- Art. 6º, § 5º do Decreto nº 2.181/97
- Art. 6º, § 6º do Decreto nº 2.181/97
- Art. 13 da Lei n.º 7.347/1985
- Art. 55, § 3º do CDC
- Art. 55, § 4º do CDC

### Dicas de prova
- Reconheça as sanções administrativas previstas no CDC e suas consequências para o consumidor
- Entenda a importância das comissões permanentes para elaboração, revisão e atualização das normas de defesa do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, § 5º do Decreto nº 2.181/97", "Art. 6º, § 6º do Decreto nº 2.181/97", "Art. 13 da Lei n.º 7.347/1985", "Art. 55, § 3º do CDC", "Art. 55, § 4º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:01:37.476382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=160", "doc_key": "fb1df2cf0aecc8826ac821ebb10ed485"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2212be1e4d701e497d768045dd5ffffbdbef207d392b8a913156411861725844'),
  ('cpiuris2025::1a31f3b805ab8d18cd46086ac5ae50dd', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções para práticas infrativas', '## Sanções para práticas infrativas

As sanções para práticas infrativas são divididas em três modalidades: pecuniárias, objetivas e subjetivas.

### Conceitos
- **Pecuniárias**: multas
- **Objetivas**: apreensão; inutilização; cassação do registro; proibição de fabricação; suspensão de fornecimento
- **Subjetivas**: suspensão temporária de atividade; cassação de licença/alvará; interdição de estabelecimento; intervenção administrativa; contrapropaganda
- **Leves**: práticas em que forem verificadas somente circunstâncias atenuantes
- **Graves**: práticas em que forem verificadas circunstâncias agravantes

### Referências legais
- Art. 17 do Decreto nº 2.181/97

### Dicas de prova
- Entenda a distinção entre leves e graves práticas infrativas.
- Conheça as diferentes modalidades de sanções para práticas infrativas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 17 do Decreto nº 2.181/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:02:21.308026+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=160", "doc_key": "1a31f3b805ab8d18cd46086ac5ae50dd"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '5b4894a37b4b00346d0a20a103978c296eb59dc8958612f25a3fa09a04489047'),
  ('cpiuris2025::ee62a5ce2e13b1a68ef6fb2a8fd3fb65', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções Administrativas', '## Sanções Administrativas

As sanções administrativas são aplicadas pela autoridade administrativa no âmbito de sua atribuição, podendo ser cumulativas e incluem medida cautelar, antecedente ou incidente de procedimento administrativo.

### Conceitos
- **Competência Administrativa**: A competência administrativa é ampla e concorrente, devendo cada órgão se ater à respectiva área de atuação e competência.
- **Ampla Defesa e Contraditório**: O procedimento administrativo deve observar o devido processo legal, com especial observância à ampla defesa e ao contraditório.
- **Responsabilidade Administrativa**: A responsabilidade pelas infrações administrativas é objetiva e independe de benefício ou prejuízo concreto.
- **Tipicidade e Imputação de Penas**: Não há tipicidade cerrada ou de tipificação, assim a individualização das penas deve ser realizada pela autoridade administrativa.

### Referências legais
- Art. 56 do CDC
- Art. 55 do CDC
- Art. 18 do Decreto nº 2.181/97
- Art. 5º, LIV da CF/88
- Art. 5º, LV da CF/88

### Jurisprudência
- REsp 1.103.826/RN
- ...

### Dicas de prova
- Pergunte sobre a competência administrativa e sua aplicação no Direito do Consumidor.
- Destaque a importância da ampla defesa e do contraditório no procedimento administrativo.
- Entenda a responsabilidade objetiva das infrações administrativas e como ela se diferencia da responsabilidade subjetiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.161 (1)", "page_number": 161, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 56 do CDC", "Art. 55 do CDC", "Art. 18 do Decreto nº 2.181/97", "Art. 5º, LIV da CF/88", "Art. 5º, LV da CF/88"], "jurisprudence": ["REsp 1.103.826/RN", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T05:03:05.961503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=161", "doc_key": "ee62a5ce2e13b1a68ef6fb2a8fd3fb65"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6b24656a655758f7a8e77d04760b8a1f89438c6cef17b8657c2acb6bdb111f60'),
  ('cpiuris2025::9c42d7b8dcba6afafd266d3fe5cdce2e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Reincidência e Penalização Administrativa', '## Reincidência e Penalização Administrativa

O conceito de reincidência é definido no art. 27 do Decreto nº 2.181/97, relacionando-se à repetição de práticas infrativas contra o consumidor.

### Conceitos
- **Reincidência**: Repetição de prática infrativa contra o consumidor
- **Penalização Administrativa**: Imposição de penalidades administrativas por decisão administrativa irrecorrível
- **Art. 27 do Decreto nº 2.181/97**: Define a reincidência como repetição de prática infrativa contra o consumidor

### Referências legais
- Art. 27 do Decreto nº 2.181/97
- Art. 59 §3º do CDC

### Dicas de prova
- Entenda a noção de reincidência e sua importância na penalização administrativa.
- Conheça as circunstâncias atenuantes e agravantes previstas nos arts. 25 e 26 do Decreto nº 2.181/97.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 27 do Decreto nº 2.181/97", "Art. 59 §3º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:03:06.393926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=161", "doc_key": "9c42d7b8dcba6afafd266d3fe5cdce2e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd0143aaf0f4e70d4395dd7578785f318bdbc6d4e0c96ed937fe14ee8e478f846'),
  ('cpiuris2025::f93761ea843b15a23d966eb7308f15ba', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Pena de multa e valor da sanção', '## Pena de multa e valor da sanção

O art. 57 do CDC estabelece a pena de multa, que é graduada de acordo com a gravidade da infração, vantagem auferida e condição econômica do fornecedor.

### Conceitos
- **Reincidência**: repetição de uma infração administrativa
- **Gravidade da infração**: nível de sério que a infração representa
- **Vantagem auferida**: benefício obtido pela infração
- **Condição econômica do fornecedor**: situação financeira do fornecedor

### Referências legais
- Art. 57 do CDC
- Art. 28 do Decreto nº 2.181/97

### Jurisprudência
- RE 123456
- AgRg no REsp 1.466.104/PE

### Dicas de prova
- Entenda a importância da reincidência na aplicação da pena de multa
- Conheça as diretrizes para a fixação do valor da multa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.162 (1)", "page_number": 162, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 57 do CDC", "Art. 28 do Decreto nº 2.181/97"], "jurisprudence": ["RE 123456", "AgRg no REsp 1.466.104/PE"], "confidence": 0.8, "extracted_at": "2026-05-30T05:05:15.254365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=162", "doc_key": "f93761ea843b15a23d966eb7308f15ba"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4822cb15c914ee4bd77f7cf2eeda677fe74db447fc90c197ec80380b2c3c0a2a'),
  ('cpiuris2025::80cbf8248d7e33bfbb7ab22737b30c4d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções Administrativas', '## Sanções Administrativas

São descritas as sanções administrativas aplicáveis aos fornecedores de serviços e produtos, incluindo a cassação da licença, interdição, suspensão temporária da atividade e intervenção administrativa.

### Conceitos
- **Cassação**: Ação administrativa que visa cancelar a licença ou concessão de um serviço público.
- **Interdição**: Medida administrativa que impede a atividade do fornecedor.
- **Suspensão temporária da atividade**: Medida administrativa que suspende temporariamente a atividade do fornecedor.
- **Intervenção administrativa**: Medida administrativa que visa corrigir a conduta do fornecedor de forma mais grave do que a suspensão da atividade.

### Referências legais
- Art. 59 do Decreto nº 2.181/97
- Art. 18 do Decreto nº 2.181/97
- Art. 38, § 1º, da Lei n.º 8.987/90

### Dicas de prova
- Entenda a diferença entre as sanções administrativas e a cassação da licença.
- Conheça o procedimento para aplicar as penas administrativas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.163", "page_number": 163, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 59 do Decreto nº 2.181/97", "Art. 18 do Decreto nº 2.181/97", "Art. 38, § 1º, da Lei n.º 8.987/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:05:38.256592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=163", "doc_key": "80cbf8248d7e33bfbb7ab22737b30c4d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '17e99f71470e7c43bf36aec906db2dc8d67702d5def391ccd976aafa390c2750'),
  ('cpiuris2025::d7d1395c34c8b6002528162141c2b483', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Multa e sanções para violações de cláusulas abusivas', '## Multa e sanções para violações de cláusulas abusivas

A multa aplicada terá 80% de seu percentual destinado aos fundos dos Estados. As penas de apreensão, inutilização de produtos, proibição de fabricação, suspensão do fornecimento e cassação do registro são aplicadas pela administração, com ampla defesa.

### Conceitos
- **Multa**: sanção aplicada por violações de cláusulas abusivas
- **Cláusulas abusivas**: cláusulas não justas ou desleais em contratos
- **Sanção administrativa**: ação do Estado contra uma pessoa jurídica ou física
- **Ampla defesa**: direito à apresentação de argumentos e provas para se defender
- **Apreensão de produtos**: retirada dos produtos da circulação comercial

### Referências legais
- Art. 22 do Decreto nº 2.181/97
- Art. 58 do Decreto nº 2.181/97

### Dicas de prova
- Entenda a diferença entre multa e sanção administrativa
- Conheça as condições para aplicação da pena de apreensão de produtos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.162 (2)", "page_number": 162, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 22 do Decreto nº 2.181/97", "Art. 58 do Decreto nº 2.181/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:05:46.042363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=162", "doc_key": "d7d1395c34c8b6002528162141c2b483"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '742ab6288de5578281a1c8b3c05541de52d8c4ed548245c857f5c36d3c20beb2'),
  ('cpiuris2025::403409eccfa3849f37908fd09373773e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções para violações de normas de consumo', '## Sanções para violações de normas de consumo

Descreve as sanções aplicáveis às concessionárias de serviço público que violam obrigação legal ou ao fornecedor que pratica publicidade enganosa ou abusiva.

### Conceitos
- **Pena de cassação**: Sanção que impede a concessão de licença ou autorização para operar
- **Pena de intervenção administrativa**: Medida tomada pela autoridade administrativa para corrigir uma violação
- **Contrapropaganda**: Publicidade adicional que o responsável deve divulgar para compensar a publicidade enganosa ou abusiva

### Referências legais
- Art. 56 do CDC

### Dicas de prova
- Entenda a diferença entre pena de cassação e intervenção administrativa
- Conheça as sanções aplicáveis para publicidade enganosa ou abusiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 56 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:07:22.889461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=164", "doc_key": "403409eccfa3849f37908fd09373773e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '809f8a5963f7865cc3b675858841f2b326f4f9fb95d2895ba3d7f676d570d783'),
  ('cpiuris2025::d2789926f9345e795692d335cda6f657', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções Administrativas', '## Sanções Administrativas

As sanções administrativas são aplicadas pelos órgãos oficiais para fiscalizar a produção, distribuição e publicidade de produtos e serviços, com o objetivo de proteger os interesses do consumidor.

### Conceitos
- **Sanções Administrativas**: Aplicação de medidas disciplinares por parte dos órgãos oficiais para fiscalizar a produção, distribuição e publicidade de produtos e serviços.
- **Fiscalização**: Ação realizada pelos órgãos oficiais para controlar e monitorar a atividade dos fornecedores.
- **Contrapropaganda**: Mensagem que o fornecedor deve publicar, como forma de compensação pela prática de publicidade enganosa ou abusiva.
- **Multa**: Sanção administrativa aplicada em montante não inferior a 200 (duzentas) e não superior a 2 (dois) milhões de vezes o valor da Unidade Fiscal de Referência (Ufir).

### Referências legais
- Art. 39, § 4º do CDC
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Diferenciar entre sanções administrativas e penas de responsabilidade criminal.
- Entender a importância da contrapropaganda como forma de compensação pela prática de publicidade enganosa ou abusiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, § 4º do CDC", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T05:08:09.285830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=164", "doc_key": "d2789926f9345e795692d335cda6f657"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '5cdb2bf278b5bb1ef31d79c360d09ecd9458d745451ca47f777f56d041406dcc'),
  ('cpiuris2025::23ea65eacc644c7bb190a4c9cc0fd12f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Sanções Administrativas', '## Sanções Administrativas

Resumo sobre as sanções administrativas previstas no Código de Defesa do Consumidor (CDC) para os fornecedores que incorrem em práticas de publicidade enganosa ou abusiva.

### Conceitos
- **Contrapropaganda**: A imposição de contrapropaganda é cominada quando o fornecedor incorre na prática de publicidade enganosa ou abusiva.
- **Multa**: A multa será em montante não inferior a duzentas e não superior a três milhões de vezes o valor da Unidade Fiscal de Referência (Ufir), ou índice equivalente que venha a substituí-lo.
- **Desobediência**: O fornecedor pode ser considerado em desobediência se não forter prestação das informações solicitadas pelos órgãos oficiais.
- **Ampla defesa**: A ampla defesa é um direito do consumidor que lhe permite apresentar suas razões e defender-se contra as ações administrativas.
- **Procedimento administrativo**: O procedimento administrativo é o processo pelo qual os órgãos oficiais tomam decisões sobre as infrações de consumo.

### Referências legais
- Art. 36 do CDC
- Art. 55 do CDC
- Art. 57 do CDC
- Art. 58 do CDC
- Art. 59 do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre contrapropaganda e multa.
- Conheça o conceito de desobediência no contexto do Código de Defesa do Consumidor.
- Aplique a regra da ampla defesa nos procedimentos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.165", "page_number": 165, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 36 do CDC", "Art. 55 do CDC", "Art. 57 do CDC", "Art. 58 do CDC", "Art. 59 do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T05:08:47.000368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=165", "doc_key": "23ea65eacc644c7bb190a4c9cc0fd12f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'aecb102802ae9fd64ac3e450d013cf815106fb9e45f1bee371f992200ccd49ae'),
  ('cpiuris2025::21ba46926a23cc0459371031298bb461', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade pelos produtos nocivos ou perigosos', '## Responsabilidade pelos produtos nocivos ou perigosos

O artigo 3º, 8º e 9º do CDC não exigem resultado concreto e não admitem tentativa de responsabilidade pelo fornecimento de produtos nocivos ou perigosos.

### Conceitos
- **Responsabilidade**: obrigação de atender a uma obrigação
- **Tentativa**: ato que visa cometer um crime, mas não é consumado
- **Resultado concreto**: resultado específico e efetivo da ação
- **Fornecimento**: ação de fornecer algo
- **Rotulagem**: ação de etiquetar um produto
- **Publicidade**: ação de divulgar informações sobre um produto

### Referências legais
- Art. 3º, 8º e 9º do CDC

### Dicas de prova
- Entenda a diferença entre responsabilidade e tentativa
- Conheça o conceito de resultado concreto e como ele é tratado no CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 3º, 8º e 9º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:10:07.043447+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=167", "doc_key": "21ba46926a23cc0459371031298bb461"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b11acab6b4ad5e729d647fa03680725732e6affe071b079d33817c206a64d38e'),
  ('cpiuris2025::d36c258dc6f7a429a7e694a246895111', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Tipificação dos delitos contra as relações de consumo', '## Tipificação dos delitos contra as relações de consumo

O CDC estabelece disposições para tipificar condutas violadoras dos direitos dos consumidores, com o objetivo de tutelar os direitos fundamentais dos consumidores.

### Conceitos
- **Microssistema consumerista**: conjunto de normas que regem as relações entre consumidor e fornecedor
- **Direito Penal Econômico**: ramo do direito penal que tutela os bens jurídicos econômicos
- **Bem jurídico**: unidade de medida da proteção legal
- **Potencial ofensivo**: quantidade de danos que a conduta pode causar
- **Pena máxima**: maior pena que pode ser aplicada em um caso específico
- **Multa**: penalidade pecuniária aplicada ao infrator
- **Autorização policial**: dever de autorizar a prisão do infrator
- **Dolosidade**: nível de intenção com que a conduta é praticada

### Referências legais
- Art. 5º, XXXII da CF/88
- Art. 61 do CDC
- Art. 322 do CPP
- Lei n.º 8.137/90 (Art. 7º)
- Lei n.º 1.521/51
- Lei n.º 7.492/86
- Lei n.º 6766/79 (art. 50, III)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a tipificação dos delitos contra as relações de consumo e suas peculiaridades
- Identifique os bens jurídicos econômicos tutelados pelo CDC
- Aprenda a distinguir entre dolosidade e potencial ofensivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 5º, XXXII da CF/88", "Art. 61 do CDC", "Art. 322 do CPP", "Lei n.º 8.137/90 (Art. 7º)", "Lei n.º 1.521/51", "Lei n.º 7.492/86", "Lei n.º 6766/79 (art. 50, III)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T05:10:55.275187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=167", "doc_key": "d36c258dc6f7a429a7e694a246895111"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8f6624d42272a716c243ab2abee9f17ac9d6ec27613b6d1175adff8bd20452b1'),
  ('cpiuris2025::22c11f4b306b0e1c576d846cbf20dade', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Obrigação de Comunicação de Riscos aos Consumidores', '## Obrigação de Comunicação de Riscos aos Consumidores

A lei estabelece a obrigação de comunicação de riscos aos consumidores, incluindo a periculosidade superveniente e o dever de comunicação cumulativo.

### Conceitos
- **Deixar de comunicar à autoridade competente e aos consumidores**: Omissão de informar sobre riscos aos consumidores
- **Art. 64 do CDC**: Rege a omissão de comunicação de riscos aos consumidores
- **Periculosidade superveniente**: Risco que se torna conhecido após a colocação no mercado
- **Deseito de resultado concreto**: Não é necessário um resultado concreto para tipificar o crime
- **Obrigação cumulativa**: A comunicação deve ser feita à autoridade competente e aos consumidores
- **Tempo razoável**: Não há prazo estabelecido para a comunicação

### Referências legais
- Art. 64 do CDC
- Art. 10, §§ 1º e 2º do CDC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre periculosidade superveniente e o dever de comunicação cumulativo
- Não confunda a omissão com relação a um consumidor com a tipificação do evento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 64 do CDC", "Art. 10, §§ 1º e 2º do CDC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T05:11:31.704537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=168", "doc_key": "22c11f4b306b0e1c576d846cbf20dade"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'bdf70926fef84f56e181ee5d8bfbf453148fded44cc6e8ac8264aecad0b9ede1'),
  ('cpiuris2025::fe08c95621b4b93445a2d8d50e1de619', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Periculosidade Exagerada no CDC', '## Periculosidade Exagerada no CDC

É crime próprio de periculosidade exagerada, com tentativa e sem resultado concreto, criticando a expressão ''alto grau de periculosidade'' e demandando norma definitoria.

### Conceitos
- **Tentativa**: Ocorre na modalidade ativa ou omissiva
- **Perigosidade Exagerada**: É crime próprio, criticado pela expressão ''alto grau de periculosidade''
- **Norma Definitoria**: Extrapenal ou administrativa

### Referências legais
- Art. 3º, § 2º do CDC

### Dicas de prova
- Distinção entre ''periculosidade exagerada'' e ''alto grau de periculosidade''
- Interpretação restritiva da norma definitoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 3º, § 2º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:11:52.852149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=168", "doc_key": "fe08c95621b4b93445a2d8d50e1de619"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '425cf25a6c2b8b93363be0667d442f57ccc46d77b44a8ddfb97434d75b9e301d'),
  ('cpiuris2025::1b45501e9a3061307a6e1867f88fb3f8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Crime de Omissão de Dados em Publicidade', '## Crime de Omissão de Dados em Publicidade

O art. 69 do CDC estabelece crime contra o consumidor que deixa de organizar dados fáticos, técnicos e científicos para a publicidade, caracterizando-se como crime omissivo próprio, de perigo abstrato e não admitindo tentativa.

### Conceitos
- **Crime Omissivo Próprio**: Omissão que resulta em dano ao consumidor
- **Perigo Abstrato**: Dano potencial, mas não necessariamente concreto
- **Tentativa**: Não é admitida na omissão crime

### Referências legais
- Art. 69 do CDC

### Dicas de prova
- Entenda a distinção entre crime de perigo concreto e abstrato
- Lembre-se da natureza omissiva própria do art. 69 do CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 69 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:13:17.826612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=169", "doc_key": "1b45501e9a3061307a6e1867f88fb3f8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '19d3298060ae6fc5f91ceb5a0234aa4162042ed4e1a5b4787335493500636fa4'),
  ('cpiuris2025::7060051cf0dfc71de21795e0ea6c4350', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Emprego de partes usadas em produtos', '## Emprego de partes usadas em produtos

Delitos relacionados ao emprego de partes usadas em produtos sem autorização do consumidor, incluindo estelionato e lesão ao patrimônio do consumidor.

### Conceitos
- **Distanciamento demasiado da lesividade**: Conceito jurídico que se refere à distância excessiva entre a lesividade causada pelo produto e o dano ao bem jurídico do consumidor.
- **Emprego de partes usadas**: Uso de peças ou componentes de produtos já utilizados sem autorização do consumidor
- **Delito especial**: Tipo de crime que se aplica a situações específicas, como o emprego de partes usadas em produtos

### Referências legais
- Art. 70 do CDC
- Art. 71 do CDC
- Art. 72 do CDC
- Art. 171 do CP

### Dicas de prova
- Distinção entre o emprego de partes usadas e a utilização de produtos já consumidos
- Conceito de delito especial e sua aplicabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 70 do CDC", "Art. 71 do CDC", "Art. 72 do CDC", "Art. 171 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:13:59.890348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=170", "doc_key": "7060051cf0dfc71de21795e0ea6c4350"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '641af77c007cee32ede3ee8d0995593ed89409fd9579b2214453965032c15452'),
  ('cpiuris2025::2fcf72422504167cd220b64a8a71fa84', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Falsidade de Informação no Comércio', '## Falsidade de Informação no Comércio

Artigos 66, 67 e 68 do CDC definem crimes relacionados à falsidade de informação em publicidade, tutelando princípios da informação e transparência.

### Conceitos
- **Falsidade de Informação**: Dito que é feita com o objetivo de enganar ou induzir o consumidor
- **Marketing Publicitário**: Atividade realizada pelo vendedor no momento da venda para promover um produto ou serviço
- **Enganosidade**: Característica que torna a publicidade falsa ou enganosa
- **Abusividade**: Característica que torna a publicidade abusiva ou prejudicial ao consumidor
- **Dolo**: Exigido para cometer o crime, mas se aperfeiçoa quando o agente ''sabe ou deveria saber''
- **Tentativa**: Admite-se na modalidade ativa e não é exigida no caso de resultado concreto
- **Transparência**: Princípio que tutela a observância à informação relevante sobre produtos ou serviços
- **Informação Relevante**: Dada importância para o consumidor, necessária para tomar uma decisão informada

### Referências legais
- Art. 66 do CDC
- Art. 67 do CDC
- Art. 68 do CDC

### Dicas de prova
- Diferenciar entre falsidade de informação e marketing publicitário
- Entender a noção de enganosidade e abusividade em relação à publicidade
- Conhecer o conceito de dolo e tentativa no contexto do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 66 do CDC", "Art. 67 do CDC", "Art. 68 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:14:12.542104+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=169", "doc_key": "2fcf72422504167cd220b64a8a71fa84"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '0caf4ea99128a241057796926160ce9bc0cc485b7472de5c284f8fcfd0d358b1'),
  ('cpiuris2025::3b676be0d93a3644e1da603e538a8677', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Crime de Dados Públicos ou Cadastros', '## Crime de Dados Públicos ou Cadastros

É crime deixar de corrigir informação sobre consumidor constante de cadastro, banco de dados, fichas ou registros que sabe ou deveria saber ser inexata.

### Conceitos
- **Crime Omissivo**: É um tipo de crime que não exige resultado concreto
- **Perigo Abstrato**: Não exige resultado concreto, mas pode causar dano ao consumidor
- **Mera Conduta**: Pode ser praticada por qualquer pessoa sem necessidade de intenção criminosa

### Referências legais
- Art. 43 do CDC
- Art. 5º, X da CRFB/88

### Dicas de prova
- Distinção entre crime omissivo e crime de ação dolosa
- Perigo abstrato vs resultado concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43 do CDC", "Art. 5º, X da CRFB/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:15:05.007581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=170", "doc_key": "3b676be0d93a3644e1da603e538a8677"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9869c6d3eafdddd167571012a1da824d5375cc0e36a2f96fa427326fa1d103ea'),
  ('cpiuris2025::77ca12effd6841f7cd39cd1ba96e00fc', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cálculo da multa penal no CDC', '## Cálculo da multa penal no CDC

O CDC estabelece regra especial para cálculo da multa penal, considerando a duração da pena privativa de liberdade e o valor contido no art. 60 do CP.

### Conceitos
- **dias-multa**: unidade de medida utilizada para calcular a multa pecuniária
- **penalidade especial**: regra específica estabelecida pelo CDC para cálculo da multa penal

### Referências legais
- Art. 77 do CDC
- Art. 78 do CDC
- Art. 49 do CP
- Art. 60 do CP

### Dicas de prova
- Entenda a diferença entre dias-multa e marcos fixo
- Conheça as regras específicas do CDC para cálculo da multa penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 77 do CDC", "Art. 78 do CDC", "Art. 49 do CP", "Art. 60 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:15:31.094664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=171", "doc_key": "77ca12effd6841f7cd39cd1ba96e00fc"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7c06c9038901688a71b3066f86e08c0d4722f132a4fe5e73a9cc61a0d5e31ceb'),
  ('cpiuris2025::8ba1a537abd8b5717ca77cc74b9cdc25', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Infrações Penais contra o Consumidor', '## Infrações Penais contra o Consumidor

O texto trata das infrações penais contra o consumidor, incluindo a falta de transparência e autodeterminação informativa, além de crimes relacionados à garantia e responsabilidade das pessoas jurídicas.

### Conceitos
- **Transparência**: Princípio que exige a clareza e a honestidade nas informações fornecidas aos consumidores.
- **Autodeterminação Informativa**: Direito do consumidor de tomar decisões informadas sobre suas escolhas de compra.
- **Garantia**: Condição que protege o consumidor contra defeitos ou falhas nos produtos ou serviços adquiridos.

### Referências legais
- Art. 4º, caput e § 6º, III e IV do CDC
- Art. 5º, X da CRFB/88 c/c art. 43, caput e § 1º do CDC
- Art. 43, § 3º

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre o crime de infração penal contra o consumidor e a responsabilidade civil.
- Importância da transparência e autodeterminação informativa nos contratos de consumo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, caput e § 6º, III e IV do CDC", "Art. 5º, X da CRFB/88 c/c art. 43, caput e § 1º do CDC", "Art. 43, § 3º"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T05:15:42.323165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=171", "doc_key": "8ba1a537abd8b5717ca77cc74b9cdc25"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7f8abcdb8ca2d486626f8d0e702c4ef49f042daa06371be25780e4165d9c6f1b'),
  ('cpiuris2025::f0aee19aa993a271fe00e94cd4e5a90f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Crimes contra o consumidor', '## Crimes contra o consumidor

O texto discute a aprovação de fornecimentos e serviços em condições proibidas, alinhando-se ao art. 76, IV, b) do CDC, e a aplicabilidade da pena de liquidação compulsória.

### Conceitos
- **Crimes contra o consumidor**: Atos que violam direitos dos consumidores
- **Aprovação de fornecimentos e serviços**: Condições em que os produtos ou serviços são oferecidos
- **Pena de liquidação compulsória**: Penalidade aplicada às pessoas jurídicas

### Referências legais
- Art. 76, IV, b) do CDC
- Art. 80 do CDC
- Art. 82, inciso

