  ('cpiuris2025::900ca63e8a5535c566c08e92a9aaf9da', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Penalidade nas infrações previstas no Código de Defesa do Consumidor (CDC)', '## Penalidade nas infrações previstas no Código de Defesa do Consumidor (CDC)

O texto discute as normas penais e processuais previstas no CDC, incluindo a responsabilidade das pessoas jurídicas e a aplicação de penas alternativas.

### Conceitos
- **Pena Alternativa**: Pena que pode ser imposta em vez da privativa de liberdade
- **Culpa**: Obrigação de agir ou não agir com cuidado e atenção
- **Dolo**: Intenção de causar dano a outrem
- **Culpabilidade**: Medida da responsabilidade do sujeito passivo em relação ao crime cometido
- **Pena de Multa**: Pena que consiste na imposição de uma quantia financeira
- **Liquidação Compulsória**: Medida processual que impõe a dissolução da pessoa jurídica e a distribuição de seus ativos

### Referências legais
- Art. 63, caput e § 2º do CDC
- Art. 75 do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de culpa e dolo em relação às infrações previstas no CDC.
- Conheça as penas alternativas disponíveis para as pessoas jurídicas que cometem crimes previstos no CDC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 63, caput e § 2º do CDC", "Art. 75 do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T05:18:40.500909+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=173", "doc_key": "900ca63e8a5535c566c08e92a9aaf9da"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'df42538dacb4372f289670d07a0fd3da92d9d72b28b079502a7e22255c574340'),
  ('cpiuris2025::931641ca47c32420d6a0e4771a5ba92d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fiança no processo penal contra consumidor', '## Fiança no processo penal contra consumidor

A questão discute a fixação da fiança em casos de crimes contra o consumidor, com referência ao artigo 79 do CDC.

### Conceitos
