- Entenda a diferença entre fiança e multa
- Conheça os critérios para fixação da fiança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.174", "page_number": 174, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 76, I do CDC", "Art. 78, I e II do CDC", "Art. 79, parágrafo único do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:19:13.483246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=174", "doc_key": "931641ca47c32420d6a0e4771a5ba92d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7e5cb1984d1d77ec18483ba10ea98d7686ef06819d5a37e9318de2de741c9f13'),
  ('cpiuris2025::f67b030e1f9a2e9053d7ca76b95811dd', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Tratamento dos direitos coletivos no microssistema', '## Tratamento dos direitos coletivos no microssistema

O tratamento dos direitos coletivos passa a se submeter a um roteiro que não se limita a um diploma legal, buscando soluções nos diplomas específicos, microssistemas e demais leis que tratam sobre processos coletivos.

### Conceitos
- **Microssistema**: conjunto de leis que compõem o direito do consumidor
- **Diploma específico**: lei que regula um determinado assunto específico
- **Tratamento dos direitos coletivos**: aplicação das regras para proteger os direitos dos consumidores em grupo
- **Roteiro**: método sistemático de busca por soluções nos diplomas legais

### Referências legais
- Art. 82 da Lei nº 8.078/1990
- Título III do Código de Defesa do Consumidor

### Jurisprudência
- REsp 510.150/MA
- Súmula 343 do STJ

### Dicas de prova
- Entenda a noção de microssistema e sua importância no direito do consumidor.
- Conheça as diferentes fontes legais que compõem o roteiro para tratamento dos direitos coletivos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 82 da Lei nº 8.078/1990", "Título III do Código de Defesa do Consumidor"], "jurisprudence": ["REsp 510.150/MA", "Súmula 343 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T05:20:54.492462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=176", "doc_key": "f67b030e1f9a2e9053d7ca76b95811dd"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd71e26d7d4e638ad79a480689bd084ea007b2d4ca763775a758f84215acd69f2'),
  ('cpiuris2025::ff309005529b91c16badc6d3cc2b50b2', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Defesa do Consumidor em Juízo', '## Defesa do Consumidor em Juízo

O título III do CDC trata da defesa do consumidor em juízo, com um papel de relevo no ordenamento jurídico brasileiro. O direito consumerista é fundamentalmente coletivo e se enquadra na dimensão dos direitos humanos.

### Conceitos
- **Direito Coletivo**: Integração entre o CDC, a Lei de Improbidade Administrativa, a Lei de Ação Civil Pública e a Lei do Mandado de Segurança.
- **Microssistema de Direito Coletivo**: Inclui o CDC, entre outros diplomas que tratam da temática coletiva
- **Processo Coletivo**: Tratamento adequado dos direitos consagrados no microssistema consumerista do CDC é fundamentalmente coletivo.
- **Teoria da Qualidade**: Prática abusiva e violação à teoria da qualidade se espraia em diversas relações travadas entre o fornecedor e o mercado.

### Referências legais
- Art. 21 da Lei n.º 7.347/85 c/c Art. 90 do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Busca pela implementação do processo coletivo é diretamente vinculada à adequada tutela do direito do consumidor.
- O CDC apresenta especial relevância nesse contexto em razão da aplicação de seu Título III como o diploma processual mais completo para a regência das contendas coletivas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 21 da Lei n.º 7.347/85 c/c Art. 90 do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T05:20:59.439398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=176", "doc_key": "ff309005529b91c16badc6d3cc2b50b2"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9c459f0bc55b0cbc36fb1eeaf9b5c4be6ac9f3f6fba6e41822581bfd7212b620'),
  ('cpiuris2025::ddcaa58608741ae1d772739dcaf3db29', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Direitos Coletivos Lato Sensu', '## Direitos Coletivos Lato Sensu

O art. 81 do CDC define a defesa dos interesses e direitos dos consumidores e das vítimas em juízo individualmente ou coletivamente. Os Direitos Coletivos Lato Sensu são exercidos quando se trata de interesses ou direitos difusos, indivisíveis, ligados por circunstâncias fáticas.

### Conceitos
- **Direitos Coletivos Lato Sensu**: Exercidos em juízo individualmente ou coletivamente para proteger interesses ou direitos difusos, indivisíveis e ligados por circunstâncias fáticas.
- **Interesses Difusos**: Indivisíveis, possuem titulares indeterminados e são ligados por circunstâncias fáticas
- **Transindividuais**: São direitos que se aplicam a um grupo de pessoas, independentemente da identidade individual dessas pessoas

### Referências legais
- Art. 81 do CDC
- Parágrafo único do Art. 21 da LACP

### Dicas de prova
- Entenda a distinção entre Direitos Coletivos Lato Sensu e coletivos stricto sensu.
- Identifique os exemplos de direitos difusos mencionados no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 81 do CDC", "Parágrafo único do Art. 21 da LACP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:21:38.856888+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=177", "doc_key": "ddcaa58608741ae1d772739dcaf3db29"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '26150df4ab312f3ec718cd6b02eb039e091094df5260ccdf9fd47329879cbbce'),
  ('cpiuris2025::65641ca3ccffa3e3875b7c28e4917641', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Diferença entre direitos coletivos e difusos', '## Diferença entre direitos coletivos e difusos

Resumo objetivo: os direitos coletivos são indivisíveis, com titulares indeterminados e ligados à parte contrária por uma relação jurídica base. Já o direito difuso é fático e não possui relação jurídica base.

### Conceitos
- **Direitos Coletivos**: Indivisíveis, com titulares indeterminados
- **Direito Difuso**: Fático, sem relação jurídica base
- **Relação Jurídica Base**: Necessária para os direitos coletivos

### Referências legais
- Art. 43 da Lei nº 8.078/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferença entre afetio societatis e relação jurídica base
- Exemplo de direito coletivo: alunos de uma faculdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43 da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T05:22:41.652289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=177", "doc_key": "65641ca3ccffa3e3875b7c28e4917641"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '44dcee26d69ef08ff6fd1a9fcbe20f24dd857697fbe7f83505cd1bf06350d585'),
  ('cpiuris2025::dab0a92da70746059c1fd90000dc0162', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Interesses ou direitos individuais homogêneos', '## Interesses ou direitos individuais homogêneos

Os interesses ou direitos individuais homogêneos são divisíveis e possuem titulares determinados, originando-se de uma lesão comum. São tratados individualmente, mas com coletividade por meio da legislação.

### Conceitos
- **Interesses ou direitos individuais homogêneos**: Direitos divisíveis e individuais, originando-se de uma lesão comum
- **Titulares determinados**: Pessoas que possuem direito individualmente, mas compartilham a mesma origem da lesão
- **Lesão comum**: Fato que originou a homogeneidade dos direitos individuais homogêneos

### Referências legais
- Art. 81 do CDC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direito coletivo e direitos individuais homogêneos
- Conheça o conceito de lesão comum e sua importância na origem dos direitos individuais homogêneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 81 do CDC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T05:23:15.058629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=178", "doc_key": "dab0a92da70746059c1fd90000dc0162"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3a9148446780836553ca0cc8184890cbe2a4631a21aa809bd30690e84b1f50db'),
  ('cpiuris2025::18d8f571573efacbc649e09e7eb7df7c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dano Moral Coletivo', '## Dano Moral Coletivo

O dano moral coletivo é um tipo de dano que afeta os valores e interesses coletivos fundamentais, resultando em uma lesão grave e maculada. Para ser configurado, a conduta antijurídica deve ter uma repercussão social significativa.

### Conceitos
- **Dano Moral Coletivo**: Lesão que afeta os valores e interesses coletivos fundamentais
- **Repercussão Social**: Significativa influência da conduta antijurídica na sociedade

### Referências legais
- Art. 43, § 2º, da Lei nº 8.078/1990

### Jurisprudência
- REsp 1.840.463/SP
- REsp 1.737.412/SE
- REsp 1.517.973/PE
- REsp 1.567.123/RS

### Dicas de prova
- Entenda a noção de dano moral coletivo e sua configuração
- Reconheça a importância da repercussão social na configuração do dano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43, § 2º, da Lei nº 8.078/1990"], "jurisprudence": ["REsp 1.840.463/SP", "REsp 1.737.412/SE", "REsp 1.517.973/PE", "REsp 1.567.123/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T05:23:49.488950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=178", "doc_key": "18d8f571573efacbc649e09e7eb7df7c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'dcedf9c139c50a089121c93139c0424a4e67aab77bcc5429c73632e9c8603b55'),
  ('cpiuris2025::a020ff611ee44b800850aff1a183c1c9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Legitimados para propositura de demandas coletivas', '## Legitimados para propositura de demandas coletivas

Resumo sobre os legitimados para propor demandas coletivas no Direito do Consumidor, incluindo o Ministério Público e as associações.

### Conceitos
- **Legitimados**: Entes que podem propor demandas coletivas
- **Sistema misto/pluralista**: Combina entidades públicas e privadas como legitimados para propositura de demandas coletivas
- **Legitimidade**: Conceito que se refere à capacidade de uma pessoa ou entidade realizar uma ação jurídica

### Referências legais
- Art. 5º da Lei n.º 7.347/85
- Art. 82 do CDC

### Jurisprudência
- REsp 1.539.056/MG
- REsp 1.574.350/SC
- STJ – REsp 876.936/RJ
- STF – RE 193.503/SP

### Dicas de prova
- Entenda o conceito de legitimidade e como ela se aplica às demandas coletivas.
- Conheça as diferenças entre sistema misto/pluralista e class actions americanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 5º da Lei n.º 7.347/85", "Art. 82 do CDC"], "jurisprudence": ["REsp 1.539.056/MG", "REsp 1.574.350/SC", "STJ – REsp 876.936/RJ", "STF – RE 193.503/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T05:24:58.748425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=179", "doc_key": "a020ff611ee44b800850aff1a183c1c9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7a164a94767c0b2400685860f4a6bc0687042e19b17f849ac7b58d46c4ae3e7e'),
  ('cpiuris2025::80bfe1ecf7c0cb5862a3a9768661ae1b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Legitidade do Ministério Público para promover ações civis públicas', '## Legitidade do Ministério Público para promover ações civis públicas

O MP tem legitimidade para promover ações civis públicas em casos de direito do consumidor, como ilegalidade de reajuste de mensalidades escolares e contratos de compra e venda de imóveis com cláusulas abusivas.

### Conceitos
- **Legitimidade do MP**: O MP tem legitimidade para promover ações civis públicas em casos de direito do consumidor.
- **Direito do Consumidor**: É o direito dos consumidores de ser protegido contra práticas comerciais abusivas e ilegais.
- **Ação Civil Pública**: É uma ação iniciada pelo MP para proteger os interesses públicos ou privados.
- **Legitimidade da Parte**: O MP tem legitimidade para representar os interesses de terceiros em casos específicos.
- **Cláusulas Abusivas**: São cláusulas de contratos que são consideradas injustas ou prejudiciais aos consumidores.
- **Reajuste de Mensalidades**: O reajuste de mensalidades escolares é um caso em que o MP tem legitimidade para agir.
- **Contrato de Compra e Venda**: É um contrato entre comprador e vendedor que pode conter cláusulas abusivas.

### Referências legais
- Súmula 643 do STF
- REsp 1.585.794/MG

### Jurisprudência
- AgR, rel. Min. Celso De Mello, Segunda Turma
- REsp 856.378

### Dicas de prova
- Pergunte sobre a legitimidade do MP em casos de direito do consumidor.
- Entenda o conceito de cláusulas abusivas e reajuste de mensalidades escolares.
- Conheça as hipóteses em que o MP é reconhecido como legitimado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito do Consumidor", "legal_refs": ["Súmula 643 do STF", "REsp 1.585.794/MG"], "jurisprudence": ["AgR, rel. Min. Celso De Mello, Segunda Turma", "REsp 856.378"], "confidence": 0.8, "extracted_at": "2026-05-30T05:26:34.837005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=179", "doc_key": "80bfe1ecf7c0cb5862a3a9768661ae1b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'caea874134e35cd2731157f1419ec1c244ca90d002f0960a10cf9cad203f3397'),
  ('cpiuris2025::e31a51460e19d9d63801f11d2b9aeff9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Pertinência Temática nas Associações de Direito Privado', '## Pertinência Temática nas Associações de Direito Privado

As associações de direito privado devem demonstrar Pertinência Temática entre o direito discutido e sua finalidade estatutária. O STJ admite interpretação extensiva dos termos previstos, desde que haja manifesto interesse social evidenciado.

### Conceitos
- **Pertinência Temática**: relação entre o direito discutido e sua finalidade estatutária
- **Interpretação Extensiva**: interpretação ampla dos termos previstos
- **Manifesto Interesse Social**: evidência de que o dano é grande ou característico

### Referências legais
- Art. 54, XIV, EOAB
- Art. 5º, V, da LACP
- Art. 82, IV, do CDC

### Jurisprudência
- REsp 1351760/PE
- REsp 876.931/RJ

### Dicas de prova
- Distinguir entre atuação ordinária e litisconsórcio
- Entender a importância da pré-constituição das associações de direito privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54, XIV, EOAB", "Art. 5º, V, da LACP", "Art. 82, IV, do CDC"], "jurisprudence": ["REsp 1351760/PE", "REsp 876.931/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T05:27:05.208492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=180", "doc_key": "e31a51460e19d9d63801f11d2b9aeff9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '475641fdd02481b802a9a75f1d933bf043894a22909b331dca38e06a324ea301'),
  ('cpiuris2025::0abc95fe81b38aa48df9c9893e35789e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Legitidade para propositura de demandas coletivas', '## Legitidade para propositura de demandas coletivas

Resumo objetivo: Discute a legitimidade para propositura de demandas coletivas no Direito do Consumidor, incluindo o Ministério Público e a Defensoria Pública. Além disso, aborda a vinculação institucional com o direito discutido em órgãos da Administração Direta e Indireta.

### Conceitos
- **Legitidade para propositura de demandas coletivas**: Direito do consumidor que permite a propositura de demandas coletivas em nome de consumidores comuns
- **Ministério Público**: Legitimado ativo para propositura de demandas coletivas, especialmente em casos de direitos sociais relacionados ao FGTS
- **Defensoria Pública**: Legitimada ativa para propositura de demandas coletivas que buscam tutela dos necessitados, incluindo minorias e setores sociais desfavorecidos
- **Vinculação institucional**: Exigência de vinculação institucional com o direito discutido em órgãos da Administração Direta e Indireta

### Referências legais
- Art. 1º, Parágrafo Único, da LACP
- Art. 5º, § 3º, da LACP
- Art. 15 da LACP
- RE 576.155/DF
- RE 643978
- EREsp 1.405.697-MG
- EREsp 1.134.957/SP
- RE 733.433
- RCL 22614

### Jurisprudência
- STF, RE 576.155/DF
- STF, RE 643978
- STJ, REsp 1.405.697-MG
- STJ, EResp 1.134.957/SP
- STJ, EResp 1.192.577/RS

### Dicas de prova
- Distinção entre Ministério Público e Defensoria Pública
- Vinculação institucional com o direito discutido em órgãos da Administração Direta e Indireta
- Ampliação do termo ''necessitados'' para incluir minorias e setores sociais desfavorecidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1º, Parágrafo Único, da LACP", "Art. 5º, § 3º, da LACP", "Art. 15 da LACP", "RE 576.155/DF", "RE 643978", "EREsp 1.405.697-MG", "EREsp 1.134.957/SP", "RE 733.433", "RCL 22614"], "jurisprudence": ["STF, RE 576.155/DF", "STF, RE 643978", "STJ, REsp 1.405.697-MG", "STJ, EResp 1.134.957/SP", "STJ, EResp 1.192.577/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T05:27:54.793878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=180", "doc_key": "0abc95fe81b38aa48df9c9893e35789e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e00a1e19ff3d34fb756f94b91146f30275644eb664d55e18320a1f95239955bf'),
  ('cpiuris2025::511c3ff35d77a57195f5ef5c9b22bf82', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Atuação Coletiva e Legitimidade Extraordinária', '## Atuação Coletiva e Legitimidade Extraordinária

A atuação coletiva de associações é regulamentada pelos arts. 5º, V, da LACP e 82, IV, do CDC. A legitimidade extraordinária para defesa de direitos coletivos é facultada, mas depende de autorização assemblear específica e apresentação de lista de beneficiários.

### Conceitos
- **Legitimidade Extraordinária**: O direito de uma associação defender direitos coletivos de seus associados
- **Atuação Coletiva**: A ação conjunta de várias pessoas ou entidades para defender direitos comuns
- **Autorização Assemblear**: A necessidade de autorização específica dos associados para a defesa de direitos coletivos

### Referências legais
- Art. 5º, V da LACP
- Art. 82, IV do CDC

### Jurisprudência
- RE 1.293.130
- REsp 1.438.263/SP
- REsp 1.325.857/RS

### Dicas de prova
- Entenda a diferença entre atuação coletiva ordinária e extraordinária
- Conheça as exigências para a legitimidade extraordinária de associações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 5º, V da LACP", "Art. 82, IV do CDC"], "jurisprudence": ["RE 1.293.130", "REsp 1.438.263/SP", "REsp 1.325.857/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T05:28:33.739432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=181", "doc_key": "511c3ff35d77a57195f5ef5c9b22bf82"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd44badb1b5df4176300ccdea91615b55136b0831640d93f5486cce8d4e229aa5'),
  ('cpiuris2025::c625e9c12d0e7285a045743cfb6af55b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proposta de ações coletivas por sindicatos e cooperativas', '## Proposta de ações coletivas por sindicatos e cooperativas

Resumo sobre a proposta de ações coletivas por sindicatos e cooperativas, bem como o estímulo à efetividade da defesa dos direitos do consumidor.

### Conceitos
- **Sindicatos**: Organizações que representam interesses de uma categoria profissional ou econômica
- **Cooperativas**: Empresas socialmente controladas por seus membros, que têm como objetivo principal a distribuição de lucros entre os associados
- **Litisconsórcio**: Relação jurídica em que mais de uma pessoa é considerada legítima para propor ou defender uma ação
- **Amplitude do processo**: Princípio que permite a admissão de todas as espécies de ações capazes de propiciar a adequada e efetiva tutela dos direitos do consumidor

### Referências legais
- Art. 8º, III, da CF/88
- Art. 21, XI e 88-A da Lei n.º 5.764/71
- Art. 83 do CDC
- Art. 12 da LACP
- Art. 90 do CDC

### Jurisprudência
- REsp 1.503.007/CE
- REsp 1.091.756/MG
- RE 370834/MS
- RE 193.503/SP
- STJ, REsp 1444484/RN
- STF, ACO 1020/SP

### Dicas de prova
- Diferenciar entre sindicatos e cooperativas em termos de proposta de ações coletivas
- Entender o conceito de litisconsórcio e sua aplicação no Direito do Consumidor
- Aplicar o princípio da amplitude do processo para a defesa dos direitos do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 8º, III, da CF/88", "Art. 21, XI e 88-A da Lei n.º 5.764/71", "Art. 83 do CDC", "Art. 12 da LACP", "Art. 90 do CDC"], "jurisprudence": ["REsp 1.503.007/CE", "REsp 1.091.756/MG", "RE 370834/MS", "RE 193.503/SP", "STJ, REsp 1444484/RN", "STF, ACO 1020/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T05:28:55.028684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=181", "doc_key": "c625e9c12d0e7285a045743cfb6af55b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e83d375d8bb4c86dbeeaa9ad66126ba4c7e39762c873e1c46a6dd3700b5ebca0'),
  ('cpiuris2025::ab4a947b5f46bfd3c093f0e5070f5ecc', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Denunciação à Lide e Competência', '## Denunciação à Lide e Competência

A denunciação à lide é vedada nas demandas consumeristas, de acordo com o art. 88 do CDC. A competência para a causa é definida pelo art. 93 do CDC, considerando a extensão do dano.

### Conceitos
- **Denunciação à Lide**: Ação em que um consumidor denuncia uma lide para ser incluída na demanda principal
- **Competência Territorial**: Definição da competência do juízo para processar a causa
- **Publicidade**: Princípio que exige que as ações judiciais sejam públicas e divulgadas
- **Right to Opt In**: Direito do consumidor de optar por ser incluído em uma demanda coletiva

### Referências legais
- Art. 88 do CDC
- Art. 93 do CDC
- Art. 2º da LACP

### Jurisprudência
- EREsp nº 1.531.504/CE

### Dicas de prova
- Entenda a vedação da denunciação à lide nas demandas consumeristas
- Conheça as regras de competência territorial definidas pelo CDC e pela LACP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 88 do CDC", "Art. 93 do CDC", "Art. 2º da LACP"], "jurisprudence": ["EREsp nº 1.531.504/CE"], "confidence": 0.8, "extracted_at": "2026-05-30T05:31:17.878264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=183", "doc_key": "ab4a947b5f46bfd3c093f0e5070f5ecc"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '522c1abaad5ccb6af0ee194b2778615d69fabd0a411439d0ca4875eda5fdfc76'),
  ('cpiuris2025::1721e983d3de7c14b382dac45f376bf1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Custas, Emolumentos, Despesas e Honorários em Ações Coletivas', '## Custas, Emolumentos, Despesas e Honorários em Ações Coletivas

O art. 87 do CDC estabelece que não haverá adiantamento de custas, emolumentos, honorários periciais e outras despesas nas ações coletivas do CDC, salvo comprovada má-fé.

### Conceitos
- **adiantamento**: exigir antecipação de honorários
- **má-fé**: conduta dolosa ou desleal
- **legitimados**: partes que têm direito à tutela do CDC
- **custas**: despesas processuais
- **emolumentos**: remuneração do advogado
- **honorários periciais**: compensação por especialista

### Referências legais
- Art. 87 do CDC
- Art. 17 da LACP
- Art. 18 da LACP

### Jurisprudência
- REsp 1.253.844/SC
- REsp 1.637.366/SP
- ACo 1.560

### Dicas de prova
- Entenda a diferença entre adiantamento e exigência de honorários.
- Conheça o princípio da má-fé e sua aplicação no CDC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 87 do CDC", "Art. 17 da LACP", "Art. 18 da LACP"], "jurisprudence": ["REsp 1.253.844/SC", "REsp 1.637.366/SP", "ACo 1.560"], "confidence": 0.8, "extracted_at": "2026-05-30T05:31:27.959267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=182", "doc_key": "1721e983d3de7c14b382dac45f376bf1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '0d94c41861288cdc5f0a727a5e21b92883371299aee23f5f628fb38014ee5487'),
  ('cpiuris2025::1527dbd398bed51e72122ec4479e7b1f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Tutela específica e multa diária', '## Tutela específica e multa diária

O art. 84 do CDC estabelece que a tutela específica é preferida, com a possibilidade de reconhecer perdas e danos subsidiárias. O § 1º determina que a conversão da obrigação em perdas e danos é admissível se o autor optar por essa medida ou se a tutela específica for impossível. O § 4º permite a imposição de multa diária ao réu, independentemente do pedido do autor.

### Conceitos
- **Tutela específica**: Preferência dada à tutela específica em vez da indenização por perdas e danos
- **Multa diária**: Imposição de multa diária ao réu, independentemente do pedido do autor
- **Conversão de obrigação em perdas e danos**: Admissibilidade da conversão da obrigação em perdas e danos, dependendo das circunstâncias do caso

### Referências legais
- Art. 84 do CDC

### Dicas de prova
- Reconhecer a tutela específica como preferida
- Diferenciar entre perdas e danos e multa diária
- Entender a admissibilidade da conversão de obrigação em perdas e danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 84 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:31:38.468632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=182", "doc_key": "1527dbd398bed51e72122ec4479e7b1f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '96632d6b559a241552c9752e5471a55f2b10c6bf733ba986f5d440b9a1eb6def'),
  ('cpiuris2025::c8092529aa1763bcd3143fa597757d3e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Ampla Divulgação da Demanda', '## Ampla Divulgação da Demanda

O art. 94 do CPC estabelece que a ação deve ser publicada para permitir o intercurso de litisconsortes e divulgar amplamente pela mídia, respeitando os princípios da justiça e universalidade.

### Conceitos
- **Litisconsorte**: Parte que intervém no processo sem ser parte principal
- **Ampla Divulgação**: Divulgação da demanda para envolver mais pessoas
- **Princípio do Acesso à Justiça**: Direito de todos ao acesso justo e igualitário aos tribunais
- **Princípio da Universalidade da Jurisdição**: Acesso igual para todos às instâncias judiciais

### Referências legais
- Art. 94 do CPC
- Art. 5º, XXXV da CF/88

### Dicas de prova
- Entenda a importância da ampla divulgação da demanda no processo
- Conheça os princípios da justiça e universalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 94 do CPC", "Art. 5º, XXXV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:33:19.559193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=183", "doc_key": "c8092529aa1763bcd3143fa597757d3e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '91d469fcaf63719b1d44fca5e30523c12fbfa792a705228eb6f17cf4a9f8efb1'),
  ('cpiuris2025::702ab3d878d9d8202efaf22372bae99b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Transporte inutilis da coisa julgada', '## Transporte inutilis da coisa julgada

Descreve o transporte inutilis da coisa julgada em demandas coletivas, exigindo liquidação imprópria e comprovação de titularidade do direito.

### Conceitos
- **Transporte inutilis**: Procedimento que permite a liquidação de direitos individuais homogêneos
- **Liquidação imprópria**: Procedimento que exige comprovação da titularidade do direito por parte do liquidante
- **Direito individual certificado**: Direito que pode ser proposto em sentença coletiva e deve ser liquidiado de forma imprópria

### Referências legais
- Art. 103, § 3º, do CDC

### Jurisprudência
- REsp 1.947.661/RS
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre transporte inutilis e liquidação imprópria
- Conheça o procedimento para direitos individuais certificados em sentença coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 103, § 3º, do CDC"], "jurisprudence": ["REsp 1.947.661/RS", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T05:33:36.615434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=184", "doc_key": "702ab3d878d9d8202efaf22372bae99b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ccc7adf36ceaf04d346e892364bad85e357d58905b7c66223a2f8aa168eb16d1'),
  ('cpiuris2025::5147edf605a61b9ac35da8c3fd52b6b5', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Liquidação prévia e cumprimento direto de sentença coletiva', '## Liquidação prévia e cumprimento direto de sentença coletiva

O STJ discute se a liquidação prévia é requisito indispensável para o ajuizamento de ações objetivando o cumprimento de sentença coletiva, ou se pode ser dispensada.

### Conceitos
- **Liquidação prévia**: Procedimento que visa liquidar uma obrigação antes do ajuizamento da ação executiva
- **Cumprimento direto de sentença coletiva**: Procedimento que permite o cumprimento imediato de uma sentença coletiva sem a necessidade de liquidação prévia
- **Ação objetivando o cumprimento de sentença condenatória genérica**: Ação que visa obter a execução de uma sentença condenatória em um caso geral

### Referências legais
- Art. 513 do CPC

### Jurisprudência
- REsp n.º 1.978.629/RJ
- Tema nº 1169/STJ

### Dicas de prova
- Entenda a diferença entre liquidação prévia e cumprimento direto de sentença coletiva
- Conheça o conceito de ação objetivando o cumprimento de sentença condenatória genérica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 513 do CPC"], "jurisprudence": ["REsp n.º 1.978.629/RJ", "Tema nº 1169/STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T05:35:45.577871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=185", "doc_key": "5147edf605a61b9ac35da8c3fd52b6b5"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4c7cbe3770a8ae4e3d3d5c2691319e77be29b39a53e95befe50e53e832e99ef0'),
  ('cpiuris2025::0048cef4030d293fea12047b898fde01', 'doutrina', 'cp_iuris', 'Direito do Consumidor — O direito do consumidor em processos coletivos', '## O direito do consumidor em processos coletivos

O artigo 104 do CDC estabelece que as ações coletivas não induzem litispendência para as ações individuais, mas os efeitos da coisa julgada erga omnes não beneficiarão os autores das ações individuais se não for requerida sua suspensão. O STJ entendeu que é possível a suspensão de todas as ações individuais pelo juiz nas hipóteses em que ajuizada demanda coletiva versando a mesma causa de pedir.

### Conceitos
- **Litispendência**: O estado de litis pendente, ou seja, a existência de uma ação judicial que ainda não foi julgada.
- **Cosa julgada erga omnes**: A aplicação de uma decisão judicial que tem efeito geral e não pode ser alterada por outra decisão posterior.
- **Liquidação imprópria**: O processo de execução de sentença, onde a vítima ou seus sucessores, assim como os legitimados, podem promover a liquidação e a execução da sentença.
- **Demanda coletiva**: Ação judicial que visa proteger o direito de um grupo de pessoas que compartilham uma situação semelhante.
- **Art. 104 do CDC**: Estabelece que as ações coletivas não induzem litispendência para as ações individuais, mas os efeitos da coisa julgada erga omnes não beneficiarão os autores das ações individuais se não for requerida sua suspensão.
- **Art. 95 do CDC**: Estabelece que em caso de procedência do pedido, a condenação será genérica, fixando a responsabilidade do réu pelos danos causados.
- **Art. 97 do CDC**: Permite que a vítima e seus sucessores, assim como os legitimados, promovam a liquidação e a execução da sentença.

### Referências legais
- Art. 104 do CDC
- Súmula 394 STJ

### Jurisprudência
- REsp 205.481/MG
- REsp nº 1.243.887/PR
- REsp nº 1.525.327/PR

### Dicas de prova
- Entenda a diferença entre litispendência e coisa julgada erga omnes.
- Conheça o conceito de demanda coletiva e sua importância no direito do consumidor.
- Aprenda a aplicar os arts. 104, 95 e 97 do CDC em situações práticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104 do CDC", "Súmula 394 STJ"], "jurisprudence": ["REsp 205.481/MG", "REsp nº 1.243.887/PR", "REsp nº 1.525.327/PR"], "confidence": 0.8, "extracted_at": "2026-05-30T05:35:57.834044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=184", "doc_key": "0048cef4030d293fea12047b898fde01"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'cefb461906805a7f246d57d37742435d63f8791d28b967719f21bd6ff889b948'),
  ('cpiuris2025::b7efde48ec67522972a7514591a4c0a9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Execução Coletiva', '## Execução Coletiva

A execução coletiva é realizada pelos legitimados em benefício de pessoas que já tiveram suas indenizações fixadas ou com relação a danos coletivos. O MP não possui legitimidade para promover a execução coletiva sem interesse público ou social.

### Conceitos
- **Legitimados**: Partes que têm direito à execução coletiva
- **Execução Coletiva**: Procedimento que visa a realização de indenizações a várias pessoas
- **Interesse Público ou Social**: Justificativa necessária para a atuação do MP na execução coletiva
- **Direitos Individuais Homogêneos**: Direitos que não têm interesse social e, portanto, não permitem a execução coletiva pelo MP

### Referências legais
- Art. 97 do CDC
- Art. 98 do CDC
- Art. 82 do CDC
- CPC Art. 509, § 2º

### Jurisprudência
- REsp 1.801.518/RJ
- RE 568.645-RG
- STJ
- STF

### Dicas de prova
- Distinção entre execução coletiva e individual
- Importância do interesse público ou social para a atuação do MP
- Diferença entre direitos individuais homogêneos e não homogêneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 97 do CDC", "Art. 98 do CDC", "Art. 82 do CDC", "CPC Art. 509, § 2º"], "jurisprudence": ["REsp 1.801.518/RJ", "RE 568.645-RG", "STJ", "STF"], "confidence": 0.8, "extracted_at": "2026-05-30T05:36:11.052007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=185", "doc_key": "b7efde48ec67522972a7514591a4c0a9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9cfc24defa73052bf140c2a3476046c4b90961d55ca8c3130999987718cbd749'),
  ('cpiuris2025::e003ea06eb7d13308166dadc125a00c7', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Competência para Execução de Sentença Coletiva', '## Competência para Execução de Sentença Coletiva

O juízo competente para a execução da sentença coletiva é determinado pelo art. 98, § 2º, do CDC, e pode ser o Juízo da liquidação da sentença ou da ação condenatória em casos de execução individual, ou o Juízo da ação condenatória em casos de execução coletiva.

### Conceitos
- **Competência**: A capacidade do juiz de julgar uma causa
- **Execução Coletiva**: O processo pelo qual a sentença condenatória é executada em relação a vários consumidores
- **Liquidação Individual**: A execução da sentença coletiva de forma individual, fora do contexto da ação condenatória

### Referências legais
- Art. 98, § 2º, do CDC
- STJ - Resp 1243887/PR
- STF - RE 1101937

### Jurisprudência
- RE 1101937

### Dicas de prova
- Entenda a distinção entre execução individual e coletiva
- Conheça o art. 98, § 2º, do CDC
- Aprenda com as decisões do STJ e STF sobre competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 98, § 2º, do CDC", "STJ - Resp 1243887/PR", "STF - RE 1101937"], "jurisprudence": ["RE 1101937"], "confidence": 0.8, "extracted_at": "2026-05-30T05:38:14.729331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=186", "doc_key": "e003ea06eb7d13308166dadc125a00c7"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8963addf5e568879c5b0263b2ecd73e18f7231cf094b7a6719b749d756b5e870'),
  ('cpiuris2025::c270558618277457881b3a3210d1092e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Preferência no pagamento de créditos decorrentes de condenação prevista na Lei 7.347/85', '## Preferência no pagamento de créditos decorrentes de condenação prevista na Lei 7.347/85

A lei estabelece que em caso de concurso de créditos decorrentes de condenação prevista na Lei 7.347/85 e de indenizações pelos prejuízos individuais resultantes do mesmo evento danoso, as execuções a título individual terão preferência no pagamento.

### Conceitos
- **Concurso de créditos**: O processo em que se sobe o valor das dívidas de vários devedores
- **Lei 7.347/85**: A Lei do Consumidor
- **Preferência no pagamento**: O direito de priorizar o pagamento de um crédito sobre outro
- **Execução a título individual**: O processo em que se busca o pagamento de uma dívida específica
- **Indenizações coletivas e individuais**: As indenizações pagas aos consumidores como resultado de um evento danoso

### Referências legais
- Art. 99 do CDC

### Jurisprudência
- REsp 1.866.440-AL
- CC 199.938-SP

### Dicas de prova
- Entenda a diferença entre execução coletiva e individual
- Conheça a Lei 7.347/85 e seu impacto no Direito do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 99 do CDC"], "jurisprudence": ["REsp 1.866.440-AL", "CC 199.938-SP"], "confidence": 0.8, "extracted_at": "2026-05-30T05:38:22.351777+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=186", "doc_key": "c270558618277457881b3a3210d1092e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '89870e037d0cd3a7521d455556ada3d6068b05c969d99f20803363f130f9c1fd'),
  ('cpiuris2025::d4372aeba9538dfec0aa7dadf55c6d51', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Execução da Sentença Coletiva e Coisa Julgada', '## Execução da Sentença Coletiva e Coisa Julgada

O artigo 100 do CDC estabelece que a execução da sentença coletiva pode ser promovida pela liquidação e execução da indenização devida, após um ano sem habilitação de interessados. A coisa julgada se aplica às ações coletivas, sendo erga omnes em casos de direitos difusos procedentes.

### Conceitos
- **Execução da Sentença Coletiva**: Promover a liquidação e execução da indenização devida após um ano sem habilitação de interessados
- **Coisa Julgada Secundum Eventum Probationis**: Caso em que o pedido é julgado improcedente por falta de provas, permitindo a propositura de nova ação com fundamento em novos elementos de prova
- **Coisa Julgada Erga Omnes**: A sentença faz coisa julgada em casos de direitos difusos procedentes ou improcedentes

### Referências legais
- Art. 100 do CDC
- Art. 103 do CDC
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Coisa Julgada Secundum Eventum Probationis

### Dicas de prova
- Diferenciar entre execução da sentença coletiva e coisa julgada secundum eventum probationis
- Entender a noção de coisa julgada erga omnes em casos de direitos difusos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 100 do CDC", "Art. 103 do CDC", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Coisa Julgada Secundum Eventum Probationis"], "confidence": 0.8, "extracted_at": "2026-05-30T05:38:58.738096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=187", "doc_key": "d4372aeba9538dfec0aa7dadf55c6d51"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3fe9984691d209a46631b9593a6bdf866d35e5a8a3253ebcdc365b3f0304440f'),
  ('cpiuris2025::e86b4d5894997f64f5d124801f299760', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Coisa Julgada nos Direitos Coletivos', '## Coisa Julgada nos Direitos Coletivos

A coisa julgada se aplica a direitos coletivos, exceto quando o pedido for improcedente por insuficiência de provas, permitindo a proposta de nova ação com base em novo elemento de prova.

### Conceitos
- **Coisa Julgada**: Conceito jurídico que se refere à imutabilidade da decisão do juiz
- **Direitos Coletivos**: Direitos que são comuns a um grupo, categoria ou classe de pessoas
- **Ultra partes**: Situação em que a coisa julgada se aplica apenas às partes envolvidas na ação
- **Erga Omnes**: Conceito jurídico que se refere à aplicação da lei a todos os interessados, independentemente de sua participação no processo

### Referências legais
- Art. 81 do Código de Defesa do Consumidor

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre coisa julgada e direitos coletivos.
- Conheça as regras sobre ultra partes e erga omnes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 81 do Código de Defesa do Consumidor"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T05:40:24.168140+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=187", "doc_key": "e86b4d5894997f64f5d124801f299760"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fd9776e7c018148a567c159d5079f2fe6c826e71d23ecc52af5c1c40b40daeab'),
  ('cpiuris2025::7ff3a8dd6d23244cd7bb2a9f71d1656d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Ajuizamento de ações individuais e coletivas', '## Ajuizamento de ações individuais e coletivas

O ajuizamento de demanda coletiva por qualquer legitimado interrompe o prazo prescricional da causa, mas não impede o ajuizamento de ação individual posteriormente proposta.

### Conceitos
- **Ajuizamento de demanda coletiva**: Ação que envolve vários consumidores
- **Prazo prescricional**: Prazo dentro do qual deve ser exercida uma ação
- **Interrupção da prescrição**: Atividade que interrompe o prazo prescricional

### Referências legais
- Art. 104 da Lei n. 8.078/1990

### Jurisprudência
- REsp 1426620/RS
- REsp 1.761.874/SC
- REsp 1.758.708/MS
- REsp 1.388.000/PR

### Dicas de prova
- Entenda a diferença entre ajuizamento de demanda coletiva e individual
- Conheça as regras sobre interrupção da prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104 da Lei n. 8.078/1990"], "jurisprudence": ["REsp 1426620/RS", "REsp 1.761.874/SC", "REsp 1.758.708/MS", "REsp 1.388.000/PR"], "confidence": 0.8, "extracted_at": "2026-05-30T05:41:01.437851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=188", "doc_key": "7ff3a8dd6d23244cd7bb2a9f71d1656d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'befa5f95b10a58eb423d6704d71a4e7576a4756dd8c204c837e7ee352a39e7d1'),
  ('cpiuris2025::731498a7a5b84be1abd8c09ae85ba44e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cosa julgada e direitos individuais homogêneos', '## Cosa julgada e direitos individuais homogêneos

A coisa julgada é secundum eventum litis, só se forma em caso de procedência. Os direitos individuais homogêneos não são prejudicados pelos direitos difusos e coletivos.

### Conceitos
- **Cosa julgada**: Conceito jurídico que se refere à situação em que uma decisão de um processo é considerada definitiva e não pode ser reavaliada
- **Direitos individuais homogêneos**: Direitos que são iguais para todos os membros da coletividade, como o direito à indenização por danos morais
- **Direitos difusos**: Direitos que são compartilhados por uma categoria de pessoas, mas não são iguais para todos os membros da coletividade
- **Coletivos**: Direitos que são compartilhados por um grupo ou classe de pessoas

### Referências legais
- Art. 103, § 1º do CDC
- Art. 103, § 2º do CDC
- Art. 104 do CDC
- Lei n.º 4.717/65 (Lei de Ação Popular)

### Jurisprudência
- REsp nº 1.243.887/PR e REsp nº 1.525.327/PR

### Dicas de prova
- Entenda a diferença entre direitos individuais homogêneos, difusos e coletivos
- Conheça as regras de coisa julgada e prescrição para as ações coletivas
- Aprenda a aplicar os arts. 103 e 104 do CDC em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 103, § 1º do CDC", "Art. 103, § 2º do CDC", "Art. 104 do CDC", "Lei n.º 4.717/65 (Lei de Ação Popular)"], "jurisprudence": ["REsp nº 1.243.887/PR e REsp nº 1.525.327/PR"], "confidence": 0.8, "extracted_at": "2026-05-30T05:41:34.967966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=188", "doc_key": "731498a7a5b84be1abd8c09ae85ba44e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd3e1a55f0e6829dd7261b1550b0cfac9452a4bc0cf757a24ceea2b233151fa36'),
  ('cpiuris2025::0f681a75bb84d60c07597c327b7b9c31', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Competência e Processo da Ação Popular', '## Competência e Processo da Ação Popular

A competência para a ação popular é relativa e depende da hipossuficiência ou barreira ao acesso à justiça. O consumidor pode escolher o foro, mas apenas se houver hipossuficiência.

### Conceitos
- **Competência Relativa**: Dependente da hipossuficiência ou barreira ao acesso à justiça
- **Hipossuficiência**: Situação em que o consumidor não tem recursos suficientes para defender seus direitos
- **Barreira ao Acesso à Justiça**: Obstáculo que impede o consumidor de acessar a justiça
- **Cláusula de Eleição de Foro**: Cláusula do contrato que estabelece o foro competente para a ação
- **Denunciação da Lide**: Procedimento pelo qual o réu chama ao processo a seguradora, se houver seguro de responsabilidade

### Referências legais
- Art. 101 do CDC
- Art. 6º, VII do CDC
- Art. 51, XV do CDC
- Art. 63, § 3º do CPC/15
- Art. 125, II do CPC/15

### Jurisprudência
- REsp 1.736.091/PE
- REsp 1.675.012/SP

### Dicas de prova
- Entenda a competência relativa e como ela depende da hipossuficiência ou barreira ao acesso à justiça
- Conheça as hipóteses em que o magistrado pode declarar a nulidade da cláusula de eleição de foro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 101 do CDC", "Art. 6º, VII do CDC", "Art. 51, XV do CDC", "Art. 63, § 3º do CPC/15", "Art. 125, II do CPC/15"], "jurisprudence": ["REsp 1.736.091/PE", "REsp 1.675.012/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T05:42:39.170724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=189", "doc_key": "0f681a75bb84d60c07597c327b7b9c31"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b8d652de31002d65e87f2e65cd34de184b33c11eb812dd2b5dca2244acc70bd0'),
  ('cpiuris2025::4a81c870456dc63cae05973c5c61a266', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Legitidade e Ações Contra o Poder Público', '## Legitidade e Ações Contra o Poder Público

O artigo 101 do CDC estabelece a legitimidade para agir em ações contra terceiros, incluindo a possibilidade de ação direta contra o segurador. O artigo 102 permite ação contra o Poder Público para proibir produtos nocivos à saúde pública e à incolumidade pessoal.

### Conceitos
- **Legitidade**: O direito de agir em uma ação
- **Ações Contra Terceiros**: Ações que envolvem terceiros, como seguradores ou empresas
- **Ação Direta Contra o Segurador**: Ação direta contra o segurador em caso de falência do réu
- **Legitimidade para Agir**: O direito de agir em uma ação, estabelecido pelo Código de Defesa do Consumidor
- **Proibição de Produtos**: Ação que visa proibir a produção, divulgação, distribuição ou venda de produtos nocivos à saúde pública e à incolumidade pessoal
- **Poder Público**: O Estado ou suas entidades

### Referências legais
- Art. 101 do CDC

### Dicas de prova
- Entenda a legitimidade para agir em ações contra terceiros
- Conheça a ação direta contra o segurador em caso de falência do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 101 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:42:43.427037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=189", "doc_key": "4a81c870456dc63cae05973c5c61a266"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3acedad88fc264b1deb137b55c53ece0c1af0f05a0a41cab1d90f51368ee76da'),
  ('cpiuris2025::e44e8394dbe8ff0490c31a54bcbb8ea9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Interesses Individuais Homogêneos', '## Interesses Individuais Homogêneos

A questão discute a definição de interesses individuais homogêneos, que são direitos coletivos compartilhados por um grupo ou classe de consumidores. A resposta correta é aquela que afirma que esses interesses podem ser exercidos em juízo individualmente.

### Conceitos
- **Interesses Individuais Homogêneos**: Direitos coletivos compartilhados por um grupo ou classe de consumidores
- **Legitimidade para Atuar em Defesa dos Consumidores**: O Ministério Público tem legitimidade para atuar em defesa dos interesses individuais homogêneos dos consumidores

### Referências legais
- Art. 82 do Código de Defesa do Consumidor

### Jurisprudência
- Súmula 236/STJ

### Dicas de prova
- Entenda a noção de interesses individuais homogêneos e sua relação com a legitimidade para atuar em defesa dos consumidores
- Leia a legislação específica sobre interesses individuais homogêneos e suas implicações práticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 82 do Código de Defesa do Consumidor"], "jurisprudence": ["Súmula 236/STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T05:44:58.144195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=190", "doc_key": "e44e8394dbe8ff0490c31a54bcbb8ea9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9815605c8deef9b8a30e5b1d47af3e678d84df9402ea22d892d7d9f6121386bf'),
  ('cpiuris2025::5042848a1daca4a31c3244b864a78531', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Legitidade para propor ação civil pública pelo Ministério Público', '## Legitidade para propor ação civil pública pelo Ministério Público

A legitimidade para propor ação civil pública pelo Ministério Púbico depende de caso em que se tutela Direito Indisponível ou Direito Disponível de relevante interesse social ou repercussão no interesse público.

### Conceitos
- **Legitidade**: O direito de agir em um determinado processo
- **Ação Civil Pública**: Processo que visa tutelar direitos individuais homogêneos
- **Direito Indisponível**: Direito que não pode ser negado ou limitado por lei ou regulamento
- **Direito Disponível**: Direito que pode ser negado ou limitado por lei ou regulamento
- **Legitimidade do Ministério Público**: O direito do Ministério Público de agir em um determinado processo

### Referências legais
- Art. 103, III do CDC
- RE 500.879-AgR
- RE 472.489-AgR

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Diferenciar entre direito individual e coletivo
- Entender a noção de legitimidade do Ministério Público
- Conhecer as regras sobre ação civil pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 103, III do CDC", "RE 500.879-AgR", "RE 472.489-AgR"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T05:45:31.803891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=190", "doc_key": "5042848a1daca4a31c3244b864a78531"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'dacf2c3e80594c00b18b2254676a4244a9d7cc76989b4e7afdc1174cb1436eb5'),
  ('cpiuris2025::c1860d245058244ca66dcac06ff0e5c4', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Defesa do consumidor em juízo', '## Defesa do consumidor em juízo

O art. 104 do CDC estabelece que as ações coletivas não induzem litispendência para as ações individuais, mas os efeitos da coisa julgada erga omnes não beneficiarão os autores das ações individuais se não for requerida sua suspensão.

### Conceitos
- **Litispendência**: Conceito jurídico que se refere à situação em que duas ou mais ações têm como objeto o mesmo direito e são processadas simultaneamente.
- **C coisa julgada erga omnes**: Efeito da decisão judicial que se estende a todos os interessados, independentemente deles terem sido parte do processo ou não.
- **Suspensão de efeitos**: Método utilizado para evitar que os efeitos de uma coisa julgada erga omnes beneficiem apenas as partes envolvidas na ação coletiva.
- **Ações individuais**: Processos que são iniciados por um consumidor individualmente, em vez de como parte de uma ação coletiva.
- **Ações coletivas**: Processos que são iniciados para proteger os direitos de vários consumidores, geralmente em relação a uma prática comercial específica.
- **Art. 104 do CDC**: Disposição do Código de Defesa do Consumidor que estabelece regras sobre as ações coletivas e individuais.
- **CPC/2015**: Código de Processo Civil de 2015, que alterou as regras processuais brasileiras.

### Referências legais
- Art. 104 do CDC

### Jurisprudência
- REsp 1243887/PR
- REsp 1370899-SP
- REsp 1.821.688

### Dicas de prova
- Entenda a diferença entre litispendência e coisa julgada erga omnes.
- Conheça as regras sobre suspensão de efeitos em ações coletivas.
- Aprenda com o art. 104 do CDC e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.191", "page_number": 191, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 104 do CDC"], "jurisprudence": ["REsp 1243887/PR", "REsp 1370899-SP", "REsp 1.821.688"], "confidence": 0.8, "extracted_at": "2026-05-30T05:46:34.640085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=191", "doc_key": "c1860d245058244ca66dcac06ff0e5c4"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd28d1dbca7657e5d59b74c5dea7ed61cf3bfb3735b6e52e28af161973da13df5'),
  ('cpiuris2025::4fd829a13b44147b51ae43dc9b20c457', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Ações Civis Originárias e Recursos Especiais', '## Ações Civis Originárias e Recursos Especiais

Lista de ações civis originárias e recursos especiais, incluindo agravo de instrumento, agravo de recurso especial e agravo regimental.

### Conceitos
- **Ação Cível Originária**: Processo iniciado pelo consumidor contra o vendedor ou fornecedor
- **Recursos Especiais**: Recurso apresentado ao tribunal para apreciar a legalidade de uma decisão proferida por um juiz de primeiro grau
- **Agravo de Instrumento**: Recurso apresentado ao tribunal para revisar ou anular uma decisão proferida por um juiz de primeiro grau

### Referências legais
- Art. 81 da Lei nº 8.078/1990

### Dicas de prova
- Entenda a diferença entre ação cível originária e recurso especial
- Conheça as formas de agravo (instrumental, recursal e regimental)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.193", "page_number": 193, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 81 da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:47:08.437895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=193", "doc_key": "4fd829a13b44147b51ae43dc9b20c457"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '564d316a467c279a882228a2b98c747648e7015120538d8b88c08aab7953c7cd'),
  ('cpiuris2025::aa4b69a7ad6e5a019a9cfcc74a365aba', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Agravo Regimental no REsp', '## Agravo Regimental no REsp

Resumo de agravos regimentais apresentados em recurso especial no Direito do Consumidor.

### Conceitos
- **Agravo Regimental**: Recurso apresentado para revisar uma decisão do juiz de primeiro grau
- **REsp**: Recurso Especial, um recurso que visa a revisão de uma decisão do juiz de primeiro grau em segunda instância
- **Agravo**: Recurso apresentado para revisar uma decisão do juiz de segundo grau

### Referências legais
- Art. 1.234 da Lei nº 9.506/1998
- Súmula 345 do STJ

### Jurisprudência
- REsp 735.249/SC
- REsp 1.122.507/PR

### Dicas de prova
