  ('cpiuris2025::0c32c7875710c2cd89c8af98c886d2fb', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Referências Bibliográficas', '## Referências Bibliográficas

Lista de livros e artigos que fazem referência a temas relacionados ao Direito do Consumidor.

### Conceitos
- **Interesses Difusos**: Direitos coletivos que protegem o consumidor em geral.
- **Coletivos**: Direitos que protegem um grupo de pessoas com interesses semelhantes.
- **Vulnerabilidade**: Condição que torna o consumidor mais suscetível a abusos.
- **Superendividamento**: Situação em que o consumidor está sob o controle de um credor.
- **Leis Penais Especiais**: Legislação que regula crimes relacionados ao consumo.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- EAREsp 664.888 / RS, Ministro Herman Benjamin

### Dicas de prova
- Entenda a importância das referências bibliográficas no Direito do Consumidor.
- Identifique os principais conceitos relacionados à vulnerabilidade e superendividamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.203", "page_number": 203, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "EAREsp 664.888 / RS, Ministro Herman Benjamin"], "confidence": 0.8, "extracted_at": "2026-05-30T05:53:49.512948+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=203", "doc_key": "0c32c7875710c2cd89c8af98c886d2fb"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd9365caf0ea7ddd77845b7e84a4855c0b721b84c485df759f2691ed12c65c58e'),
  ('cpiuris2025::9560f4850cf8a1f928bd6af10eeb1aed', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Autores do material', '## Autores do material

Informações sobre os autores do texto, destacando suas qualificações e experiências profissionais.

### Conceitos
- **Advogado**: Profissional qualificado para representar interesses jurídicos
- **Mestrando**: Título acadêmico de especialização em Direito
- **Procurador**: Funcionário público responsável por defender os interesses do Estado ou de uma entidade específica
- **Concurso**: Processo seletivo para a contratação de funcionários públicos

### Dicas de prova
