- Reconhecer a importância das qualificações acadêmicas e profissionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.3", "page_number": 3, "discipline": "Direitos Financeiro", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:53:53.027720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=3", "doc_key": "9560f4850cf8a1f928bd6af10eeb1aed"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '4c81ad66637e4fb53954b69ac7d6210a4ab8266d64bdb2cdfca164f81116cbc7'),
  ('cpiuris2025::1c8ef1053053b5ce05e6e5c48e6ce198', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Introdução ao Direito Financeiro', '## Introdução ao Direito Financeiro

Disciplina que aborda as regras e princípios que regem a atividade financeira, incluindo contratos financeiros, operações de crédito e investimentos.

### Conceitos
- **Direito Financeiro**: Brancha do direito que regula a atividade financeira
- **Contrato Financeiro**: Acordo entre duas ou mais partes que envolve a transferência de riscos e direitos
- **Operação de Crédito**: Atividade financeira que envolve o fornecimento de crédito a um cliente
- **Investimento**: Ação de colocar recursos em uma atividade econômica com o objetivo de obter lucro

### Referências legais
- Art. 1.231 do Código Civil
- Súmula 394 da Súmula Técnica do STF

### Jurisprudência
- RE 123456/DF
- Tema repetitivo: natureza jurídica dos contratos financeiros

### Dicas de prova
- Entenda a definição de Direito Financeiro e sua importância na atividade financeira
- Conheça as principais características dos contratos financeiros e operações de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.2", "page_number": 2, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 1.231 do Código Civil", "Súmula 394 da Súmula Técnica do STF"], "jurisprudence": ["RE 123456/DF", "Tema repetitivo: natureza jurídica dos contratos financeiros"], "confidence": 0.8, "extracted_at": "2026-05-30T05:53:59.369647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=2", "doc_key": "1c8ef1053053b5ce05e6e5c48e6ce198"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '5e6175904f0843f95100e255473754ecd120e8bae37c7c3c382fff6145b7c4f2'),
  ('cpiuris2025::002c19d91fafc5644508272f9b6b4258', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Atividade financeira do Estado e Orçamento Público', '## Atividade financeira do Estado e Orçamento Público

Descreve a atividade financeira do Estado, principais fontes do Direito Financeiro, competência e natureza jurídica do Orçamento Público.

### Conceitos
- **Objeto de estudo**: atividade financeira do Estado
- **Competência**: área onde o Estado exerce poderes financeiros
- **Orçamento Participativo**: mechanismo que envolve a participação da sociedade na elaboração do Orçamento Público

### Referências legais
- Art. 100 da Constituição Federal
- Súmula 634/STF

### Dicas de prova
- Entenda a competência do Estado em relação à atividade financeira
- Conheça as principais fontes do Direito Financeiro e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da Constituição Federal", "Súmula 634/STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:55:37.262963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=4", "doc_key": "002c19d91fafc5644508272f9b6b4258"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '4ecea292d08d38576c66e7bd5dacf2e8f7265fff511e70ef5f4f2fb5fb27107e'),
  ('cpiuris2025::a548bd63e94efe66f8c0170d35861bad', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento Público', '## Orçamento Público

Descreve as fontes e os ciclos do orçamento público, incluindo iniciativa, apreciação, execução e controle.

### Conceitos
- **Iniciativa**: Ato de apresentar o Orçamento Público ao Legislativo.
- **Apreciação (Deliberação)**: Procedimento pelo qual o Legislativo analisa e aprova o Orçamento Público.
- **Execução**: Fase do orçamento em que as despesas são pagas e os recebimentos são registrados.
- **Controle**: Procedimento pelo qual o Executivo supervisiona a execução do Orçamento Público.
- **Plano Plurianual (PPA)**: Documento que estabelece as diretrizes gerais para o período de 3 anos seguintes.
- **Lei de Diretrizes Orçamentárias (LDO)**: Lei que estabelece as diretrizes orçamentárias para um ano civil.
- **Lei Orçamentária Anual (LOA)**: Lei que aprovou o Orçamento Público para um ano civil.

### Referências legais
- Art. 167 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do ciclo orçamentário e as fontes de abertura do orçamento público.
- Conheça as diferenças entre os diferentes ciclos do orçamento público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T05:56:37.781160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=4", "doc_key": "a548bd63e94efe66f8c0170d35861bad"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '89ce95487f59603a1ca2234de8b3ce19c9f1194a553f4c2b5707976c5970ca97'),
  ('cpiuris2025::a449e5053a7b22622c824745f3ebe3b7', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Princípios e Leis Orçamentárias', '## Princípios e Leis Orçamentárias

Resumo dos principios orçamentários, incluindo legalidade, exclusividade, programação, equilíbrio, anualidade, unidade, universalidade, orçamento bruto, transparência e especificação.

### Conceitos
- **Legalidade**: O princípio de que o orçamento deve ser aprovado por lei.
- **Exclusividade**: O princípio de que os recursos públicos devem ser utilizados exclusivamente para fins públicos.
- **Programação**: A definição do que será feito com os recursos orçamentários.
- **Equilíbrio Orçamentário**: O equilíbrio entre as receitas e despesas públicas.
- **Anualidade**: A aplicação dos princípios orçamentários apenas a um ano específico.
- **Unidade**: A utilização de uma unidade de medida para todas as despesas públicas.
- **Universalidade**: A cobertura de todos os setores públicos pelo orçamento.
- **Orçamento Bruto**: O valor total das receitas e despesas públicas.

### Referências legais
- Art. 71 da Constituição Federal
- Lei nº 4.300/1964

### Dicas de prova
- Entenda a importância da legalidade e exclusividade nos princípios orçamentários.
- Conheça o conceito de equilíbrio orçamentário e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71 da Constituição Federal", "Lei nº 4.300/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:57:07.138455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=4", "doc_key": "a449e5053a7b22622c824745f3ebe3b7"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'eeb311253b1877e7a56c33d74a675d6648f60618a74fafa64d5a203ab6654e54'),
  ('cpiuris2025::619092534ea1201d47b3b2235ddce903', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receitas Públicas', '## Receitas Públicas

Definição e classificação das receitas públicas, considerando periodicidade, sentido, competência e origem.

### Conceitos
- **Receita Pública**: Gênero de receita do Estado
- **Periodicidade**: Característica da receita que se repete em um determinado período
- **Sentido**: Amplitude ou escopo da receita
- **Competência**: Ente federativo responsável pela receita
- **Origem**: Fonte da receita

### Referências legais
- Art. 96 da Constituição Federal

### Dicas de prova
- Diferenciar entre receitas ordinárias e extraordinárias
- Entender a competência do ente federativo em relação às receitas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 96 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:57:11.736706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=5", "doc_key": "619092534ea1201d47b3b2235ddce903"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '9f3bae1d0c7fc0a58170db62a80e1eafc458a6d6ef5f0fef9f7d787b85fda36a'),
  ('cpiuris2025::504ecb3f4ea7f600b86d35c88516d95c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Correntes e Capital', '## Despesas Correntes e Capital

Artigos que definem despesas correntes e de capital, bem como a classificação das despesas públicas em fases.

### Conceitos
- **Despesa Corrente**: Despesa necessária para o funcionamento diário do governo
- **Despesa de Capital**: Gastos realizados para aquisição ou manutenção de ativos duradouros

### Referências legais
- Art. 3.4 da Lei X

### Dicas de prova
- Entenda a distinção entre despesas correntes e de capital.
- Conheça as fases das despesas públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.5 (4)", "page_number": 5, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 3.4 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:58:23.442836+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=5", "doc_key": "504ecb3f4ea7f600b86d35c88516d95c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a9bb318e1ac3b4051da010453cee473a99ea9de37c8dfb95367d787433a908fb'),
  ('cpiuris2025::b7b7ede7172a5c6a58bf31d902a7e810', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Classificação e Natureza das Receitas Públicas', '## Classificação e Natureza das Receitas Públicas

O texto aborda a classificação e natureza das receitas públicas, incluindo originárias, derivadas, orçamentárias e extraorçamentárias, bem como as categorias econômicas e os processos de previsão, lançamento, arrecadação e recolhimento.

### Conceitos
- **Receitas Públicas**: Benefícios recebidos pelo Estado ou entidades públicas
- **Classificação Legal**: Categorização das receitas em função de sua natureza econômica
- **Orçamentária**: Receita que faz parte do orçamento público
- **Extraorçamentária**: Receita não incluída no orçamento público

### Referências legais
- Art. 96 da Lei 8.137/1990

### Dicas de prova
- Entenda a distinção entre receitas originárias e derivadas
- Conheça as categorias econômicas e suas implicações jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 96 da Lei 8.137/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:58:31.761592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=5", "doc_key": "b7b7ede7172a5c6a58bf31d902a7e810"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '9ae7123b823073998851b1e5566777227a22b46697616cde2a9e7b67bb4c5d4d'),
  ('cpiuris2025::bd5752e77beaa8496123ad4f7d28fddd', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita Corrente Líquida (RCL) e responsabilidade na gestão fiscal', '## Receita Corrente Líquida (RCL) e responsabilidade na gestão fiscal

Trecho sobre Receita Corrente Líquida, responsabilidade na gestão fiscal e sanções pela ineficiência arrecadatória.

### Conceitos
- **Receita Corrente Líquida (RCL)**: Valor líquido das receitas correntes de uma empresa ou entidade.
- **Responsabilidade na Gestão Fiscal**: Obrigação do ente público de gerenciar suas receitas e despesas de forma eficiente.
- **Sanções pela ineficiência arrecadatória**: Medidas legais impostas ao ente público para garantir a arrecadação de receitas de forma eficiente.
- **Renúncia de Receita**: Ato pelo qual o ente público renuncia a receber uma determinada receita tributária.
- **Repartição de Receitas Tributárias**: Processo pelo qual as receitas tributárias são distribuídas entre os entes públicos responsáveis por sua arrecadação.

### Referências legais
- Art. 105 da Lei 8.137/1990

### Dicas de prova
- Entenda a importância da Receita Corrente Líquida e sua relação com a responsabilidade na gestão fiscal.
- Conheça as sanções impostas pela ineficiência arrecadatória e como elas afetam o ente público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 105 da Lei 8.137/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:59:33.617075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=5", "doc_key": "bd5752e77beaa8496123ad4f7d28fddd"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '35439e0431e61e71b304d0dbba7c770fca2068d58c84a17137a75b26f802499f'),
  ('cpiuris2025::e630ecb23e2d88ee2797ba2c0c8bb2db', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Empenho e Pagamento', '## Empenho e Pagamento

Trecho aborda os tipos de empenho, possibilidade de cancelamento, liquidação e pagamento de despesas públicas.

### Conceitos
- **Empenho**: acordo pelo qual o Estado compromete-se a pagar uma determinada despesa no futuro.
- **Liquidação**: processo que visa resolver as dúvidas sobre a natureza e a extensão de uma despesa.
- **Pagamento**: ação pelo qual o Estado efetiva o pagamento de uma despesa.

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a diferença entre empenho e precatório.
- Conheça as regras gerais de liquidação e pagamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T05:59:58.903967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=6", "doc_key": "e630ecb23e2d88ee2797ba2c0c8bb2db"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2a6a2f676143e45dc3025a7ff95d8381f6ec98e16ac161407822930cbbd1fbea'),
  ('cpiuris2025::820d22ddd63a77eed104fba3c1dc7696', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Lei de Responsabilidade Fiscal', '## Despesas Públicas e Lei de Responsabilidade Fiscal

Trecho aborda as regras sobre despesas públicas, limitação de empenho, geração de despesa, desapropriação de imóvel urbano e DOCC.

### Conceitos
- **Despesa Obrigatória de Caráter Continuado (DOCC)**: Despesa que deve ser contabilizada continuamente
- **Desapropriação de imóvel urbano**: Ato pelo qual o Estado adquire a propriedade de um imóvel para fins públicos

### Referências legais
- Art. 96 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre DOCC e despesa obrigatória de capital
- Conheça as exceções ao cômputo dos gastos com pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 96 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:00:07.357394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=6", "doc_key": "820d22ddd63a77eed104fba3c1dc7696"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0c8541275a537a287e1d3f2f69e62a0df8a27f15a07f76f8455624231def66ed'),
  ('cpiuris2025::7dc03ca94d6047ccf23c82da83bfe01f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Critérios para o controle e Classificações do crédito público', '## Critérios para o controle e Classificações do crédito público

Descreve os critérios e classificações utilizadas no controle do crédito público, destacando a importância dessas categorias na gestão financeira.

### Conceitos
- **Controle de crédito**: Mecanismo que visa regular e fiscalizar o uso dos recursos financeiros
- **Classificação do crédito público**: Categorização do crédito público em diferentes níveis, como federal, estadual e municipal

### Referências legais
- Art. 100 da Lei 8.666/1993

### Dicas de prova
- Entenda a importância dos critérios de controle no contexto financeiro
- Destaque as classificações do crédito público para uma gestão eficaz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.6 (4)", "page_number": 6, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da Lei 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:01:22.159231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=6", "doc_key": "7dc03ca94d6047ccf23c82da83bfe01f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '1b675b9e1a2ec43aaed69d8141a5491f06c216be94bca578f8209d7b241a3180'),
  ('cpiuris2025::a743615d18cf97e71e1ccca75f52a715', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle dos gastos com pessoal e transferências', '## Controle dos gastos com pessoal e transferências

Regras para controle de gastos com pessoal, transferências obrigatórias e voluntárias, além de sanções e princípios aplicáveis.

### Conceitos
- **Limite de alerta**: Limites estabelecidos para controle dos gastos com pessoal
- **Limite prudencial**: Máximo permitido para despesas com pessoal
- **Excesso de despesa e sanções**: Sanciones aplicadas em caso de superaventagem de gastos com pessoal
- **Transferências obrigatórias**: Despesas compulsórias para a seguridade social
- **Transferências voluntárias**: Despesas que podem ser autorizadas pelo ente público
- **Princípio da Intranscendência Subjetiva das Sanções**: Não se pode exceder a sanção estabelecida

### Referências legais
- Art. 10, § 4º da Lei nº 8.666/1993
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre limites de alerta e prudencial
- Conheça os requisitos para transferências voluntárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 10, § 4º da Lei nº 8.666/1993", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:01:50.525570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=6", "doc_key": "a743615d18cf97e71e1ccca75f52a715"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c6a405a7a172fd17b35d7a5c55cc35066a6ca4a7da9751294903e7be009203b7'),
  ('cpiuris2025::6d88739150cbab250a7dce2dbc23daf6', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Coercitividade e Temporalidade das Obrigações Públicas', '## Coercitividade e Temporalidade das Obrigações Públicas

O texto aborda a coercitividade e temporalidade das obrigações públicas, incluindo as regras para a dívida pública flutuante e fundada ou consolidada.

### Conceitos
- **Coercitividade**: A capacidade de um título de obrigação pública de ser executado por meio da força do Estado.
- **Temporalidade**: O prazo dentro do qual uma obrigação pública deve ser satisfeita.
- **Dívida Pública Flutuante**: A dívida pública que não está sujeita a um prazo específico de pagamento.
- **Dívida Pública Fundada ou Consolidada**: A dívida pública que tem um prazo específico de pagamento e é consolidada em um único valor.

### Referências legais
- Art. 96 da CF/88
- Súmula 634 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Coercitividade e Temporalidade

### Dicas de prova
- Entenda a diferença entre coercitividade e temporalidade nas obrigações públicas.
- Conheça as regras para a dívida pública flutuante e fundada ou consolidada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 96 da CF/88", "Súmula 634 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Coercitividade e Temporalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T06:02:24.631532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=7", "doc_key": "6d88739150cbab250a7dce2dbc23daf6"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '5e84e4b27da295e850476059f4d2814291d59de9dc07a9cc928a6aea3e30539a'),
  ('cpiuris2025::8c797cc4fdc4ca2df7517133abcfb70f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência do Tribunal de Contas', '## Competência do Tribunal de Contas

Discute as competências do Tribunal de Contas, incluindo julgamento de contas, controle dos atos de pessoal e fiscalização.

### Conceitos
- **Tribunal de Contas**: órgão responsável pela fiscalização e controle dos atos do Poder Executivo
- **Competência**: área de conhecimento ou jurisdição de um órgão ou tribunal
- **Julgamento de contas**: processo pelo qual o Tribunal de Contas examina as contas dos administradores e demais responsáveis por valores públicos
- **Controle dos atos de pessoal**: fiscalização sobre os atos do Poder Executivo em relação ao pessoal público
- **Fiscalização**: ação de controlar ou monitorar o desempenho de uma entidade ou órgão

### Referências legais
- Art. 101 da Constituição Federal
- Lei nº 4.737/1965

### Jurisprudência
- RE 123456
- Tema repetitivo do controle dos atos de pessoal

### Dicas de prova
- Entenda a competência do Tribunal de Contas e suas atribuições
- Identifique as diferenças entre julgamento de contas e controle dos atos de pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 101 da Constituição Federal", "Lei nº 4.737/1965"], "jurisprudence": ["RE 123456", "Tema repetitivo do controle dos atos de pessoal"], "confidence": 0.8, "extracted_at": "2026-05-30T06:03:47.384878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=7", "doc_key": "8c797cc4fdc4ca2df7517133abcfb70f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd380c1c208233c7fc6d27644e7c3e547c5a42d538b01680681590c237b532483'),
  ('cpiuris2025::a1e34328fa575bdbf84829dc0e003b6f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Atividade financeira do Estado e Orçamento Público', '## Atividade financeira do Estado e Orçamento Público

A atividade financeira do Estado é composta por receita pública, despesa pública, orçamento público e crédito público. O Direito Financeiro busca entender todas as etapas envolvidas na gestão desses elementos.

### Conceitos
- **Atividade financeira**: Gestão da receita e despesa públicas
- **Receita pública**: Obtenção de recursos públicos
- **Despesa pública**: Dispêndio (gastos) de recursos públicos
- **Orçamento público**: Gestão da atividade financeira estatal a partir do cotejamento entre gastos e receitas públicas
- **Crédito público**: Empréstimos utilizados para viabilizar o equilíbrio orçamentário

### Referências legais
- Art. 5 da Lei nº 5.172/1966

### Jurisprudência
- Súmula 395 do STF

### Dicas de prova
- Entenda a distinção entre o Direito Financeiro e o Direito Tributário
- Conheça os quatro elementos que compõem a atividade financeira do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.8", "page_number": 8, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 5 da Lei nº 5.172/1966"], "jurisprudence": ["Súmula 395 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T06:04:13.131280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=8", "doc_key": "a1e34328fa575bdbf84829dc0e003b6f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '02743059c83f5560ae02451139ec0d04f86d531f6ba1f7e19c556225811fb0a9'),
  ('cpiuris2025::3107169fcb6f3873e4988fc7b629e8eb', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Principais fontes do Direito Financeiro', '## Principais fontes do Direito Financeiro

As fontes do Direito Financeiro são materiais e formais, sendo as fontes materiais os eventos sociais, políticos e econômicos que desencadeiam a necessidade de regulação normativa, e as fontes formais a forma de exteriorização dessas normas.

### Conceitos
- **fonte material**: eventos sociais, políticos e econômicos que desencadeiam a necessidade de regulação normativa
- **fonte formal**: forma de exteriorização das normas
- **Constituição Federal**: fonte precípua do Direito Financeiro
- **Lei Complementar**: veicula normas gerais de Direito Financeiro

### Referências legais
- Art. 70 a 75 da CF/88
- Art. 157 a 164 da CF/88
- Art. 165 e seguintes da CF/88

### Dicas de prova
- Entenda a distinção entre fontes materiais e formais do Direito Financeiro.
- Conheça as principais fontes do Direito Financeiro, como a Constituição Federal e a Lei Complementar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 70 a 75 da CF/88", "Art. 157 a 164 da CF/88", "Art. 165 e seguintes da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:04:26.589626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=9", "doc_key": "3107169fcb6f3873e4988fc7b629e8eb"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'fb653d0960ca3500b8b351b832cce69b0b71f663855961105bbfbb4ad78906a6'),
  ('cpiuris2025::688f3c3be87ac838a8edbe5c36bbd92c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Regulação do Orçamento Público', '## Regulação do Orçamento Público

O artigo regula as competências da lei complementar para dispor sobre o exercício financeiro, a vigência, os prazos, a elaboração e a organização do plano plurianual, entre outras questões.

### Conceitos
- **Plano Plurianual**: Documento que estabelece as diretrizes orçamentárias para um período de três anos
- **Lei Orçamentária Anual**: Lei que aprovada anualmente, que estabelece os limites financeiros da administração pública

### Referências legais
- Art. 165
- EC nº 109 de 2021
- EC nº 135 de 2024

### Dicas de prova
- Entenda a importância do plano plurianual e da lei orçamentária anual
- Conheça as competências da lei complementar em matéria financeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165", "EC nº 109 de 2021", "EC nº 135 de 2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:04:43.772478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=9", "doc_key": "688f3c3be87ac838a8edbe5c36bbd92c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'cf741fdd22a1500b067d436759ffeacb3b4196a0e0d684e8359184e95b74e37f'),
  ('cpiuris2025::51178da9723b59aed163ea6044533c43', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência Legislativa dos Municípios', '## Competência Legislativa dos Municípios

A competência legislativa dos municípios é determinada pela Constituição Federal de 1988, especificamente nos arts. 24 e 30. A interpretação desses dispositivos revela que os municípios têm competência concorrente com a União e os estados para legislar sobre assuntos de interesse local.

### Conceitos
- **Competência Legislativa**: O direito do Estado ou da entidade política de legislar sobre determinados assuntos
- **Concorrência**: A existência de mais de uma fonte de direito que tem a mesma competência para regular um mesmo assunto
- **Legislação Federal e Estadual**: As leis emitidas pela União e pelos estados, respectivamente
- **Competência Concordante**: A competência que é compartilhada entre diferentes entidades políticas para regular um mesmo assunto

### Referências legais
- Art. 24 da CF/88
- Art. 30 da CF/88

### Dicas de prova
- Entenda a noção de competência legislativa e concorrência
- Conheça os arts. 24 e 30 da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 24 da CF/88", "Art. 30 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:07:09.605673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=10", "doc_key": "51178da9723b59aed163ea6044533c43"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e7060ffd50f8ff0ab3c391195b2702c4c5463180fc9a5ff96231c260133814ee'),
  ('cpiuris2025::9ef0e631a91ad21170487bde7b9435a4', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência Suplementar e Orçamento Público', '## Competência Suplementar e Orçamento Público

A competência suplementar é exercida pelos municípios, que podem legislar em concorrência com os demais entes no que se refere ao Direito Financeiro, desde que vinculada ao interesse local. O orçamento público é um instrumento de controle do arbítrio estatal e deve guardar consonância com as despesas autorizadas e as receitas previstas.

### Conceitos
- **Competência Suplementar**: Exercida pelos municípios, que podem legislar em concorrência com os demais entes no que se refere ao Direito Financeiro.
- **Orçamento Público**: Instrumento de controle do arbítrio estatal e fixador de despesa que efetiva a previsão de receitas.
- **Legitimidade das Decisões**: Deve guardar consonância com as despesas autorizadas e as receitas previstas na respectiva lei orçamentária.

### Referências legais
- Art. 30 da CF/88
- Art. 24 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência suplementar e sua relação com o orçamento público.
- Análise das etapas da atividade financeira do Estado, iniciando pelo orçamento público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 30 da CF/88", "Art. 24 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:07:20.635110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=11", "doc_key": "9ef0e631a91ad21170487bde7b9435a4"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e3da1ad80ccb4fe5ed9d7672a6636ef8c9e3667007ca5a22b237ec0b949137e6'),
  ('cpiuris2025::4cb2a4c1366367780ba3df5c78d57aea', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Leis Ordinárias e Medidas Provisórias no Direito Financeiro', '## Leis Ordinárias e Medidas Provisórias no Direito Financeiro

Descreve a função das leis ordinárias e medidas provisórias no Direito Financeiro, incluindo sua utilização para abertura de créditos extraordinários e restrições à regulamentação de matérias objeto de lei complementar.

### Conceitos
- **Lei Ordinária**: Veicula as leis orçamentárias, como o Plano Plurianual (PPA), Lei de Diretrizes Orçamentárias (LDO) e a Lei Orçamentária Anual (LOA).
- **Medida Provisória**: Usada apenas na abertura de créditos extraordinários, como exemplo: crédito adicional para acobertar situações urgentes e imprevisíveis ao orçamento público originário.
- **Lei Complementar**: Matérias objeto de lei complementar não podem ser regulamentadas por medidas provisórias.

### Referências legais
- Art. 166 (Redação dada pela EC n.º 100/19)
- Art. 167, § 3º
- Art. 163 da CF/88
- Art. 68, § 1º, III, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre leis ordinárias e medidas provisórias no Direito Financeiro.
- Conheça as restrições à regulamentação de matérias objeto de lei complementar por meio de medidas provisórias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 166 (Redação dada pela EC n.º 100/19)", "Art. 167, § 3º", "Art. 163 da CF/88", "Art. 68, § 1º, III, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:07:46.994111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=10", "doc_key": "4cb2a4c1366367780ba3df5c78d57aea"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'afa8b4621d81f0b88ec6daa7e53b3ea4f34dcb2b8f821387455794799ea5df1f'),
  ('cpiuris2025::f289fe48b3afe8e400d89912c21e7269', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento Público', '## Orçamento Público

O orçamento público é uma lei multifacetada que abrange vários aspectos, incluindo político, econômico, contábil e jurídico. Ele programa a vida financeira do Estado e permite endividamento em benefício dos interesses públicos.

### Conceitos
- **Orçamento Público**: Lei que programa a vida financeira do Estado
- **Equilíbrio Fiscal**: Situação em que as despesas públicas são cobertas pela totalidade da receita arrecadada
- **Crédito Público**: Empréstimo público utilizado para cobrir déficits orçamentários

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a concepção moderna do orçamento e sua relação com os interesses públicos
- Identifique o equilíbrio fiscal como critério para avaliação da situação financeira do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:09:11.619078+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=11", "doc_key": "f289fe48b3afe8e400d89912c21e7269"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '55dc3140630092079200568c6aa6d9745c49433f5ec70edd8aa825ecddb8ea58'),
  ('cpiuris2025::6b4835e3a79ddf71f03973a06c8a1858', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento e Planejamento Orçamentário', '## Orçamento e Planejamento Orçamentário

O orçamento de desempenho é baseado em desempenhos anteriores, enquanto o orçamento-programa tem vinculação estreita com planos/programas governamentais.

### Conceitos
- **Orçamento de Desempenho**: baseado em desempenhos anteriores
- **Orçamento-Programa**: vinculação estreita com planos/programas governamentais

### Referências legais
- Art. 77 da Lei nº 4.030/62

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre orçamento de desempenho e orçamento-programa
- Leia o artigo 77 da Lei nº 4.030/62 para entender melhor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 77 da Lei nº 4.030/62"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T06:09:29.112398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=12", "doc_key": "6b4835e3a79ddf71f03973a06c8a1858"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a2b89478701e9018ed3b2caa045c02d92b22a58361789271fdec766889a4ab00'),
  ('cpiuris2025::73225d5d6b72d88e5af5706736edf94f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Aspectos do Orçamento', '## Aspectos do Orçamento

O orçamento é um instrumento político que reflete o plano de ação do governo, sendo também um mecanismo de redistribuição de renda e regulação da economia. Ele é uma lei cogente, devendo observar as normas constitucionais e infraconstitucionais.

### Conceitos
- **Orçamento**: Mecanismo político que reflete o plano de ação do governo
- **Redistribuição de renda**: Objetivo econômico do orçamento
- **Regulação da economia**: Outro objetivo econômico do orçamento
- **Lei cogente**: Caráter jurídico do orçamento
- **Normas constitucionais**: Bases para a elaboração do orçamento
- **Trâmite legislativo**: Procedimento necessário para a modificação do orçamento
- **Controle abstrato de constitucionalidade**: Mecanismo jurídico que controla a constitucionalidade do orçamento
- **Diretriz financeira**: Objetivo geral do orçamento

### Referências legais
- Art. 77 da Constituição Federal
- Súmula 643/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Orçamento e Controle de Gastos

### Dicas de prova
- Entenda a relação entre o orçamento e os direitos fundamentais
- Conheça as espécies do orçamento (político, econômico, técnico/contábil e jurídico)
- Avalie a importância das normas constitucionais na elaboração do orçamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 77 da Constituição Federal", "Súmula 643/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Orçamento e Controle de Gastos"], "confidence": 0.8, "extracted_at": "2026-05-30T06:10:26.963882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=12", "doc_key": "73225d5d6b72d88e5af5706736edf94f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f1d5bd2400e865d75b2d0ab6d92a8a98d58138e341d1be81c269e2d891c1db36'),
  ('cpiuris2025::52a9e6511649328d74ccc4cdf792c1e0', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento Participativo', '## Orçamento Participativo

O orçamento participativo é caracterizado pela consulta à população para definição das áreas prioritárias de alocação de recursos públicos, mas não tem efeitos vinculantes sobre o Poder Executivo.

### Conceitos
- **Orçamento Participativo**: Consulta à população para definição das áreas priorizadas de alocação de recursos públicos
- **Vontade do Poder Executivo**: A capacidade do Poder Executivo de iniciar o processo legislativo e tomar decisões sobre o orçamento
- **Legislativo**: O Poder Legislativo tem competência para emendar a proposta de orçamento em tramitação
- **Consulta Popular**: A consulta à população para definição das áreas priorizadas de alocação de recursos públicos

### Referências legais
- Art. 24, § 3º da CF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre consulta popular e orçamento participativo
- Conheça a posição dos tribunais superiores sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 24, § 3º da CF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:11:23.489224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=13", "doc_key": "52a9e6511649328d74ccc4cdf792c1e0"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'edf04ce8a67e50088dbdbafeaeb43da8949d897ddff5659ba6b6d5d8e8f1e003'),
  ('cpiuris2025::fd5e77cf8c31b966eb9eff1fda44031a', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento Público e Execução Orçamentária', '## Orçamento Público e Execução Orçamentária

A lei orçamentária é ato administrativo com efeitos concretos, mas a norma estadual que torna impositiva a deliberação popular sobre proposta de lei orçamentária é inconstitucional porque limita os poderes do Executivo.

### Conceitos
- **Orçamento Público**: ato administrativo com efeitos concretos
- **Execução Orçamentária**: dever da administração de executar as programações orçamentárias
- **Inconstitucionalidade**: violação da Constituição Federal
- **Poderes do Executivo**: iniciativa e execução das ações do governo
- **Deliberação Popular**: processo em que a população decide sobre proposta de lei orçamentária
- **Consultas Populares**: procedimento em que a população expressa sua opinião sobre questões públicas
- **Técnica da Interpretação Conforme**: método utilizado para interpretar a Constituição de forma flexível

### Referências legais
- CF, art. 61, § 1º, II, “b”, c/c art. 165, III

### Jurisprudência
- ADI 2037
- RE 123456

### Dicas de prova
- Entenda a diferença entre orçamento público e execução orçamentária
- Conheça os poderes do Executivo e como eles são afetados pela norma estadual
- Aprenda sobre as consultas populares e a técnica da interpretação conforme', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direitos Financeiro", "legal_refs": ["CF, art. 61, § 1º, II, “b”, c/c art. 165, III"], "jurisprudence": ["ADI 2037", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:12:21.420841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=13", "doc_key": "fd5e77cf8c31b966eb9eff1fda44031a"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f7690ba271566254ec3a4ef2a3410d9a7bcb255f7242123eb51ce71c0cc951ed'),
  ('cpiuris2025::5ed02f138a4f89d57bc2bdefd5941665', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle de Constitucionalidade das Leis Orçamentárias', '## Controle de Constitucionalidade das Leis Orçamentárias

O Supremo Tribunal Federal entende que as leis orçamentárias podem sofrer controle de constitucionalidade, mesmo sendo de efeitos concretos. A lei orçamentária é apenas autorizativa, não impositiva.

### Conceitos
- **Controle de Constitucionalidade**: Fiscalização da constitucionalidade das leis e dos atos normativos
- **Lei Orçamentária**: Lei que prevê os gastos e autoriza as despesas do Estado
- **Autorização vs. Obrigatoriedade**: A lei orçamentária é apenas autorizativa, não impositiva

### Referências legais
- Art. 96 da Constituição Federal
- Súmula 646 do STF

### Jurisprudência
- RE 592.581/RS - Informativo 797 do STF

### Dicas de prova
- Entenda a diferença entre autorização e obrigatoriedade em relação à lei orçamentária
- Conheça o controle de constitucionalidade das leis orçamentárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 96 da Constituição Federal", "Súmula 646 do STF"], "jurisprudence": ["RE 592.581/RS - Informativo 797 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T06:12:43.574664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=14", "doc_key": "5ed02f138a4f89d57bc2bdefd5941665"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '9d3e411911b2877cc25f5082c22f479b8797df85e911fb95687eae67b79bf825'),
  ('cpiuris2025::b521445dbc79fb6bdef41f10b01cd06e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Caráter autorizativo do orçamento público', '## Caráter autorizativo do orçamento público

O caráter autorizativo do orçamento é ''em regra'', mas há exceções, como despesas impositivas e vinculações constitucionais.

### Conceitos
- **Caráter autorizativo**: O princípio de que o orçamento público deve ser aprovado por lei
- **Despesas impositivas**: Despesas que não podem ser evitadas ou suspensas sem autorização constitucional
- **Vinculações constitucionais**: Obrigação de realizar despesas mínimas em áreas como educação e saúde

### Referências legais
- Art. 165, § 10 da CF/88

### Jurisprudência
- STF - ADI 4048/DF

### Dicas de prova
- Entenda o conceito de caráter autorizativo e suas exceções
- Identifique as despesas impositivas e vinculações constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 10 da CF/88"], "jurisprudence": ["STF - ADI 4048/DF"], "confidence": 0.8, "extracted_at": "2026-05-30T06:13:21.586360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=14", "doc_key": "b521445dbc79fb6bdef41f10b01cd06e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ca98c8c6608584bbc4a502aca7f9d3a27e5de2dc1b2f99c8527b2ba88a91891b'),
  ('cpiuris2025::7ef7933ecc0834cff8ead9cbfd517a13', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Atividade financeira do estado e orçamento público', '## Atividade financeira do estado e orçamento público

O texto discute a distribuição dos recursos da União em emendas individuais, destacando a vinculação facultativa para a saúde e a obrigação de atender as emendas impositivas de forma igualitária.

### Conceitos
- **Vinculação orçamentária**: Obrigação de atender às emendas individuais de forma igualitária, independentemente da autoria
- **Emendas impositivas**: Emendas que devem ser atendidas de forma igualitária, mediante critérios objetivos e imparciais
- **Critérios equitativos**: Objetivos e imparciais para a execução das programações de caráter obrigatório

### Referências legais
- Art. 166 da Constituição
- Art. 165 da Constituição

### Dicas de prova
- Entenda a vinculação orçamentária e as emendas impositivas
- Identifique os critérios equitativos para a execução das programações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 166 da Constituição", "Art. 165 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:14:42.317807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=16", "doc_key": "7ef7933ecc0834cff8ead9cbfd517a13"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c3bc2456da886c22ac616abaa24552bcfbea4973805421977e936eda454bce3d'),
  ('cpiuris2025::628982c7cc771ba617665c78239cefe2', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Regime Fiscal Sustentável', '## Regime Fiscal Sustentável

O Regime fiscal sustentável é aplicável apenas à União, com base na despesa ajustada pelo crescimento da receita a partir do adimplemento ou não das metas fiscais.

### Conceitos
- **Despesa Ajustada**: despesa corrigida pelo crescimento da receita
- **Metas Fiscais**: metas estabelecidas para o exercício e os três exercícios subsequentes
- **Teto de Gastos**: limitação à despesa pública instituída pela EC nº 95/2016

### Referências legais
- Art. 200 da LRF
- LDO

### Dicas de prova
- Entenda a diferença entre o teto de gastos e o regime fiscal sustentável.
- Conheça as metas fiscais e sua importância no regime fiscal sustentável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 200 da LRF", "LDO"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:15:05.168693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=16", "doc_key": "628982c7cc771ba617665c78239cefe2"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '7935b00030507cf07e768b96b08356fe59a54e3a23e06a1cdef10b1364d2d811'),
  ('cpiuris2025::c83a6a3a3df0b0083d7b4c2a408f091c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento Público e Emendas Constitucionais', '## Orçamento Público e Emendas Constitucionais

Despesas incluídas e criadas na lei orçamentária, despesas cujo viés impositivo é preexistente ao orçamento, como as vinculações constitucionais nos gastos mínimos em saúde e educação.

### Conceitos
- **Vinculação pré-orçamentária**: Despesa que já existe antes da edição de uma lei orçamentária
- **Vinculação orçamentária**: Despesa autorizada pelo orçamento
- **Impositiva**: Despesa vinculada a uma norma constitucional ou legal pré-existente
- **Autorizativa**: Despesa autorizada pelo orçamento, mas não obrigatória
- **Emenda Constitucional**: Mudança feita na Constituição por meio de um processo legislativo

### Referências legais
- Art. 166 da CF/88
- EC n.º 86/2015
- EC n.º 100/2019

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Orçamento Público e Emendas Constitucionais

### Dicas de prova
- Diferenciar entre despesas impositivas e autorizativas
- Entender o conceito de vinculação pré-orçamentária e orçamentária
- Conhecer as emendas constitucionais e suas implicações no orçamento público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.15", "page_number": 15, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 166 da CF/88", "EC n.º 86/2015", "EC n.º 100/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Orçamento Público e Emendas Constitucionais"], "confidence": 0.8, "extracted_at": "2026-05-30T06:15:12.699190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=15", "doc_key": "c83a6a3a3df0b0083d7b4c2a408f091c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '29fc41acba787106578642adfc35c97a7ded4aa86c2b2c06069e81ce32f428b8'),
  ('cpiuris2025::3864e6f30dac23959f110c223a6d4ada', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Garantia de Execução de Orçamento Público', '## Garantia de Execução de Orçamento Público

A garantia de execução do orçamento público é estendida às programações incluídas em emendas parlamentares, com um limite de 1% da receita corrente líquida.

### Conceitos
- **Garantia de Execução**: obrigação do Estado de cumprir as programações orçamentárias
- **Orçamento Público**: plano financeiro do Estado que estabelece as receitas e despesas
- **Emenda Parlamentar**: mudança feita na Constituição por um grupo de deputados

### Referências legais
- Art. 166 da CF/88
- EC n.º 100/2019

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre emendas individuais e de bancada federal.
- Conheça o percentual de até 1% da receita corrente líquida que pode ser destinado às programações orçamentárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 166 da CF/88", "EC n.º 100/2019"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:16:53.421840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=17", "doc_key": "3864e6f30dac23959f110c223a6d4ada"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2e6d5255a1fcbdd9ac4ae4c0d078905fff749f49939a81ad2c9a389eb61ff260'),
  ('cpiuris2025::bfb7098ef9132b936b6d0ec275a17c98', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Diretrizes interpretativas constitucionais sobre emendas parlamentares impositivas', '## Diretrizes interpretativas constitucionais sobre emendas parlamentares impositivas

A Constitucional n.º 102 estabeleceu diretrizes para o manejo orçamentário, afirmando que não cabe à Constituição Estadual instituir a figura das programações orçamentárias fora do regramento constitucional.

### Conceitos
- **Diretrizes interpretativas constitucionais**: Preceitos estabelecidos pela Constituição para a interpretação de leis
- **Emendas parlamentares impositivas**: Mudanças feitas pelas assembleias estaduais em leis orçamentárias
- **Programações orçamentárias**: Planejamento e execução de despesas públicas

### Referências legais
- Art. 102 da Constituição Federal

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Direito constitucional e financeiro''}

### Dicas de prova
- Entenda a importância das diretrizes interpretativas constitucionais no manejo orçamentário.
- Conheça as emendas parlamentares impositivas e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 102 da Constituição Federal"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Direito constitucional e financeiro''}"], "confidence": 0.8, "extracted_at": "2026-05-30T06:17:03.753001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=17", "doc_key": "bfb7098ef9132b936b6d0ec275a17c98"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a7802f26719a406b69c4bd3d7bee2e4aada54a3c261ae94e0e74dae2e0fa2541'),
  ('cpiuris2025::5cc4e6032193ceaa4554c3e3272eb421', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência da União para editar normas gerais de direito financeiro', '## Competência da União para editar normas gerais de direito financeiro

A competência da União é estabelecida pelo artigo 24, I, e § 1º, da CF/1988, enquanto a reserva de lei complementar federal se faz pelo art. 165, § 9º, da CF/1988.

### Conceitos
- **Competência da União**: Poder do Estado Federal para editar normas gerais de direito financeiro
- **Lei Complementar Federal**: Legislação que complementa a Constituição Federal em matéria específica
- **Art. 24, I, e § 1º, da CF/1988**: Estabelece a competência da União para editar normas gerais de direito financeiro
- **Art. 165, § 9º, da CF/1988**: Reserva de lei complementar federal para a edição de normas gerais sobre elaboração da lei orçamentária anual
- **Competência Concorrente**: Poder do Estado para editar legislação em matéria específica, quando não prevista na Constituição Federal

### Referências legais
- Art. 24, I, e § 1º, da CF/1988
- Art. 165, § 9º, da CF/1988

### Dicas de prova
- Entenda a competência da União e a reserva de lei complementar federal
- Conheça as normas gerais de direito financeiro e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 24, I, e § 1º, da CF/1988", "Art. 165, § 9º, da CF/1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:17:15.959303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=18", "doc_key": "5cc4e6032193ceaa4554c3e3272eb421"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '3fc2bd3e7a2713a6a734592474107d718fa0886d25148e3cc4694e0b7dcd0aa4'),
  ('cpiuris2025::5065f05c27793d5a3d0dfd6209c02519', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Dever de Execução Orçamentária', '## Dever de Execução Orçamentária

A Emenda Constitucional n.º 102/2019 estabelece regras para a execução orçamentária, destacando que o dever de execução se aplica exclusivamente às despesas primárias discricionárias.

### Conceitos
- **Dever de Execução Orçamentária**: O dever de cumprir as metas fiscais e limites de despesas estabelecidos na Constituição.
- **Despesas Primárias Discricionárias**: Despesas que aumentam a dívida líquida do setor público e não têm relação com a apropriação de juros aos estoques dessa mesma dívida.
- **Obrigatórias e Discricionárias**: As despesas primárias são divididas em obrigatórias (que não há margem de decisão do gestor público) e discricionárias (que têm margem de decisão).

### Referências legais
- Art. 165, § 11 da Constituição

### Jurisprudência
- ADI 6308
- RE 123456

### Dicas de prova
- Entenda a aplicabilidade do dever de execução orçamentária apenas às despesas primárias discricionárias.
- Diferencie entre obrigatórias e discricionárias as despesas primárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 11 da Constituição"], "jurisprudence": ["ADI 6308", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:19:48.276555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=18", "doc_key": "5065f05c27793d5a3d0dfd6209c02519"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '27039f48b413d791a48dce29fa17327f9477fbbb45fd75780088850d9540467c'),
  ('cpiuris2025::8df4d78833ae5b7b444e945ed2ea8cf9', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transferências Especiais e Programação Orçamentária', '## Transferências Especiais e Programação Orçamentária

A transferência especial tem uma liberdade maior de alocar as verbas, sem necessidade de convênio, mas está vinculada à programação estabelecida na emenda parlamentar. Os recursos não integram a receita do Estado e não podem ser aplicados para pagamento de despesas com pessoal ou encargos sociais.

### Conceitos
- **Transferência Especial**: Verba orçamentária destinada a uma finalidade específica
- **Programação Orçamentária**: Planejamento e gestão da aplicação das verbas públicas
- **Vinculação**: Restrição à liberdade de alocar as verbas, devido a uma condição específica
- **Despesas com Pessoal**: Gastos relacionados ao pagamento dos funcionários públicos
- **Encargos Sociais**: Gastos relacionados à manutenção dos benefícios sociais

### Referências legais
- Art. 80 da Constituição Federal
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Transferências Especiais e Programação Orçamentária

### Dicas de prova
- Entenda a diferença entre transferência especial e programação orçamentária
- Conheça as restrições à liberdade de alocar as verbas em transferência especial
- Identifique as áreas que podem receber recursos transferidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 80 da Constituição Federal", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Transferências Especiais e Programação Orçamentária"], "confidence": 0.8, "extracted_at": "2026-05-30T06:20:03.396926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=19", "doc_key": "8df4d78833ae5b7b444e945ed2ea8cf9"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '343a7a10478afaa74a896acbfd93cee5301a8a2f82727bbae3fd04a0ccf43a6e'),
  ('cpiuris2025::1908242356b849a53f32488d1544a0bf', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Discricionárias e Orçamento Público', '## Despesas Discricionárias e Orçamento Público

A EC n.º 102 estabelece que as despesas discricionárias não afastam o dever de sua efetivação, mas reforçam a execução orçamentária cogente. Além disso, a Emenda Constitucional n.º 105/2019 acrescentou o art. 166-A à Constituição, correlacionando a forma de aplicação dos recursos advindos das emendas individuais impositivas.

### Conceitos
- **Despesas Discricionárias**: Gastos que têm margem de conveniência e oportunidade do gestor público
- **Orçamento Público**: Plano financeiro do Estado
- **EC n.º 102**: Emenda Constitucional que estabelece as regras para as despesas discricionárias
- **Transferência Especial**: Repasso direto de recursos ao ente federativo destinatário, sem necessidade de convênio ou instrumento congênere
- **Lei de Diretrizes Orçamentária (LDO)**: Lei que estabelece as diretrizes para o orçamento público

### Referências legais
- Art. 165, § 12 da CF/88
- EC n.º 102
- EC n.º 105/2019
- Art. 166-A da CF

### Dicas de prova
- Entenda a diferença entre despesas discricionárias e obrigatórias
- Conheça as regras para a transferência especial de recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 12 da CF/88", "EC n.º 102", "EC n.º 105/2019", "Art. 166-A da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:20:24.258128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=19", "doc_key": "1908242356b849a53f32488d1544a0bf"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2e1e5f6a68663e95e9413d09b76a206b04559222b10bdfe27e914af728ea18b1'),
  ('cpiuris2025::7982799de4dfe364f00dd30d00f60d5e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Omissão ou erro na indicação de beneficiário', '## Omissão ou erro na indicação de beneficiário

Omissão ou erro na indicação de beneficiário pelo autor da emenda impositiva individual ou de bancada estadual é considerado um ato irregular e pode ser objeto de ação judicial.

### Conceitos
- **Beneficiário**: Pessoa física ou jurídica que recebe o benefício
- **Emenda impositiva individual**: Proposta de emenda apresentada por um autor para alterar a legislação
- **Bancada estadual**: Grupamento de deputados estaduais que trabalham juntos em uma causa comum
- **Cadastro Nacional da Pessoa Jurídica (CNPJ)**: Registro oficial das pessoas jurídicas no Brasil

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas podem pedir para identificar o beneficiário, a natureza da emenda ou a irregularidade no registro do CNPJ.
- A importância de entender a definição de beneficiário e as implicações legais de uma omissão ou erro na indicação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.20 (3)", "page_number": 20, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:22:11.218032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=20", "doc_key": "7982799de4dfe364f00dd30d00f60d5e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b91f4e08fdb7981432a0b44bd34384172d386285d3ba365efe9dcd192dae591a'),
  ('cpiuris2025::178f3b82dc5c6339d69ec22d5b2bac55', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Mecanismos de controle e transparência para execução das emendas parlamentares', '## Mecanismos de controle e transparência para execução das emendas parlamentares

Rege as hipóteses de impedimentos de ordem técnica para execução de emendas parlamentares, estabelecendo critérios para a aprovação ou rejeição das propostas.

### Conceitos
- **Hipótese de impedimento**: Critério que impede a aprovação de uma proposta de emenda parlamentar
- **Objeto da despesa**: Finalidade ou atributos da ação orçamentária e respectivo subtítulo
- **Ausência de projeto de engenharia**: Falta de projeto aprovado pelo órgão setorial responsável pela programação
- **Licença ambiental prévia**: Permissão necessária para realizar um empreendimento
- **Comprovação da capacidade de aportar recursos**: Demonstração que os Estados, Distrito Federal ou Municípios podem financiar o empreendimento

### Referências legais
- Art. 10 da Lei 11

### Dicas de prova
- Entenda a importância dos critérios de impedimento para a execução das emendas parlamentares
- Reconheça as hipóteses de impedimento e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 10 da Lei 11"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:22:31.412583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=20", "doc_key": "178f3b82dc5c6339d69ec22d5b2bac55"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2fcfaf8a5ed3f962dac1a6d3db62265daa82b10447d20bfed15c73bc5654d77f'),
  ('cpiuris2025::cfb1cca9e3ad66e61ed3cdbbb19e963e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Execução de Emendas Parlamentares Impositivas', '## Execução de Emendas Parlamentares Impositivas

A execução de emendas parlamentares impositivas depende da observância dos requisitos estabelecidos na Constituição e nas normas infraconstitucionais, incluindo a existência e apresentação prévia de plano de trabalho, compatibilidade com a lei de diretrizes orçamentárias e com o plano plurianual, entre outros.

### Conceitos
- **Requisitos para execução de emendas parlamentares impositivas**: Existência e apresentação prévia de plano de trabalho, compatibilidade com a lei de diretrizes orçamentárias e com o plano plurianual
- **Transparência e rastreabilidade no gasto público**: Cumprimento de regras que permitam o controle social do gasto público, incluindo a identificação de origem exata da emenda parlamentar e destino das verbas
- **Obediência a dispositivos constitucionais e legais**: Cumprimento de metas fiscais ou limites de despesas estabelecidos na Constituição e nas leis

### Referências legais
- Art. 66 da Lei Complementar nº 210/2024
- Súmula 644 do Supremo Tribunal Federal

### Jurisprudência
- ADI 7697 MC-Ref
- RE 123456

### Dicas de prova
- Entenda a importância da transparência e rastreabilidade no gasto público
- Conheça os requisitos para execução de emendas parlamentares impositivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 66 da Lei Complementar nº 210/2024", "Súmula 644 do Supremo Tribunal Federal"], "jurisprudence": ["ADI 7697 MC-Ref", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:22:42.088742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=20", "doc_key": "cfb1cca9e3ad66e61ed3cdbbb19e963e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6118deb2ab0b2986b38f71bf334d76936f4f315843c0594ebeef6ba2633cf0fb'),
  ('cpiuris2025::ed86a024ea403fdc3a58575dba1f08dc', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Incompatibilidade com o Orçamento Público', '## Incompatibilidade com o Orçamento Público

Listagem de incompatibilidades para a aprovação de emendas orçamentárias, incluindo benefícios do beneficiário, valor das despesas e critérios técnicos.

### Conceitos
- **Benefício do Beneficiário**: Incompatibilidade com o subtítulo da programação orçamentária da emenda
- **Valor das Despesas**: Inobservância da aplicação mínima obrigatória de 70% (setenta por cento) em despesas de capital nas transferências especiais
- **Critérios Técnicos**: Não observância da legislação aplicável ou incompatibilidade das despesas com a política pública setorial

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Perguntas sobre incompatibilidades orçamentárias podem ser muito específicas, então prepare-se para detalhes.
- A legislação de diretrizes orçamentárias é complexa e pode ter várias hipóteses previstas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:24:29.482924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=21", "doc_key": "ed86a024ea403fdc3a58575dba1f08dc"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '83f694884917e9c2d1bb7f0a302d60b04009e16feaf67922bdbb5fbed82c1264'),
  ('cpiuris2025::ceb7f6b8bb5141e770102e57cd1fabb1', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Regime Extraordinário Fiscal', '## Regime Extraordinário Fiscal

A Emenda Constitucional n.º 106/2020 instituiu regime extraordinário fiscal para enfrentar a crise gerada pela pandemia da COVID-19, com características como processos simplificados de contratação, dispensa de limitações legais ao aumento de despesa e renúncia de receitas.

### Conceitos
- **Emenda Constitucional**: Modificação do texto da Constituição
- **Regime Extraordinário Fiscal**: Fiscalidade temporária e simplificada para enfrentar a crise
- **Contratação Temporária**: Contratação de pessoal e obras, serviços e compras em caráter temporário e emergencial
- **Critérios Objetivos**: Destinação de recursos para Estados e Municípios com base em critérios objetivos
- **Dispensa de Limitações Legais**: Aumento de despesa e renúncia de receitas sem limites legais
- **Programação Orçamentária**: Plano específico para a gestão do orçamento público

### Referências legais
- Art. 106 da CF/2020
- Súmula 456 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Regime Extraordinário Fiscal

### Dicas de prova
- Entenda a definição de regime extraordinário fiscal e suas características principais
- Conheça os critérios objetivos para a destinação de recursos para Estados e Municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 106 da CF/2020", "Súmula 456 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Regime Extraordinário Fiscal"], "confidence": 0.8, "extracted_at": "2026-05-30T06:25:00.785557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=21", "doc_key": "ceb7f6b8bb5141e770102e57cd1fabb1"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '341edd878fc1ba4602b85e40036422450b6fd74125bb1122c213a36ee6da43c5'),
  ('cpiuris2025::f462e83284cf522981a64602a9a27126', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Emenda Constitucional nº 109/2021', '## Emenda Constitucional nº 109/2021

Trata-se de norma constitucional autorizativa de novas medidas de enfrentamento à pandemia gerada pela COVID-19, incluindo avaliação e monitoramento de políticas públicas, previsão de indicadores de sustentabilidade da dívida pública e restrições à criação de fundos públicos.

### Conceitos
- **Avaliação e monitoramento de políticas públicas**: Obrigação de a Administração Pública realizar avaliação e monitoramento de políticas públicas
- **Indicadores de sustentabilidade da dívida pública**: Previsão de lei complementar apresente indicadores de sustentabilidade da dívida pública
- **Criação de fundos públicos**: Vedação à criação de fundos públicos, quando seus objetivos puderem ser alcançados mediante a vinculação de receitas orçamentárias específicas ou execução direta por programação orçamentária e financeira
- **Transferência de recursos**: Proibição de transferência a fundos de recursos financeiros oriundos de repasses duodecimais, com retorno dos recursos não utilizados ao Caixa Único do tesouro

### Referências legais
- Art. 37, § 16, CF/88
- Art. 165, § 16, CF/88
- Art. 163, VIII, CF/88
- Art. 164-A, CF/88
- Art. 167, XIV, CF/88
- Art. 168, §§ 1º e 2º, CF/88
- Art. 167-A, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da avaliação e monitoramento de políticas públicas
- Conheça os ''gatilhos'' de contenção de despesas e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 37, § 16, CF/88", "Art. 165, § 16, CF/88", "Art. 163, VIII, CF/88", "Art. 164-A, CF/88", "Art. 167, XIV, CF/88", "Art. 168, §§ 1º e 2º, CF/88", "Art. 167-A, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:25:52.617825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=22", "doc_key": "f462e83284cf522981a64602a9a27126"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '94e0e04d77da84870115cde14e62a2b0bc2ed1172665098db07fa8f677a71514'),
  ('cpiuris2025::1950bbc1f55f8989916de51111ac30a5', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Regime Extraordinário Fiscal e Financeiro', '## Regime Extraordinário Fiscal e Financeiro

Regras para regime extraordinário fiscal e financeiro em caso de estado de calamidade pública de abrangência nacional.

### Conceitos
- **Estado de Calamidade Pública**: Declaração do Congresso Nacional ou do Presidente da República, com iniciativa privativa
- **Regime Extraordinário Fiscal e Financeiro**: Regras especiais para a gestão financeira em caso de calamidade pública
- **PEC do Orçamento de Guerra**: Emenda Constitacional n.º 106/2020, que estabelece processos simplificados de contratação temporária

### Referências legais
- Art. 49, XVIII, CF/88
- Art. 84, XXVIII, CF/88
- Art. 167-B a 167-G, CF/88

### Dicas de prova
- Entenda a diferença entre o regime regular e o regime extraordinário fiscal e financeiro
- Conheça as regras para a contratação temporária em caso de calamidade pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 49, XVIII, CF/88", "Art. 84, XXVIII, CF/88", "Art. 167-B a 167-G, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:26:33.240124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=22", "doc_key": "1950bbc1f55f8989916de51111ac30a5"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '50f03fa9efab5a767bc0c5ab3f80c9994fb423815da25c1ab2cefe93e0ecf58d'),
  ('cpiuris2025::a602f8a4b10685f013cd9cc5e2272dd3', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Dispensa de fontes específicas de recursos em propósitos exclusivos de enfrentar calamidade', '## Dispensa de fontes específicas de recursos em propósitos exclusivos de enfrentar calamidade

A União, Estados e Municípios não precisam especificar fontes de recursos para atos legislativos ou executivos que tenham como objetivo principal enfrentar uma calamidade pública, desde que não envolvam despesas continuadas.

### Conceitos
- **Calamidade Pública**: Situação excepcional que requer intervenção governamental
- **Dispensa de fontes específicas**: Exceção à regra de especificação de recursos para atos legislativos ou executivos
- **Despesa continuada**: Despesa que não é temporária e requer continuidade

### Referências legais
- Art. 167-D, CF/88
- Art. 167-A, CF/88
- Artigos 29-A e 169, caput, CF/88
- Artigo 34, VII, ''e'', da CF/88
- Artigo 35, III, da CF/88

### Jurisprudência
- RE 123456
- EC nº 119/2022

### Dicas de prova
- Entenda a noção de calamidade pública e sua relação com a dispensa de fontes específicas de recursos.
- Identifique as exceções à regra de especificação de recursos para atos legislativos ou executivos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167-D, CF/88", "Art. 167-A, CF/88", "Artigos 29-A e 169, caput, CF/88", "Artigo 34, VII, ''e'', da CF/88", "Artigo 35, III, da CF/88"], "jurisprudence": ["RE 123456", "EC nº 119/2022"], "confidence": 0.8, "extracted_at": "2026-05-30T06:27:33.423237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=23", "doc_key": "a602f8a4b10685f013cd9cc5e2272dd3"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '17113dc68d25ebd7b6569de1b684f30fc05889ad89690fa950a7f9a52aade4cf'),
  ('cpiuris2025::001ea1e378d88d0ee73d887ae1224411', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Investimentos em Educação', '## Investimentos em Educação

A EC nº 119/2023 estabelece regras para investimentos em educação, evitando punições e exigindo complementação de entes subnacionais até 2023.

### Conceitos
- **Investimento em Educação**: Ação realizada por entes subnacionais para desenvolver o ensino.
- **EC nº 119/2023**: Lei que estabelece regras para investimentos em educação.
- **Parágrafo Único do Artigo 119**: Disposto no caput deste artigo, o ente deverá complementar a diferença entre valor aplicado e valor mínimo exigível constitucionalmente.
- **Sistema Integrado de Planejamento e Orçamento**: Sistema utilizado para registrar informações sobre investimentos em educação.
- **Entes Subnacionais**: Estados, Distrito Federal e Municípios que recebem investimentos em educação.

### Referências legais
- Art. 119 da EC nº 119/2023
- Parágrafo Único do Artigo 119

### Dicas de prova
- Entenda a importância dos investimentos em educação e como a EC nº 119/2023 afeta os entes subnacionais.
- Identifique o sistema integrado de planejamento e orçamento mencionado no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 119 da EC nº 119/2023", "Parágrafo Único do Artigo 119"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:28:20.746276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=23", "doc_key": "001ea1e378d88d0ee73d887ae1224411"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f61e9ce72b79ad6dd1e69973314da787e7e52e254a32ebf846342ff191e3db2c'),
  ('cpiuris2025::0f74d0f7e1b7f07b6d41cfa24599b7c8', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Disposições Constitucionais Transitórias e Orçamento Público', '## Disposições Constitucionais Transitórias e Orçamento Público

A EC nº 119/2020 mitigou a regra de impositividade das despesas relacionadas à manutenção e ao desenvolvimento do ensino, restabelecendo a obrigatoriedade da norma a partir de 2021.

### Conceitos
- **Disposições Constitucionais Transitórias**: Normas constitucionais que regulam o processo de elaboração e execução do orçamento público.
- **Orçamento Público**: O conjunto das receitas e despesas da União, dos Estados e dos Municípios, dentro de um período determinado.
- **Disponibilidade de Caixa**: A capacidade do Estado ou ente público de realizar pagamentos de suas obrigações.

### Referências legais
- Art. 119 da Ato das Disposições Constitucionais Transitórias
- EC nº 119/2020

### Dicas de prova
- Entenda a natureza do orçamento público e as disposições constitucionais que o regem.
- Conheça a noção de disponibilidade de caixa e sua importância para o pagamento de obrigações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 119 da Ato das Disposições Constitucionais Transitórias", "EC nº 119/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:28:51.859185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=24", "doc_key": "0f74d0f7e1b7f07b6d41cfa24599b7c8"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '01471fee9d7f4a6089bfa6258aa26721fa3cff48e113fdf6618e53145f91491a'),
  ('cpiuris2025::a448f7271ba97195f6556d87a403e3f2', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Princípios Orçamentários', '## Princípios Orçamentários

Resumo dos principais princípios orçamentários: equilíbrio, unidade de tesouraria e anualidade.

### Conceitos
- **Equilíbrio orçamentário**: Despesas e receitas projetadas devem se manter em níveis compatíveis
- **Unidade de tesouraria**: Todas as receitas sejam recolhidas a conta única, vedada a criação de caixas especiais
- **Anualidade**: Dotações orçamentárias do exercício seguinte sejam fixadas conforme exercício anterior
- **Orçamento especial**: Exceção ao princípio de universalidade, aplicado à previdência social
- **Vinculação de receita**: Permitida para despesas com educação

### Referências legais
- Art. 77 da Lei Orçamentária
- ...

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Perguntas sobre equilíbrio orçamentário podem ser resolvidas com base na receita e despesa.
- Unidade de tesouraria é fundamental para evitar a criação de caixas especiais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 77 da Lei Orçamentária", "..."], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T06:29:55.002108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=24", "doc_key": "a448f7271ba97195f6556d87a403e3f2"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e56253e50ce32bb81b13623ead0197eb78e5fc53b5b8267aa66ec9dd228573a4'),
  ('cpiuris2025::a82a22fb2d9398e8cd2704d9ef836c3f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Disponibilidade de caixa e depósito em instituição financeira privada', '## Disponibilidade de caixa e depósito em instituição financeira privada

A questão discute a disponibilidade de caixa e o depósito de salário ou remuneração de servidor público em instituição financeira privada, com base no artigo 164, § 3º, da Constituição Federal.

### Conceitos
- **Disponibilidade de caixa**: Conceito jurídico que se refere à capacidade do Estado de pagar suas obrigações
- **Depósito em instituição financeira privada**: Ação de colocar recursos em uma instituição financeira privada, sem afrontar o artigo 164, § 3º, da Constituição Federal

### Referências legais
- Art. 164, § 3º, da Constituição Federal

### Dicas de prova
- Entenda a noção de disponibilidade de caixa e como ela se relaciona com o depósito em instituição financeira privada
- Leia atentamente o artigo 164, § 3º, da Constituição Federal para evitar erros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.25", "page_number": 25, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 164, § 3º, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:30:14.248185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=25", "doc_key": "a82a22fb2d9398e8cd2704d9ef836c3f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f9d21f5d3c48d0473ac7f9494181dc86977ca1abe2919991972f8c2ccaa77ea9'),
  ('cpiuris2025::11195d1bde3427214dd4987fd9221907', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Princípios e Leis Orçamentárias', '## Princípios e Leis Orçamentárias

O princípio da legalidade é fundamental no Direito Financeiro, exigindo que as finanças públicas sejam geridas por autorização legal. A lei orçamentária anual deve ser a base para a gestão das finanças públicas.

### Conceitos
- **Princípio da Legalidade**: Exige que as finanças públicas sejam geridas por autorização legal
- **Lei Orçamentária Anual**: Base para a gestão das finanças públicas
- **Paralelismo das Normas**: A alteração do orçamento geralmente deve observar o mesmo instrumento normativo
- **Desrespeito ao Princípio da Legalidade**: Causa reflexos, inclusive penais

### Referências legais
- Art. 37 da Constituição Federal
- Art. 167 da Constituição Federal
- Art. 359-D do Código Penal

### Dicas de prova
- Entenda o princípio da legalidade e sua aplicação no Direito Financeiro
- Conheça as exceções ao princípio da legalidade, como a transposição de recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.27", "page_number": 27, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 37 da Constituição Federal", "Art. 167 da Constituição Federal", "Art. 359-D do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:30:28.478179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=27", "doc_key": "11195d1bde3427214dd4987fd9221907"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6a79e9eeb07e443ce97a1ffa5524deb81eb3c1ca8a836ff4d4962734832290aa'),
  ('cpiuris2025::4be0431e0703ef1c4d531839973180f7', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Princípios e Leis Orçamentárias', '## Princípios e Leis Orçamentárias

O texto discute os princípios da exclusividade, programação, equilíbrio orçamentário e anualidade no contexto das leis orçamentárias brasileiras.

### Conceitos
- **Exclusividade**: Princípio que determina a especificidade do orçamento público
- **Programação**: Princípio que relaciona os objetivos e metas do plano de governo com as missões constitucionais
- **Equilíbrio Orçamentário**: Princípio que indica a relação entre despesas e receitas no orçamento público
- **Anualidade**: Tempo de vigência do exercício financeiro, coincidindo com o exercício civil

### Referências legais
- Art. 165, § 8º da CF/88
- Art. 165, § 4º da CF/88
- Art. 34 da Lei n.º 4.320/1964

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a exclusividade como um princípio que evita orçamentos rabilongos
- Conheça o programa de governo e suas missões constitucionais
- Avalie o equilíbrio orçamentário em relação às despesas e receitas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.28", "page_number": 28, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 8º da CF/88", "Art. 165, § 4º da CF/88", "Art. 34 da Lei n.º 4.320/1964"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:33:08.903999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=28", "doc_key": "4be0431e0703ef1c4d531839973180f7"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'de0c2a014ce67194bed578d706d000dde89843d7bf1e44c7558d8d7a2b911271'),
  ('cpiuris2025::184bd3365c736ff119336e843274fa53', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Princípios e Leis Orçamentárias', '## Princípios e Leis Orçamentárias

O princípio da unidade exige que cada ente federativo tenha um orçamento contendo receita e despesa para evidenciar a política econômico-financeira do governo. A Constituição Federal estabelece três orçamentos: fiscal, investimento e seguridade social.

### Conceitos
- **Princípio da unidade**: Exige que cada ente federativo tenha um orçamento contendo receita e despesa para evidenciar a política econômico-financeira do governo.
- **Universalidade**: Todas as receitas e despesas referentes aos Poderes, seus fundos, órgãos e entidades da Administração Direta e Indireta devem estar contidas no orçamento.
- **Orçamento Bruto**: Todas as receitas e despesas constarão na lei orçamentária pelos seus valores totais (brutos), vedadas quaisquer deduções.

### Referências legais
- Art. 165 da CF/88
- Art. 2º da Lei n.º 4.320/1964

### Dicas de prova
- Entenda o princípio da unidade e sua aplicação prática nos orçamentos dos entes federativos.
- Conheça as três partes do orçamento: fiscal, investimento e seguridade social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.29", "page_number": 29, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165 da CF/88", "Art. 2º da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:33:22.016871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=29", "doc_key": "184bd3365c736ff119336e843274fa53"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '350a2b503f0890ba6c5fe0aecaca4e8163ba4671a133a48eb16c9afd4571ae97'),
  ('cpiuris2025::b141bd062eb9c6ff7e10cf9d04552f5d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transparência orçamentária', '## Transparência orçamentária

O princípio da transparência orçamentária é um mandamento nuclear que regula a Administração Pública, sendo um dever específico do Poder Executivo. Isso inclui a divulgação de informações financeiras e contábeis, como relatórios resumidos de execução orçamentária e divulgação de contas municipais.

### Conceitos
- **Transparência orçamentária**: Dever específico do Poder Executivo de divulgar informações financeiras e contábeis
- **Relatório Resumido de Execução Orçamentária (RREO)**: Instrumento que o Poder Executivo publica até 30 dias após o encerramento de cada bimestre
- **Divulgação de contas municipais**: Dever do Poder Executivo de divulgar as contas dos municípios durante 60 dias anualmente
- **Emenda Constitucional n.º 108/2020**: Rege a divulgação das informações e dados contábeis, orçamentários e fiscais da União e seus entes federados
- **Relatório de Gestão Fiscal (RGF)**: Instrumento que os titulares dos Poderes e órgãos emitem ao final de cada quadrimestre
- **Lei de Acesso à Informação**: Rege a divulgação de informações públicas, incluindo financeiras e contábeis
- **Teoria da sujeição especial**: Teoria que legitima restrições maiores a direitos fundamentais, incluindo a intimidade, para os agentes públicos

### Referências legais
- Art. 37 da CF/88
- Art. 165, § 3º, CF/88
- Art. 31, § 3º, CF/88
- Art. 163-A, CF/88
- Art. 20 da LRF
- Lei n.º 12.527/11

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da transparência orçamentária e como ela é regulada pela Constituição.
- Conheça os instrumentos que o Poder Executivo deve divulgar para cumprir com esse princípio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 37 da CF/88", "Art. 165, § 3º, CF/88", "Art. 31, § 3º, CF/88", "Art. 163-A, CF/88", "Art. 20 da LRF", "Lei n.º 12.527/11"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T06:34:38.771832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=30", "doc_key": "b141bd062eb9c6ff7e10cf9d04552f5d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '326c19b73f2dc5713af660140e1fc0ba74e49e12888a5441435bbfea41e76b59'),
  ('cpiuris2025::44ebde2d6c4b1c6bbfeb968795d9ca76', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Exigência de especificidade nas dotações orçamentárias', '## Exigência de especificidade nas dotações orçamentárias

As dotações orçamentárias devem ser específicas e precisas, pois não podem ser genéricas ou globais. Isso se deve ao artigo 5º, § 4º da Lei Complementar n.º 101/2000.

### Conceitos
- **Dotação orçamentária**: parte do orçamento que é alocada para um determinado objetivo ou atividade
- **Exigência de especificidade**: obrigação de ser clara e precisa, sem ambiguidades
- **Genéricas**: dotações orçamentárias que são muito amplas e não específicas
- **Globais**: dotações orçamentárias que são aplicáveis a todos os casos ou situações

### Referências legais
- Art. 5º, § 4º da Lei Complementar n.º 101/2000

### Dicas de prova
- Entenda o conceito de dotação orçamentária e a importância da especificidade.
- Reconheça as exceções à regra geral, como a reserva de contingência e os programas especiais de trabalho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 5º, § 4º da Lei Complementar n.º 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:35:22.256064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=30", "doc_key": "44ebde2d6c4b1c6bbfeb968795d9ca76"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '85ac917987cf7b08b842ce9972afba52051d1ce8599aca01d76a86298f9146f9'),
  ('cpiuris2025::dce80c8e8a5727a24058da116db0998e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Unidade de Caixa (Tesouraria)', '## Unidade de Caixa (Tesouraria)

O princípio de unidade de tesouraria impõe que todas as receitas sejam dispostas em uma única conta para facilitar a administração e fiscalizar o equilíbrio das contas.

### Conceitos
- **Unidade de Caixa**: Princípio que impõe a unificação das receitas em uma única conta
- **Tesouraria**: Recurso carregado ao erário para atender às necessidades do governo
- **Disponibilidade de Caixa**: Valor disponível no erário para atender às necessidades do governo

### Referências legais
- Art. 56 da Lei n.º 4.320/1964
- Art. 164, § 3º, da CF/88

### Jurisprudência
- AI 837.677 AgR/MA

### Dicas de prova
- Entenda o conceito de unidade de caixa e sua importância na administração pública
- Conheça a exceção prevista no art. 43, § 1º, da Lei de Responsabilidade Fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 56 da Lei n.º 4.320/1964", "Art. 164, § 3º, da CF/88"], "jurisprudence": ["AI 837.677 AgR/MA"], "confidence": 0.8, "extracted_at": "2026-05-30T06:35:36.695057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=31", "doc_key": "dce80c8e8a5727a24058da116db0998e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a9eff1cf1044139424e1847efd07af3882cea37fa3bc50a5d84c9af055ddba85'),
  ('cpiuris2025::4b93f6de50f18c90953b4c7d4324b476', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita de Impostos e Vinculação', '## Receita de Impostos e Vinculação

A receita de impostos não pode ser vinculada a órgão, fundo ou despesa, exceto para destinação específica.

### Conceitos
- **Vinculação de Receita**: Receita de impostos não pode ser vinculada a órgão, fundo ou despesa
- **Destinação de Recursos**: Recursos podem ser destinados para atividades específicas

### Referências legais
- Art. 167, IV da Constituição Brasileira

### Dicas de prova
- Entenda a noção de vinculação de receita e destinação de recursos
- Conheça o artigo 167, IV da Constituição Brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167, IV da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:36:19.137008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=31", "doc_key": "4b93f6de50f18c90953b4c7d4324b476"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f9e08141da18266f9bd289798ee42863302eaf54cc29478aa3d2e50a8775615e'),
  ('cpiuris2025::5bba1f7b164dbdd59e9314e02f497203', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Créditos Orçamentários', '## Créditos Orçamentários

Descreve os diferentes tipos de créditos orçamentários, suas finalidades e requisitos para abertura.

### Conceitos
- **Crédito Suplementar**: Reforço de dotação já existente na lei orçamentária.
- **Crédito Especial**: Despesa para a qual não haja dotação orçamentária e necessita de autorização legislativa.
- **Crédito Extraordinário**: Despesa imprevisível e urgente, que pode ser aberto sem autorização legislativa mediante Medida Provisória.

### Referências legais
- Art. 43, § 1º, da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a diferença entre crédito suplementar e especial.
- Conheça as fontes para abertura de créditos adicionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.33", "page_number": 33, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 43, § 1º, da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:37:32.581627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=33", "doc_key": "5bba1f7b164dbdd59e9314e02f497203"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd0314f3b060bf6bb9d0cb9e46266e2125467f41f73ebf9e050fa9ed4c422d46e'),
  ('cpiuris2025::50bebb38170afdf55eed4ad5bbf5ff6a', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Princípios e Leis Orçamentárias', '## Princípios e Leis Orçamentárias

Descreve os princípios e leis que regem o orçamento público, incluindo a não vinculação de impostos a uma finalidade específica e a necessidade de autorização legislativa para transposição, remanejamento ou transferência de recursos.

### Conceitos
- **Princípio da não vinculação de impostos**: Impostos não podem ser vinculados a uma finalidade específica
- **Transposição, remanejamento ou transferência de recursos (TRT)**: Gestor público não pode manejar o orçamento por meio de TRT sem prévia autorização legislativa
- **Créditos adicionais**: Surgem a partir de ajustes orçamentários para adaptar previsões insuficientes ou não realizadas
- **Suplementares, especiais e extraordinários**: Tipos de créditos adicionais com diferentes características

### Referências legais
- Art. 198, § 2º, CF/88
- Art. 212, CF/88
- Art. 37, XXII, CF/88
- Art. 165, § 8º, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a não vinculação de impostos e a necessidade de autorização legislativa para TRT
- Conheça os tipos de créditos adicionais e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.32", "page_number": 32, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 198, § 2º, CF/88", "Art. 212, CF/88", "Art. 37, XXII, CF/88", "Art. 165, § 8º, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:38:17.571054+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=32", "doc_key": "50bebb38170afdf55eed4ad5bbf5ff6a"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0544ad752680b6520ddbeca6911d34b89fe5f0dcb1310788a30149673d42c9d1'),
  ('cpiuris2025::2b5a882df573761f67fa3a681df53489', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Ciclo Orçamentário e Iniciativa', '## Ciclo Orçamentário e Iniciativa

O ciclo orçamentário é mais amplo que o exercício financeiro e começa antes do início do exercício, estendendo-se após seu término. A iniciativa de leis orçamentárias é exclusiva e indelegável do Poder Executivo.

### Conceitos
- **Ciclo Orçamentário**: Período que abrange mais do que um exercício financeiro
- **Iniciativa Exclusiva e Indelegável**: Direito do Poder Executivo de elaborar leis orçamentárias sem necessidade de iniciativa legislativa
- **Princípio da Anualidade**: Exercício financeiro coincide com o ano civil

### Referências legais
- Art. 84, XXIII, c/c o art. 61, § 1º, II, ''b''
- Art. 85, VI
- CF/88

### Dicas de prova
- Entenda a diferença entre ciclo orçamentário e exercício financeiro
- Conheça o princípio da exclusividade e indelegável da iniciativa do Poder Executivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 84, XXIII, c/c o art. 61, § 1º, II, ''b''", "Art. 85, VI", "CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:38:37.714622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=34", "doc_key": "2b5a882df573761f67fa3a681df53489"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'bf344a6ba7e69aa3547ab9657904599e9b311072783215d6ad43b8477520e25c'),
  ('cpiuris2025::83d658540b69a6f76801c43fc9b23b6e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Restrições às emendas no projeto de lei orçamentário', '## Restrições às emendas no projeto de lei orçamentário

As emendas devem ser compatíveis com o PPA e a LDO, não podem aumentar despesa e devem indicar recursos que virão de anulação de despesas.

### Conceitos
- **PPA**: Plano Plurianual
- **LDO**: Lei de Diretrizes Orçamentárias

### Referências legais
- Art. 59 da Lei Orçamentária
- ...

### Jurisprudência
- RE 590.697-ED

### Dicas de prova
- Perguntas sobre compatibilidade com PPA e LDO
- Distinção entre aumento de despesa e anulação de despesas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 59 da Lei Orçamentária", "..."], "jurisprudence": ["RE 590.697-ED"], "confidence": 0.8, "extracted_at": "2026-05-30T06:39:09.280791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=34", "doc_key": "83d658540b69a6f76801c43fc9b23b6e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '7580adb8acf809b43702a7a2a6cbca95df11b33ef8f129da39bab17c51bb5643'),
  ('cpiuris2025::a11be3b52195c75af73d0111f5f2756f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento e Execução Orçamentária', '## Orçamento e Execução Orçamentária

Descreve as regras de emenda ao projeto de lei orçamentária, execução do orçamento e limitação de empenho.

### Conceitos
- **Compatibilidade**: A compatibilidade com o PPA e a LDO é necessária para emendas ao projeto de lei orçamentária.
- **Restrições formais**: As emendas devem ser relacionadas com correções de erros ou omissões, ou com os dispositivos do texto do projeto de lei.
- **Limitação de empenho**: A limitação de empenho é aplicada se a receita não corresponder ao que foi previsto inicialmente, para evitar superaventura.
- **Serviço da dívida**: As despesas relacionadas ao serviço da dívida são excluídas da limitação de empenho.
- **Lei de diretrizes orçamentárias**: A lei estabelece os critérios para a limitação de empenho e movimentação financeira.

### Referências legais
- Art. 166 da CF/88
- Art. 8º da LRF
- Art. 9º da LRF

### Dicas de prova
- Pergunte sobre a compatibilidade com o PPA e a LDO.
- Entenda as restrições formais para emendas ao projeto de lei orçamentária.
- Conheça a limitação de empenho e seus critérios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.35", "page_number": 35, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 166 da CF/88", "Art. 8º da LRF", "Art. 9º da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:41:07.311567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=35", "doc_key": "a11be3b52195c75af73d0111f5f2756f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '28992bbbb26930a584ff99286050097b07cb455cea96c7669374f2438c8ea47d'),
  ('cpiuris2025::73d523f5b2a7bee15b101555d1d31501', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Lei de Diretrizes Orçamentárias (LDO)', '## Lei de Diretrizes Orçamentárias (LDO)

A LDO é um documento que estabelece metas e prioridades da administração pública federal, orienta a elaboração da lei orçamentária anual e dispõe sobre alterações na legislação tributária.

### Conceitos
- **Lei de Diretrizes Orçamentárias (LDO)**: Documento que estabelece metas e prioridades da administração pública federal
- **Política Fiscal**: Diretiva que orienta a gestão financeira do governo
- **Lei Orçamentária Anual**: Documento que detalha as receitas e despesas do governo em um ano
- **Poder Executivo**: Unidade de governo responsável pela execução das leis
- **Poder Legislativo**: Unidade de governo responsável pela elaboração das leis

### Referências legais
- Art. 165, § 2º, CF/88

### Dicas de prova
- Entenda a função da LDO em relação à lei orçamentária anual e ao PPA
- Conheça as metas e prioridades da administração pública federal estabelecidas pela LDO', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 2º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:41:22.748426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=37", "doc_key": "73d523f5b2a7bee15b101555d1d31501"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd25f874c0f51e24b2688bbb2c7ea13648a66469680794eedc4dd3976ba5d1c67'),
  ('cpiuris2025::982ab817bb3403250cc3af8f542f8cfb', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle e Lei Orçamentária', '## Controle e Lei Orçamentária

O controle da aplicação dos recursos públicos é feito por órgãos de controle, como o Tribunal de Contas, e pode ser realizado pela controladoria interna, pelo Poder Legislativo e até mesmo pela sociedade. A Constituição estabeleceu três leis orçamentárias: Plano Plurianual (PPA), Lei de Diretrizes Orçamentárias (LDO) e Lei Orçamentária Anual (LO).

### Conceitos
- **Controle**: Fiscalização e apreciação da correta aplicação dos recursos públicos
- **Lei Orçamentária**: Norma que regula a execução do orçamento público
- **Plano Plurianual (PPA)**: Documento que estabelece diretrizes, objetivos e metas da administração pública federal para despesas de capital e outras delas decorrentes
- **Lei de Diretrizes Orçamentárias (LDO)**: Elo entre o planejamento (PPA) e o operacional (LOA)
- **Tribunal de Contas**: Órgão responsável pela fiscalização e controle da aplicação dos recursos públicos
- **Poder Legislativo**: Órgão responsável pelo controle externo da aplicação dos recursos públicos

### Referências legais
- Art. 165, § 1º, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do controle na aplicação dos recursos públicos
- Conheça as três leis orçamentárias e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.36", "page_number": 36, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 1º, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:41:43.503063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=36", "doc_key": "982ab817bb3403250cc3af8f542f8cfb"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'bb21c53b89e70464cff6eacb1775f05cce0fd45319ecc1914ed4a0422a58f1d4'),
  ('cpiuris2025::d4744fce829f65c56181706881a43f88', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Vigência da Lei de Diretrizes Orçamentárias (LDO)', '## Vigência da Lei de Diretrizes Orçamentárias (LDO)

A LDO tem vigência acima de um ano e entra em vigor após 17 de julho de um determinado exercício, permanecendo até 31 de dezembro do exercício subsequente.

### Conceitos
- **Vigência da LDO**: Período durante o qual a LDO é aplicada
- **Entrada em vigor da LDO**: Data após a qual a LDO entra em vigor
- **Prazo de vigência da LDO**: Período durante o qual a LDO permanece vigente

### Referências legais
- Art. 4º da Lei Complementar n.º 101/2000
- LRF

### Dicas de prova
- Entenda a diferença entre entrada em vigor e prazo de vigência
- Leia o artigo 4º da LCP n.º 101/2000 cuidadosamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 4º da Lei Complementar n.º 101/2000", "LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:43:03.144295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=37", "doc_key": "d4744fce829f65c56181706881a43f88"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6a5cff49ee91cf51bc5fcceb583bbadc17a1960a0f8b1c59c7ff2cc5f2b76f9f'),
  ('cpiuris2025::fe1b1cce7ddc294652e8d263f36aded2', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Lei Orçamentária Anual (LOA)', '## Lei Orçamentária Anual (LOA)

Descreve a LOA como lei que trata da execução de projetos previstos em diretrizes, objetivos e metas contidas no PPA e LDO, sendo a mais concreta das três leis.

### Conceitos
- **Lei Orçamentária Anual (LOA)**: lei que trata da execução de projetos previstos em diretrizes, objetivos e metas
- **PPA**: Plano Plurianual
- **LDO**: Lei de Diretrizes Orçamentárias

### Referências legais
- Art. 80 da Constituição Federal
- LC nº 101/2000

### Dicas de prova
- Entenda a diferença entre PPA, LDO e LOA.
- Conheça o prazo de vigência da LOA.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 80 da Constituição Federal", "LC nº 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:43:14.846101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=38", "doc_key": "fe1b1cce7ddc294652e8d263f36aded2"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c166ffafa921f8856f2bf6c1fbeb032b2aeece2f4d12ad67d48b1b93c3b90b41'),
  ('cpiuris2025::ca82ddabd3df751e65c5b07a2c722a5e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Lei Orçamentária e Anexos Fiscais', '## Lei Orçamentária e Anexos Fiscais

O texto discute os anexos fiscais do Orçamento, como o Anexo de Metas Fiscais e o Anexo de Riscos Fiscais, e suas obrigações e exceções.

### Conceitos
- **Anexo de Metas Fiscais**: anexo que estabelece metas anuais para receitas, despesas, resultados nominal e primário e montante da dívida pública
- **Anexo de Riscos Fiscais**: anexo que avalia os passivos contingentes e outros riscos capazes de afetar as contas públicas
- **Lei Complementar n.º 101**: leis orçamentárias que estabelecem regras para o Orçamento da União, dos Estados e do Distrito Federal
- **LDO**: Lei de Diretrizes Orçamentárias

### Referências legais
- Art. 9º da Lei Complementar n.º 101
- Art. 65-A da Lei Complementar n.º 101
- Art. 63, III da Lei Complementar n.º 101/00

### Dicas de prova
- Entenda a importância dos anexos fiscais do Orçamento e suas obrigações.
- Conheça as exceções para a elaboração de anexos fiscais, como os municípios com menos de 50.000 habitantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 9º da Lei Complementar n.º 101", "Art. 65-A da Lei Complementar n.º 101", "Art. 63, III da Lei Complementar n.º 101/00"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:43:29.602619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=38", "doc_key": "ca82ddabd3df751e65c5b07a2c722a5e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e5612b1cac4ba79acbc0ec65cac8ffe3120824ac0d1fc0b3eebaf8e81e225fd6'),
  ('cpiuris2025::858963deb82e08967d577b47a0ad448d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Abuso de poder tributário', '## Abuso de poder tributário

Listagem de atividades ilegais da administração tributária, incluindo abertura de crédito sem autorização legislativa e instituição de fundos sem prévia autorização.

### Conceitos
- **Abuso de poder tributário**: Uso indevido do poder tributário por parte da administração tributária
- **Crédito suplementar ou especial**: Crédito concedido sem prévia autorização legislativa
- **Instituição de fundos**: Criação de fundos financeiros sem prévia autorização legislativa

### Referências legais
- Art. 165, § 8º; Art. 198, § 2º; Art. 212; Art. 37, XXII

### Dicas de prova
- Identifique as atividades ilegais da administração tributária
- Entenda a importância da autorização legislativa para a instituição de fundos e créditos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 8º; Art. 198, § 2º; Art. 212; Art. 37, XXII"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:45:28.555901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=39", "doc_key": "858963deb82e08967d577b47a0ad448d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '496932c5cb470d1f1098455d6a872e1e75ae951828668d4e8fb296678709df1f'),
  ('cpiuris2025::08df3f3e1875577a728bd6872c355f07', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Lei Orçamentária', '## Lei Orçamentária

O projeto de lei orçamentária anual deve conter demonstrativo da compatibilidade da programação dos orçamentos com os objetivos e metas constantes do plano plurianual, além de reserva de contingência para atendimento de passivos contingentes e outros riscos.

### Conceitos
- **Lei Orçamentária**: Lei que estabelece os princípios e regras para a elaboração do orçamento público
- **Reserva de Contingência**: Montante destinado a atender a passivos contingentes e outros riscos imprevistos
- **Compatibilidade da Programação**: Demonstrativo que mostra a compatibilidade da programação dos orçamentos com os objetivos e metas do plano plurianual

### Referências legais
- Art. 5º da Lei Complementar nº 70/1991
- Art. 165, § 6º da Constituição

### Dicas de prova
- Perguntas sobre a compatibilidade da programação dos orçamentos com os objetivos e metas do plano plurianual
- Reserva de contingência: qual é o seu objetivo?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 5º da Lei Complementar nº 70/1991", "Art. 165, § 6º da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:45:51.842148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=39", "doc_key": "08df3f3e1875577a728bd6872c355f07"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '8e424b50d6b545b7dfa2a69f96a1fe1dff110723e11930a4b09bced13966178d'),
  ('cpiuris2025::02bdf8745905fa9e6d2f41591e48d9ac', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Regra de Ouro e Classificação de Despesas e Receitas', '## Regra de Ouro e Classificação de Despesas e Receitas

O inciso III do art. 167 da CF/88 define a regra de ouro, que estabelece que receita corrente financia despesa corrente e receitas de capital financiam despesas de capital, ressalvados os créditos adicionais.

### Conceitos
- **Regra de Ouro**: Princípio que estabelece a relação entre receita corrente e despesa corrente
- **Despesas Correntes**: Despesas necessárias ao funcionamento do governo, financiadas por receita corrente
- **Receitas de Capital**: Receitas que financiam investimentos e projetos a longo prazo
- **Orçamento Clássico**: Tipos de orçamento que mantêm características do orçamento tradicional
- **Orçamento de Base Zero**: Técnica orçamentária que busca reduzir despesas e aumentar receitas

### Referências legais
- Art. 167 da CF/88

### Dicas de prova
- Entenda a diferença entre despesa corrente e despesa de capital
- Conheça as características do orçamento clássico e do orçamento de base zero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:46:12.006800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=40", "doc_key": "02bdf8745905fa9e6d2f41591e48d9ac"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '80b1a1a875dfcd2d52922ab5507fbb1ce8328e95594e5819b46e4f717aba2e3f'),
  ('cpiuris2025::edcc202e3414da63b9d936dc78efccd2', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento-Programa', '## Orçamento-Programa

O orçamento-programa é uma técnica que vincula os recursos financeiros com as metas governamentais.

### Conceitos
- **Orçamento-Programa**: Técnica que vincula os recursos financeiros com as metas governamentais
- **Plano Plurianual**: Documento que estabelece diretrizes, objetivos e metas da administração pública federal

### Referências legais
- Art. 4.320/64
- Constituição da República de 1946
- Constituição da República de 1988

### Dicas de prova
- Entenda a diferença entre Orçamento-Programa e Plano Plurianual
- Reconheça as modalidades distintas de leis orçamentárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 4.320/64", "Constituição da República de 1946", "Constituição da República de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:47:20.777989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=40", "doc_key": "edcc202e3414da63b9d936dc78efccd2"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '31b942be08feda7c61a11933c2e2ba32b0e6c5a1f93f9edb952d7e7ccdbdf989'),
  ('cpiuris2025::7e83eeeab355a74e75818750d6b7898c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita Pública', '## Receita Pública

Receita pública é toda entrada de numerário nos cofres públicos para custear despesas públicas. Diferenciação entre receita pública e ingresso público.

### Conceitos
- **Receita Pública**: entrada de numerário nos cofres públicos para custear despesas públicas
- **Ingresso Público**: entrada provisória de recursos, marcada pela possibilidade de devolução ao particular
- **Patrimônio Público**: conjunto dos bens e direitos do Estado
- **Despesa Pública**: gastos realizados pelo Estado para atender a necessidades públicas

### Referências legais
- Art. 167, § 3º, CF/88
- Art. 148, CF/88

### Dicas de prova
- Diferenciar entre receita pública e ingresso público
- Entender a classificação das receitas públicas (ordinária e extraordinária)
- Conhecer o conceito de patrimônio público e despesa pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.44", "page_number": 44, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167, § 3º, CF/88", "Art. 148, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:49:21.583044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=44", "doc_key": "7e83eeeab355a74e75818750d6b7898c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0180b560fcad5e70e639757b012ba5d79bfdd026ffa058157af723af000080e4'),
  ('cpiuris2025::458bd5403087a524b7497ede9264bdd7', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Orçamento Orçamentário Unidade', '## Orçamento Orçamentário Unidade

A lei orçamentária anual é um documento único e formalizado pela União, que integra a previsão de receita e a fixação da despesa de todos os entes federados em cada exercício financeiro.

### Conceitos
- **Orçamento Orçamentário Unidade**: A unidade do orçamento, que significa que a previsão de receita e a fixação da despesa de todos os entes federados integram um único documento legalmente formalizado.
- **Lei Orçamentária Anual**: O documento único e formalizado pela União que integra a previsão de receita e a fixação da despesa de todos os entes federados em cada exercício financeiro.
- **Unidade de Caixa**: A unidade de caixa é o princípio orçamentário que exige que todas as receitas e despesas sejam registradas em uma única conta.
- **Equilíbrio Orçamentário**: O equilíbrio orçamentário é o princípio orçamentário que exige que a soma das receitas seja igual à soma das despesas.
- **Exclusividade**: A exclusividade é um princípio orçamentário que exige que as receitas e despesas sejam utilizadas apenas para fins públicos.
- **Anualidade**: A anualidade é um princípio orçamentário que exige que o orçamento seja apresentado e aprovado anualmente.
- **Universalidade**: A universalidade é um princípio orçamentário que exige que o orçamento aborde todas as áreas de atuação do Estado.
- **Programa**: Um programa é um conjunto de ações com vistas à concretização de objetivos e metas.

### Referências legais
- Art. 3º da Constituição Federal de 1988

### Jurisprudência
- Súmula 646/2012 do Supremo Tribunal Federal

### Dicas de prova
- Entenda a unidade do orçamento e como ela se relaciona com a lei orçamentária anual.
- Conheça os princípios orçamentários e como eles são aplicados na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.41", "page_number": 41, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 3º da Constituição Federal de 1988"], "jurisprudence": ["Súmula 646/2012 do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-30T06:49:51.755080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=41", "doc_key": "458bd5403087a524b7497ede9264bdd7"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ab4b0abfa94b71376035175d662b4c5f3cba396e7ee9721329894ac3ef08b340'),
  ('cpiuris2025::aa9b8ffd13cd1d2add8e3dcaba815050', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Princípios Orçamentários', '## Princípios Orçamentários

Os princípios orçamentários são: unidade estabelecida pela existência de um orçamento único para cada ente da federação; exclusividade, que não permite dispositivos estranhos à previsão da receita e fixação das despesas; anualidade, com exceções como restos a pagar e créditos especiais; equilíbrio, com exceções como déficits e superávits justificados; Orçamento Bruto e Unidade orçamentária.

### Conceitos
- **Unidade Estabelecida**: Existência de um orçamento único para cada ente da federação
- **Exclusividade**: Não permitir dispositivos estranhos à previsão da receita e fixação das despesas
- **Anualidade**: Comporta exceções, como restos a pagar e créditos especiais
- **Equilíbrio**: Comporta exceções, como déficits e superávits justificados
- **Orçamento Bruto**: Lei nº 4.320/1964, que estabelece a existência de um orçamento único para cada ente da federação
- **Unidade Orçamentária**: Deve existir apenas um orçamento para cada ente da federação em cada exercício financeiro

### Referências legais
- Art. 165, § 2º, CF/88 (com redação alterada pela EC 109/2021)
- Art. 165, § 5º, CF/88
- Art. 166, § 9º, CF/88
- Lei nº 4.320/1964

### Jurisprudência
- RE 123456
- Tema repetitivo da LOA

### Dicas de prova
- Entenda a unidade estabelecida e exclusividade orçamentária
- Conheça as exceções para anualidade, equilíbrio e Orçamento Bruto
- Pergunte sobre a Unidade Orçamentária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.42", "page_number": 42, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 2º, CF/88 (com redação alterada pela EC 109/2021)", "Art. 165, § 5º, CF/88", "Art. 166, § 9º, CF/88", "Lei nº 4.320/1964"], "jurisprudence": ["RE 123456", "Tema repetitivo da LOA"], "confidence": 0.8, "extracted_at": "2026-05-30T06:50:04.356896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=42", "doc_key": "aa9b8ffd13cd1d2add8e3dcaba815050"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '776ec2abd0f57d4fa3ba181989ea92ee97216be0c4fbf31af728f357b1efb562'),
  ('cpiuris2025::ada2c1b076d34cae1999cdea2b7f5c5d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Relações Jurídicas em Direitos Financeiros', '## Relações Jurídicas em Direitos Financeiros

As relações jurídicas em direitos financeiros dependem da relação com o usuário ou contribuinte, sendo reguladas por leis específicas.

### Conceitos
- **Uso efetivo**: cobrança permitida apenas pelo uso real
- **Uso potencial**: cobrança permitida pela possibilidade de uso
- **Direito do consumidor**: regula a relação com o usuário
- **Relação jurídica Estado - contribuinte**: tributária e regulada por leis específicas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre uso efetivo e potencial
- Importância do direito do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:51:28.556816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=46", "doc_key": "ada2c1b076d34cae1999cdea2b7f5c5d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '7963b06136494201896a84b99d69757a37fe206f489874f0ed9dbdeb04b8276e'),
  ('cpiuris2025::456371fd37d436f82aec636fa42aab75', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita Pública', '## Receita Pública

A receita pública é o ingresso do erário, representado pela arrecadação de recursos com reservas e possibilidade de devolução aos particulares.

### Conceitos
- **Receita Pública**: ingresso do erário
- **Arrecadação**: receita do erário
- **Reserva**: possibilidade de devolução aos particulares
- **Receita em sentido amplo**: ingressos que não podem ser utilizados para fazer face às despesas públicas
- **Receita em sentido restrito**: arrecadação definitiva aos cofres públicos sem devolução
- **Pacto federativo**: acordo entre os entes federativos para distribuição de receitas

### Referências legais
- Art. 11 da Lei n.º 4.320/1964
- Súmula 343 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre receita pública em sentido amplo e restrito
- Entender a classificação das receitas em função da competência do ente federativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.45", "page_number": 45, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 11 da Lei n.º 4.320/1964", "Súmula 343 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T06:51:55.553588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=45", "doc_key": "456371fd37d436f82aec636fa42aab75"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '01a455a3082ae01ddecb8120b76f5c600a81783ec72f3f3d3a78fd53d4448226'),
  ('cpiuris2025::f1f702ee99ed7859da4121532fc57f8f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receitas Públicas', '## Receitas Públicas

Descreve as receitas públicas, distinguindo entre originárias e derivadas, e aborda a teoria tripartite e pentapartite dos tributos.

### Conceitos
- **Tributo**: Receita derivada instituída pelas entidades de direito público
- **Taxa**: Receita originária decorrente do exercício do poder de polícia ou da prestação de serviço público específico e divisível
- **Tarifa**: Receita derivada não observando o princípio da anterioridade
- **Princípio da Anterioridade**: Regra que exige que a cobrança de tributos seja feita com antecedência à sua instituição

### Referências legais
- Art. 9º da Lei n.º 4.320/1964

### Dicas de prova
- Diferenciar entre receitas originárias e derivadas
- Entender a teoria tripartite e pentapartite dos tributos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 9º da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:52:02.122630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=46", "doc_key": "f1f702ee99ed7859da4121532fc57f8f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '67a6fb8fa08b59e5ef853da183a20135335d1b2abaaaa242eeb784a59e5a9043'),
  ('cpiuris2025::9045ff9840bed5ff65a1b00b104672dd', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Serviços Públicos e Taxas', '## Serviços Públicos e Taxas

Regras para a remuneração de serviços públicos essenciais e não essenciais, bem como a natureza da receita orçamentária.

### Conceitos
- **Taxa**: Serviço público compulsório
- **Tarifa**: Serviço público facultativo
- **Receita Orçamentária**: Ressalvado o disposto no parágrafo único do art. 3º, todas as receitas arrecadadas

### Referências legais
- Art. 57 da Lei n.º 4.320/1964
- Súmula 412 do STJ
- Súmula 545 do STF

### Jurisprudência
- RE 123456
- STF - Súmula 545
- STJ - Súmula 412

### Dicas de prova
- Diferença entre taxa e tarifa
- Natureza da receita orçamentária
- Princípio da legalidade estrita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 57 da Lei n.º 4.320/1964", "Súmula 412 do STJ", "Súmula 545 do STF"], "jurisprudence": ["RE 123456", "STF - Súmula 545", "STJ - Súmula 412"], "confidence": 0.8, "extracted_at": "2026-05-30T06:53:28.442507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=47", "doc_key": "9045ff9840bed5ff65a1b00b104672dd"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0a33d4192c6eeeffe6ffc7d2f943d34bda12f847b94b8f6c520e6d3dfd575dc2'),
  ('cpiuris2025::0888b548024efb8a311e7423d82e84a0', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receitas Orçamentárias e Extraorçamentárias', '## Receitas Orçamentárias e Extraorçamentárias

A norma legal diferencia receitas de operações de crédito autorizadas em lei das operações de crédito por antecipação de receita, classificando as últimas como extraorçamentárias.

### Conceitos
- **Operações de crédito**: receita orçamentária
- **Operações de crédito por antecipação de receita (ARO)**: receita extraorçamentária

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- 21 STF. Plenário. ADI 800/RS
- ...

### Dicas de prova
- Diferenciar entre receitas orçamentárias e extraorçamentárias
- Memorizar as classificações de operações de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["21 STF. Plenário. ADI 800/RS", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T06:53:29.137286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=47", "doc_key": "0888b548024efb8a311e7423d82e84a0"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '3942f154ef7839e4424a2cfaac2f22dff9b88e4f1b1caff084e037f32c87309e'),
  ('cpiuris2025::be8281f6f34c2bcf521a9d8751468616', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita Extraorçamentária', '## Receita Extraorçamentária

A receita extraorçamentária é um recurso financeiro sem previsão orçamentária, que deve ser devolvido ao particular e não pode ser utilizada para fazer face às despesas orçamentárias.

### Conceitos
- **Receita Extraorçamentária**: Recurso financeiro sem previsão orçamentária
- **Despesa Extraorçamentária**: Despesa não prevista no orçamento
- **Passivo Exigível**: O passivo do ente público quando da realização da despesa extraorçamentária

### Referências legais
- Art. 11, § 1º, da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a diferença entre receita extraorçamentária e despesa extraorçamentária
- Conheça o conceito de passivo exigível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 11, § 1º, da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:54:02.890886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=48", "doc_key": "be8281f6f34c2bcf521a9d8751468616"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b842bc77312be8663d91ee59336393afa47b917e6762f3c641d9a477bb232e8d'),
  ('cpiuris2025::cf3f106f82aeee5d2df1cc2e6bd24b22', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Natureza Jurídica dos Royalties', '## Natureza Jurídica dos Royalties

Royalties são receitas patrimoniais originárias, provenientes da exploração do patrimônio público.

### Conceitos
- **Receita Patrimonial**: receita proveniente da exploração do patrimônio público
- **Royalties**: participação no resultado ou compensação financeira pela exploração dos recursos naturais

### Referências legais
- Art. 20, § 1º, da CF/88

### Dicas de prova
- Entenda a diferença entre royalties e outras receitas correntes.
- Conheça o artigo 20, § 1º, da Constituição Federal de 1988.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 20, § 1º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:54:58.153964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=48", "doc_key": "cf3f106f82aeee5d2df1cc2e6bd24b22"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a6be0b7736f04ef4d80cff486df0efe70c7084c34240f6600ebc18776493a7c0'),
  ('cpiuris2025::f860fd7bcbf6f667b51cb167ef49c133', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receitas de Capital e Orçamento', '## Receitas de Capital e Orçamento

Descreve a distinção entre juros associados aos empréstimos, amortização do principal e receita de capital, bem como a natureza jurídica do superávit orçamentário.

### Conceitos
- **Receitas de Capital**: Rendas provenientes de ativos permanentes ou de investimentos
- **Amortização do Principal**: Redução do valor do principal em decorrência de pagamentos
- **Superávit Orçamentário**: Diferença entre as receitas e despesas correntes de um ano

### Referências legais
- Art. 11, § 3º, da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a distinção entre juros e amortização
- Conheça a natureza jurídica do superávit orçamentário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 11, § 3º, da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:55:24.883903+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=49", "doc_key": "f860fd7bcbf6f667b51cb167ef49c133"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '16409adf681891ca7308a28f47f8f74098dddd6da9e0dcd59045d7b0c5a7bd63'),
  ('cpiuris2025::944017e1924843b9f7185347bb4750bc', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receitas de Capital', '## Receitas de Capital

As receitas de capital são provenientes de operações que não afetam o patrimônio líquido do Estado, como a compra de bens com recursos próprios e a alienação de bens destinada a despesas de capital.

### Conceitos
- **Patrimônio Líquido**: O valor líquido do patrimônio público, após dedução das despesas correntes.
- **Receitas de Capital**: Provenientes de operações que não afetam o patrimônio líquido do Estado.
- **Despesas de Capital**: Despesas classificáveis como despesas de capital, como a compra de bens ou a construção de obras.

### Referências legais
- Art. 11, § 2º, da Lei n.º 4.320/1964
- Art. 20, § 1º, da Constituição Brasileira

### Dicas de prova
- Diferenciar entre receitas de capital e despesas correntes.
- Entender a importância das despesas de capital para o financiamento do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 11, § 2º, da Lei n.º 4.320/1964", "Art. 20, § 1º, da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:55:25.685871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=49", "doc_key": "944017e1924843b9f7185347bb4750bc"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd633b3f721f8b8d1795b6025290a8f908e00d54f934e76694df47b7dc076cffc'),
  ('cpiuris2025::a7a7f6338e8169b5a124caf073219f14', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Lançamento da Receita', '## Lançamento da Receita

O lançamento da receita é o procedimento administrativo que verifica a procedência do crédito fiscal e inscreve o débito desta, conforme art. 53 da Lei n.º 4.320/1964.

### Conceitos
- **Lançamento da Receita**: procedimento administrativo que verifica a procedência do crédito fiscal e inscreve o débito
- **Crédito Tributário**: direito do Estado de cobrar uma determinada quantia
- **Fato Gerador**: ocorrência que gera a obrigação tributária

### Referências legais
- Art. 53 da Lei n.º 4.320/1964
- Art. 52
- Art. 142 do CTN

### Dicas de prova
- Entenda a diferença entre lançamento de receita tributária e não tributária
- Conheça o conceito de fato gerador e sua relação com o crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 53 da Lei n.º 4.320/1964", "Art. 52", "Art. 142 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:57:27.811589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=50", "doc_key": "a7a7f6338e8169b5a124caf073219f14"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '587aaea33583347e5bb8a87b47b70d3aebe899301bf209ec30bb17429a350f17'),
  ('cpiuris2025::e383efee942b39b6030a0fce85b17b57', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita Pública', '## Receita Pública

Descreve a receita pública, incluindo arrecadação, recolhimento e receita corrente líquida.

### Conceitos
- **Arrecadação**: Fase que antecede o recolhimento da receita
- **Recolhimento**: Transferência efetiva dos valores arrecadados à conta única do Tesouro Nacional
- **Receita Corrente Líquida (RCL)**: Somatório das receitas tributárias, de contribuições, patrimoniais, industriais, agropecuárias, de serviços, transferências correntes e outras receitas também correntes

### Referências legais
- Art. 2º, IV da Lei n.º 4.320/1964
- Art. 53 da Lei n.º 4.320/1964
- Art. 56 da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a diferença entre arrecadação e recolhimento.
- Conheça o conceito de receita corrente líquida (RCL) e sua importância na administração pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 2º, IV da Lei n.º 4.320/1964", "Art. 53 da Lei n.º 4.320/1964", "Art. 56 da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:57:50.492079+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=51", "doc_key": "e383efee942b39b6030a0fce85b17b57"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '17c0116f34d32bf6ab3302c4ec6eac596737ffd8558925fc5be0c88a7457be1a'),
  ('cpiuris2025::a40ef9fc957aaf08940a05c71ec3d000', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Previsão e Lançamento de Receita Pública', '## Previsão e Lançamento de Receita Pública

A previsão de receita pública é uma estimativa de percepção de receitas no âmbito da lei orçamentária, com base em normas técnicas e legais. A previsão deve ser feita de acordo com as normas técnicas e legais, considerando os efeitos das alterações na legislação, variação do índice de preços, crescimento econômico ou de qualquer outro fator relevante.

### Conceitos
- **Previsão**: Estimativa de percepção de receitas no âmbito da lei orçamentária
- **Lançamento**: Procedimento pelo qual as receitas são registradas no orçamento corrente
- **Normas técnicas e legais**: Requisitos que devem ser seguidos para a previsão de receita pública

### Referências legais
- Art. 165, § 8º, da CF/88
- Art. 12, da LRF

### Dicas de prova
- Entenda a importância da previsão de receita pública e como ela está relacionada à responsabilidade fiscal.
- Conheça as normas técnicas e legais que devem ser seguidas para a previsão de receita pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 8º, da CF/88", "Art. 12, da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:58:07.557702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=50", "doc_key": "a40ef9fc957aaf08940a05c71ec3d000"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f9b50149f239b0a981817eb01a67b9a0b8a535893754000b0d7f87958b8abf63'),
  ('cpiuris2025::a772e291a5a47b106aa536a3f6ab98a6', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita Corrente Liquida (RCL)', '## Receita Corrente Liquida (RCL)

RCL é definida com base na Receitas Correntes prevista no art. 11, § 1º, da Lei n.º 4.320/1964, com deduções específicas.

### Conceitos
- **Receita Corrente Liquida (RCL)**: definição curta
- **Receitas Correntes**: prevista no art. 11, § 1º, da Lei n.º 4.320/1964
- **Deduções na RCL**: transferências constitucionais, contribuições previdenciárias e receitas financeiras

### Referências legais
- Art. 201 da Constituição
- Art. 11, § 1º, da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a definição de RCL e suas deduções
- Conheça as fontes legais que regem a Receita Corrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 201 da Constituição", "Art. 11, § 1º, da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T06:59:19.901230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=51", "doc_key": "a772e291a5a47b106aa536a3f6ab98a6"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '60a84baccfcc53d4051ee1053638a1d68e0b74b61a48d0151d95a9dee00e357a'),
  ('cpiuris2025::e9dc2805475bd76850b95cb324f0a285', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receita Corrente Líquida (RCL) e Gestão Fiscal', '## Receita Corrente Líquida (RCL) e Gestão Fiscal

A Receita Corrente Líquida é calculada considerando as receitas arrecadadas em um mês e os eleven anteriores, excluindo duplicidades. A gestão fiscal responsável requer a instituição de tributos, previsão e efetiva arrecadação das receitas.

### Conceitos
- **Receita Corrente Líquida (RCL)**: Calculo de receita considerando as receitas arrecadadas em um mês e os eleven anteriores, excluindo duplicidades.
- **Gestão Fiscal Responsável**: Instituição de tributos, previsão e efetiva arrecadação das receitas para garantir a responsabilidade do ente federativo.

### Referências legais
- Art. 2º, § 3º, da LRF
- Art. 100, § 18, da CF/88

### Dicas de prova
- Entenda a diferença entre RCL e receita corrente líquida.
- Conheça os requisitos essenciais da responsabilidade na gestão fiscal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 2º, § 3º, da LRF", "Art. 100, § 18, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:00:03.377061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=52", "doc_key": "e9dc2805475bd76850b95cb324f0a285"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'cadd2e6c4fa36a6764512875c632e5ac5754f275529ccb07036678ca0857d7d0'),
  ('cpiuris2025::79ea7078ec7bafadfff312bde9e2a33f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência e Obrigação Tributária', '## Competência e Obrigação Tributária

A Constituição Federal não cria tributos, mas sim outorga competência aos entes federativos, que não têm obrigação de criar e exigir os tributos. A obediência ao art. 11 da LRF é exigida pelos Tribunais de Contas.

### Conceitos
- **Competência Constitucional**: A competência outorgada pela Constituição Federal aos entes federativos.
- **Obrigação Tributária**: Não existe obrigação constitucional para criar e exigir tributos.
- **Facultatividade do Cumprimento do Mandamento Legal**: Tese não prevalecida no STF.
- **Art. 11 da LRF**: Rege a regularidade das contas públicas.

### Referências legais
- Art. 11 da Lei Renda Federal (LRF)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre competência e obrigação tributária.
- Conheça o art. 11 da LRF e sua aplicação nos Tribunais de Contas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 11 da Lei Renda Federal (LRF)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:00:10.487014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=52", "doc_key": "79ea7078ec7bafadfff312bde9e2a33f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '184c68cb6f3b6950e21df3c883fbdda8eb814f22b7ff04afada6887c42b76e99'),
  ('cpiuris2025::9da0a3d91659cca3b161785258da60ea', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Sanções pela ineficiência arrecadatória', '## Sanções pela ineficiência arrecadatória

O gestor e o ente federativo podem ser responsabilizados pela ineficiência arrecadatória, com sanções incluindo prestação de contas e restrição de transferências voluntárias.

### Conceitos
- **Arrecadação**: receita pública
- **Prestação de contas**: obrigação do gestor de explicar o desempenho da arrecadação
- **Ineficiência arrecadatória**: falta de eficiência na coleta de receitas públicas
- **Lei n.º 8.429/1992**: lei que classificava negligência quanto à arrecadação como ato de improbidade administrativa
- **Lei n.º 14.230/2021**: leis que alteraram a LIA, afastando a possibilidade de configuração de ato improbo causador de dano ao erário

### Referências legais
- Art. 58 da LRF
- Art. 10, X da Lei n.º 8.429/1992
- Parágrafo único do Art. 11 da LRF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre eficiência na arrecadação dos impostos e eficiência em relação aos tributos
- Conheça as sanções aplicáveis ao gestor e ao ente federativo pela ineficiência arrecadatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 58 da LRF", "Art. 10, X da Lei n.º 8.429/1992", "Parágrafo único do Art. 11 da LRF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T07:02:04.364442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=53", "doc_key": "9da0a3d91659cca3b161785258da60ea"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ee9ce9a0313faf387e0b2ae8f9039ebadd713d34cbd260b01690ae636e2dd915'),
  ('cpiuris2025::2c183d007b1e7c300d0fba7ba47c1b9d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Requisitos para a concessão ou aplicação de benefícios fiscais', '## Requisitos para a concessão ou aplicação de benefícios fiscais

A Emenda Constitucional n.º 95/2016 estabeleceu requisitos para a concessão ou alteração de despesas obrigatórias ou renúncias de receita, incluindo o acompanhamento de estimativa de impacto financeiro e orçamentário.

### Conceitos
- **Requisitos para a concessão de benefícios fiscais**: Acompanhamento de estimativa de impacto financeiro e orçamentário
- **Impacto financeiro**: Efeito econômico que resulta da concessão ou alteração de despesas obrigatórias ou renúncias de receita
- **Requisitos constitucionais**: Acompanhamento de estimativa de impacto financeiro e orçamentário, atendimento a requisitos da LDO e demonstração de medidas de compensação

### Referências legais
- Art. 113 ADCT
- Art. 14 LRF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância do acompanhamento de estimativa de impacto financeiro e orçamentário
- Conheça os requisitos constitucionais para a concessão ou alteração de despesas obrigatórias ou renúncias de receita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 113 ADCT", "Art. 14 LRF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:02:32.908396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=54", "doc_key": "2c183d007b1e7c300d0fba7ba47c1b9d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '4596a60880c80acce8d1c13ecea9293386c831a671538b568b19fa9a61c63f63'),
  ('cpiuris2025::2fe4e4c94b1dc01f6819342379b78ba8', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Renúncia de Receitas e Demonstrativos Orçamentários', '## Renúncia de Receitas e Demonstrativos Orçamentários

O artigo 165, § 6º, da CF/88 exige que o projeto de lei orçamentária seja acompanhado de um demonstrativo regionalizado sobre a renúncia de receitas. Além disso, as formas de renúncia de receita exigem autorização em lei específica, exceto para benefícios fiscais envolvendo o ICMS.

### Conceitos
- **Renúncia de Receita**: Acessão voluntária a uma dedução ou exclusão de receita tributária
- **Demonstrativo Orçamentário**: Relatório que detalha o impacto da renúncia fiscal no orçamento
- **Isenção**: Exceção de pagamento de impostos ou taxas
- **Anistia**: Perdão condicional por infrações penais
- **Remissão**: Redução ou suspensão do pagamento de dívidas
- **Subsídio**: Apoio financeiro concedido pelo Estado a uma pessoa física ou jurídica

### Referências legais
- Art. 165, § 6º, da CF/88
- Art. 150, § 6º, da CF/88
- Art. 155, § 2.º, XII, g.

### Dicas de prova
- Entenda a diferença entre isenção e subsídio
- Conheça as formas de renúncia de receita e suas exigências legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 165, § 6º, da CF/88", "Art. 150, § 6º, da CF/88", "Art. 155, § 2.º, XII, g."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:03:04.683431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=53", "doc_key": "2fe4e4c94b1dc01f6819342379b78ba8"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'fdab7dc7c15165c47c4b6caa1bef2d1590032155815ac81b64139ca4f6a388b8'),
  ('cpiuris2025::24ff968f580f98ce9c3aa1d9913755e5', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Benefício Fiscal e Repartição de Receitas Tributárias', '## Benefício Fiscal e Repartição de Receitas Tributárias

O benefício fiscal depende da comprovação de medidas de compensação de receita, e não se aplica à redução de alíquota ou cancelamento de débito. A repartição de receitas tributárias garante a obtenção de recursos para os entes federativos.

### Conceitos
- **Benefício Fiscal**: ajuste tributário
- **Repartição de Receitas Tributárias**: transferência de receitas entre os entes federativos

### Referências legais
- Art. 14, § 3º da LRF

### Dicas de prova
- Entenda a diferença entre redução de alíquota e cancelamento de débito
- Conheça as formas de repartição de receitas tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 14, § 3º da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:03:45.754458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=54", "doc_key": "24ff968f580f98ce9c3aa1d9913755e5"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '9de967b2e294570a15c52da4a96f535c2fe921a580fef62a4307fad3d39f6f61'),
  ('cpiuris2025::9e1a3cc2d714279b90b7ddbb7b47ea93', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Repartição de Receitas Tributárias', '## Repartição de Receitas Tributárias

A repartição de receitas tributárias pode ocorrer de duas formas: direta ou indireta, com critérios específicos para cada tipo.

### Conceitos
- **Direta**: Repartição sem passar por fundo ou intermediação
- **Indireta**: Repartição com intermediação de fundos e critérios definidos em lei
- **Índice de Valor Agregado**: Critério utilizado na repartição indireta para corrigir desigualdades regionais
- **Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação (FUNDEB)**: Fundo que repassa recursos para fins específicos, com o fim de organizar a repartição
- **Repartição Indireta**: Repartição com intermediação de fundos e critérios definidos em lei

### Referências legais
- Art. 157 da CF/88
- Art. 158 da CF/88
- Art. 159 da CF/88

### Dicas de prova
- Diferenciar entre direta e indireta na repartição de receitas tributárias
- Entender o papel dos índices de valor agregado e outros critérios na repartição indireta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 157 da CF/88", "Art. 158 da CF/88", "Art. 159 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:05:14.689818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=55", "doc_key": "9e1a3cc2d714279b90b7ddbb7b47ea93"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '3a05dccd7019ac104aee657428bf79f718b97f4074d24f03bd6982bb03cb6eda'),
  ('cpiuris2025::20fd4beeb2085563c7fe01e11ccaf033', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência Residual e Distribuição de Receitas Tributárias', '## Competência Residual e Distribuição de Receitas Tributárias

Resumo objetivo: Descrição da competência residual e distribuição das receitas tributárias entre os entes federativos.

### Conceitos
- **Competência Residual**: Direito do Estado ou Distrito Federal de receber uma parcela do produto da arrecadação
- **Distribuição de Receitas Tributárias**: Mecanismo pelo qual as receitas tributárias são destinadas aos entes federativos
- **ITR**: Imposto sobre o Trabalho
- **IPVA**: Imposto sobre o Valor Adicionado de Veículos Automotores
- **ICMS**: Imposto sobre a Consumo de Bens e Serviços
- **CIDE Combustíveis**: Contribuição para o Desenvolvimento Energético

### Referências legais
- Art. 177, § 4º, II, da CF/88

### Dicas de prova
- Entenda a competência residual e como as receitas tributárias são distribuídas entre os entes federativos.
- Identifique o ITR, IPVA, ICMS e CIDE Combustíveis e suas respectivas taxas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 177, § 4º, II, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:05:15.180457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=55", "doc_key": "20fd4beeb2085563c7fe01e11ccaf033"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '3e040dea70bf4842320ba700ff45edc396b76043775b8ff50449378372a9b6d1'),
  ('cpiuris2025::6174187505f40a05924c8ec93685fc85', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Repartição Indireta de Receitas Públicas', '## Repartição Indireta de Receitas Públicas

A repartição indireta de receitas públicas envolve a distribuição dos fundos entre os Estados e Municípios, com base em critérios estabelecidos pela lei complementar.

### Conceitos
- **Fundo de Participação dos Estados (FPE)**: Fundo destinado à participação dos Estados na repartição indireta de receitas públicas
- **Fundo de Participação dos Municípios (FPM)**: Fundo destinado à participação dos Municípios na repartição indireta de receitas públicas
- **Fundo de Compensação pela Exportação (FPEX)**: Fundo destinado a compensar as perdas de receita decorrentes da exportação de produtos industrializados

### Referências legais
- Art. 161 da Constituição Federal
- EC nº 112/2021

### Dicas de prova
- Entenda a importância da repartição indireta de receitas públicas e como ela é estabelecida pela lei complementar.
- Conheça os critérios de rateio dos fundos previstos na Constituição Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.56", "page_number": 56, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 161 da Constituição Federal", "EC nº 112/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:06:04.304663+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=56", "doc_key": "6174187505f40a05924c8ec93685fc85"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '38c74a0a756035e1bc95e034c8157d79e1bfb8404543051de2c44a037aa853ee'),
  ('cpiuris2025::7ee3ef5b4863c68a0bdef05621ffd00b', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Vinculação de Receita de Impostos a Fundos', '## Vinculação de Receita de Impostos a Fundos

A vinculação da receita de impostos a fundos é vedada, exceto em casos constitucionais ou para realizar objetivos específicos.

### Conceitos
- **Vinculação**: Conexão obrigatória
- **Fundos**: Recursos destinados a um objetivo específico
- **Objetivos**: Programas de trabalho priorizados pela Administração

### Referências legais
- Art. 71 da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a diferença entre vinculação constitucional e para realizar objetivos específicos.
- Leia atentamente o artigo 71 da Lei n.º 4.320/1964', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71 da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:06:55.719405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=57", "doc_key": "7ee3ef5b4863c68a0bdef05621ffd00b"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '8d2444722f6bfeec909912e4823664d847129138064b211b6dc35960236c2427'),
  ('cpiuris2025::a717da77e98d74ee21cba225a57a4847', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Bloqueio de Transferências Constitucionais e Fundos Públicos', '## Bloqueio de Transferências Constitucionais e Fundos Públicos

O artigo 160 da CF/88 impede a retenção ou restrição ao repasse de receitas aos Estados, Distrito Federal e Municípios. Exceções incluem pagamento de créditos e descumprimento de percentuais mínimos para saúde.

### Conceitos
- **Bloqueio de Transferências Constitucionais**: Restrição ao repasse de receitas aos Estados, Distrito Federal e Municípios
- **Fundos Públicos**: Recursos destinados a determinada finalidade pública, conforme objetivos especificados em lei
- **Pessoa Jurídica**: Não se trata de pessoa jurídica, mas sim um tipo especial de gestão de recursos
- **Receitas Específicas**: As receitas que compõem um fundo devem ser específicas, instituídas em lei ou outra receita qualquer

### Referências legais
- Art. 160 da CF/88
- EC nº 113/2021

### Dicas de prova
- Entenda a importância do bloqueio de transferências constitucionais e as exceções estabelecidas pela lei.
- Conheça as características dos fundos públicos e sua natureza jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 160 da CF/88", "EC nº 113/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:07:26.883439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=57", "doc_key": "a717da77e98d74ee21cba225a57a4847"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '1cd1e49f62944bf85db8324f2dddaf39c9fb6415c30c78202ee756542357bba8'),
  ('cpiuris2025::6c54306d95e070010b66d2f117c12f0d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Fundo Público', '## Fundo Público

O fundo público é uma exceção aos Princípios da Especificação e da Unidade de Tesouraria. Sua criação exige autorização legislativa prévia, conforme o art. 167, IX, da CF/88.

### Conceitos
- **Fundo Público**: instituição financeira pública que tem como objetivo alcançar objetivos específicos
- **Destinação das disponibilidades do caixa especial**: é por meio dela que se identificará a destinação das disponibilidades deste caixa especial
- **Descentralização interna do processo decisório**: só haverá essa medida se a autoridade administrativa assim o quiser
- **Plano de aplicação, contabilidade e prestação de contas**: nesse caso, há um plano de aplicação em que ficarão evidenciadas as origens dos recursos financeiros e as suas aplicações
- **Criação dos fundos**: exige autorização legislativa prévia, conforme o art. 167, IX, da CF/88
- **Instituição e funcionamento dos fundos**: cabe à lei complementar estabelecer condições para instituição e funcionamento dos fundos
- **Princípios da Especificação e da Unidade de Tesouraria**: exceção aos fundos, pois suas dotações não são detalhadas e as receitas não são depositadas no caixa único do Tesouro

### Referências legais
- Art. 167, IX, da CF/88
- Art. 165, § 9º, II, da CF/88
- Lei n.º 4.320/1964

### Dicas de prova
- Entenda a noção de fundo público e suas características
- Conheça as regras para a criação e funcionamento dos fundos públicos
- Destaque a importância da especificação e unidade de tesouraria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167, IX, da CF/88", "Art. 165, § 9º, II, da CF/88", "Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:08:02.269533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=58", "doc_key": "6c54306d95e070010b66d2f117c12f0d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '04d24365d3f6b3b036241301f08bdf5c193ba117be99172ed0c71bf57c976326'),
  ('cpiuris2025::3c30d31528e8d68e4e5888a8d653f312', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Vinculação de receitas orçamentárias e cessão de direitos creditórios', '## Vinculação de receitas orçamentárias e cessão de direitos creditórios

A vinculação de receitas orçamentárias ocorre mediante execução direta por programação orçamentária e financeira. A cessão de direito creditório é um negócio jurídico bilateral, gratuito ou oneroso, pelo qual o credor transfere a sua posição na relação obrigacional.

### Conceitos
- **Vinculação de receitas orçamentárias**: Execução direta por programação orçamentária e financeira
- **Cessão de direito creditório**: Negócio jurídico bilateral, gratuito ou oneroso

### Referências legais
- Art. 39-A da Lei nº 4.320/1964
- Lei Complementar nº 208/2024

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre vinculação de receitas orçamentárias e cessão de direito creditório
- Conheça as implicações da Lei Complementar nº 208/2024', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 39-A da Lei nº 4.320/1964", "Lei Complementar nº 208/2024"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:10:08.811504+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=58", "doc_key": "3c30d31528e8d68e4e5888a8d653f312"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c9205e456078e6101c88f6f67d1ff10d673140b16d435e4564fbdfdb31df5572'),
  ('cpiuris2025::e9a1d09255363a028dd717e92cfa78c5', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Cessão de Crédito', '## Cessão de Crédito

A cessão de crédito é regulamentada pela legislação, com regras específicas para a instituição financeira controlada pelo ente cedente. A vedação estabelecida pelo § 8º impede a participação em operações de aquisição primária dos direitos creditórios desse ente.

### Conceitos
- **Cessão de Crédito**: Alienação de um direito
- **Ente Cedente**: Pessoa jurídica que cede o crédito
- **Cessionário**: Pessoa jurídica que recebe o direito de credor
- **Instituição Financeira Pública**: Entidade pública que atua como prestadora de serviços na estruturação financeira da operação

### Referências legais
- Art. 39-A
- Art. 44 da LRF
- Art. 167, IV, da CF

### Dicas de prova
- Entenda a diferença entre cedente e cessionário
- Conheça as regras específicas para a instituição financeira controlada pelo ente cedente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 39-A", "Art. 44 da LRF", "Art. 167, IV, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:10:28.103508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=59", "doc_key": "e9a1d09255363a028dd717e92cfa78c5"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '737de988cab5415462263559b2fe7caa79c111f4dcdfea026640d99bcbb48418'),
  ('cpiuris2025::91b5c38185eb86aedcae4da958fa8917', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Cessão de Créditos Tributários', '## Cessão de Créditos Tributários

A cessão de créditos tributários pode ser usada para afastar a vedação do artigo 167, IV, da CF, mas mantém a repartição das receitas tributárias.

### Conceitos
- **Cessão de Créditos Tributários**: Prática que permite ao credor transferir o direito de cobrar uma dívida para outro credor.
- **Art. 167, IV, da CF**: Proíbe a aplicação de receitas de capital para financiar despesas correntes.
- **Parágrafo Único do Art. 11 da LRF**: Regula as competências impositivas fiscais tributárias dos Entes locais.
- **Art. 14 da LRF**: Organiza a estratégia de criação de gastos tributários no processo legislativo.
- **Democratização do Processo de Criação de Gastos Tributários**: Reforço do papel dos Estados e Municípios na criação de gastos tributários.
- **Transparência Constitucional**: Importância da transparência no processo legislativo para a cidadania fiscal.
- **Financiamento de Despesas Correntes**: Uso de receitas de capital para financiar despesas correntes.
- **Receita de Capital**: Renda gerada por ativos não circulantes, como imóveis ou ações.

### Referências legais
- Art. 167, IV da CF
- Parágrafo Único do Art. 11 da LRF
- Art. 14 da LRF

### Jurisprudência
- ADI 2238
- RE 123456

### Dicas de prova
- Entenda a diferença entre receita de capital e despesa corrente.
- Conheça as regras sobre a aplicação de receitas de capital para financiar despesas correntes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167, IV da CF", "Parágrafo Único do Art. 11 da LRF", "Art. 14 da LRF"], "jurisprudence": ["ADI 2238", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:11:35.493193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=59", "doc_key": "91b5c38185eb86aedcae4da958fa8917"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '38bf30e4fdeee384eb8128ba65f9f7c4f7e2b2664d239c701e3d2a2e755613f5'),
  ('cpiuris2025::fc9c172a81191f0054a4ba02ec059503', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receitas e Despesas Financeiras', '## Receitas e Despesas Financeiras

Despesas classificáveis em Despesas Correntes incluem despesas de recursos financeiros recebidos de pessoas de direito público ou privado, enquanto Receitas de Capital incluem recursos financeiros oriundos de constituição de dívidas e conversão de bens e direitos.

### Conceitos
- **Despesas Correntes**: despesas classificáveis
- **Receitas de Capital**: recursos financeiros oriundos de constituição de dívidas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre Despesas Correntes e Receitas de Capital.
- Não confunda as despesas com os recursos financeiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:11:59.365811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=60", "doc_key": "fc9c172a81191f0054a4ba02ec059503"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b636a1f2fae7a4b88e8d6d9b93c7221b067847f5ea5edf1b52ea5c055db9b8b9'),
  ('cpiuris2025::a33503fb93b86d9cfdced15e4da0f862', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Receitas Públicas e Constitucionalidade de Leis Estaduais', '## Receitas Públicas e Constitucionalidade de Leis Estaduais

A iniciativa de lei para disciplinar o sistema financeiro de conta de depósitos judiciais não cabe ao Poder Judiciário, pois a recepção e gestão dos depósitos têm natureza administrativa. Leis estaduais que permitem utilização de recursos em percentual superior ao previsto na legislação nacional são inconstitucionais.

### Conceitos
- **Receita Pública**: Fonte de financiamento do Estado
- **Competência Tributária**: Atribuição da Constituição para os entes federados instituir tributos
- **Lei Estadal**: Lei aprovada por um estado ou município
- **ADCT**: Ato das Disposições Constitucionais Transitórias
- **Recepção e Gestão de Depósitos Judiciais**: Atividade administrativa do Poder Judiciário

### Referências legais
- Art. 101, §2º, I e II, e 3º, do Ato das Disposições Constitucionais Transitórias; Lei Complementar federal 151/2015; Lei federal 10.482/2002

### Jurisprudência
- ADI 5080
- ADI 6303/RR
- RE 123456

### Dicas de prova
- Entenda a competência tributária e a natureza da receita pública
- Conheça as normas constitucionais que regem a disciplina do sistema financeiro de conta de depósitos judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 101, §2º, I e II, e 3º, do Ato das Disposições Constitucionais Transitórias; Lei Complementar federal 151/2015; Lei federal 10.482/2002"], "jurisprudence": ["ADI 5080", "ADI 6303/RR", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:12:57.663064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=60", "doc_key": "a33503fb93b86d9cfdced15e4da0f862"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ae8f7ee58eb0281b68b68e3f5b43b575ce4b810c333829116d5cfbaf524f6180'),
  ('cpiuris2025::6c09e4de5eccdd8ceb70897571b6b9bd', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Obrigação de Estimar Impacto Financeiro', '## Obrigação de Estimar Impacto Financeiro

A obrigação de estimar o impacto financeiro previsto na LRF aplica-se apenas em caso de renúncia de receita de natureza tributária.

### Conceitos
- **Art. 113 do ADCT**: Rege a aplicabilidade da obrigação de estimar o impacto financeiro
- **LRF**: Lei que regula a Receita Federal do Brasil
- **Renúncia de receita de natureza tributária**: Situação em que a obrigação de estimar o impacto financeiro é aplicada

### Referências legais
- Art. 113 do ADCT
- Lei 9.532/98
- Lei 4.320/64

### Dicas de prova
- Distinção entre renúncia de receita tributária e outras formas de renúncia
- Importância da aplicação do artigo 113 do ADCT em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.62", "page_number": 62, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 113 do ADCT", "Lei 9.532/98", "Lei 4.320/64"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:13:46.878493+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=62", "doc_key": "6c09e4de5eccdd8ceb70897571b6b9bd"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '330fc2a9ae932059be4283a32358051cb330f8bf274a52cf8ff00dda4c98aa6c'),
  ('cpiuris2025::17c25c53ee2a4c545ab64f060f6cebab', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Fundo Especial e Receitas Públicas', '## Fundo Especial e Receitas Públicas

O fundo especial é um instrumento financeiro utilizado pelo Estado para realizar objetivos precisos de políticas públicas, sendo criado a partir de receitas vinculadas à realização de determinados objetivos ou serviços. O saldo positivo do fundo especial não é transferido para o exercício seguinte, permitindo sua desvinculação a partir do ano subsequente à arrecadação.

### Conceitos
- **Fundo Especial**: instrumento financeiro utilizado pelo Estado
- **Receitas Públicas**: receitas geradas pelo Estado
- **Vinculação de Receitas**: regras que determinam a utilização de receitas para objetivos específicos
- **Desvinculação de Receitas**: processo pela qual o saldo positivo do fundo especial é liberado para uso em outros fins

### Referências legais
- Art. 9º, Lei n.º 4.320/1964
- Art. 11, § 1º, Lei n.º 4.320/1964
- Art. 11, § 2º, Lei n.º 4.320/1964
- Art. 12, § 1º, Lei n.º 4.320/1964
- Art. 12, § 5º, II, Lei n.º 4.320/1964

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de fundo especial e suas características.
- Conheça as regras de vinculação e desvinculação de receitas públicas.
- Aprenda a aplicar a legislação específica sobre fundos especiais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.61", "page_number": 61, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 9º, Lei n.º 4.320/1964", "Art. 11, § 1º, Lei n.º 4.320/1964", "Art. 11, § 2º, Lei n.º 4.320/1964", "Art. 12, § 1º, Lei n.º 4.320/1964", "Art. 12, § 5º, II, Lei n.º 4.320/1964"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T07:14:39.004803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=61", "doc_key": "17c25c53ee2a4c545ab64f060f6cebab"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '3ca06413067dc7023559ddc5f0a3d51b901e14fa5181d4397ddbea5365a5c730'),
  ('cpiuris2025::33f34b036543e7afba8699a1fe5c3fdf', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Despesas públicas são o montante de recursos financeiros despendidos pelo Estado para implementar direitos fundamentais e gerar bem-estar comum.

### Conceitos
- **Despesa pública**: Montante de recursos financeiros despendidos pelo Estado
- **Orçamentárias**: Gastos que constam nas leis orçamentárias e nos créditos adicionais
- **Extraorçamentárias**: Gastos não contabilizados na norma orçamentária
- **Receita extraorçamentária**: Ressida arrecadada com caráter de transitoriedade

### Referências legais
- Art. 77 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre orçamentárias e extraorçamentárias
- Conheça as classificações de despesas públicas mais utilizadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.64", "page_number": 64, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 77 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T07:15:09.990607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=64", "doc_key": "33f34b036543e7afba8699a1fe5c3fdf"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e73172308cdbb12030bd6050b67f075e83a58ea90bb85aa0b0789a06e15dd5d4'),
  ('cpiuris2025::2ec7aeacae05f1fe8d99bd56e4440340', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Despesas públicas são classificadas em despesas correntes e de capital, com as despesas correntes sendo aquelas destinadas a suprir necessidades próprias do Estado, relacionadas à manutenção da máquina pública.

### Conceitos
- **Despesa Corrente**: despesa destinada a suprir necessidades próprias do Estado
- **Despesa de Capital**: despesa que aumenta o patrimônio estatal
- **Ordinárias**: despesas que ocorrem normalmente e são renovadas periodicamente dentro de cada exercício financeiro
- **Extraordinárias**: despesas que não têm previsão orçamentária correspondente, como guerras externas e calamidades públicas

### Referências legais
- Art. 167, § 3º, CF/88

### Dicas de prova
- Diferenciar entre despesas correntes e de capital
- Entender a classificação das despesas em ordinárias e extraordinárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.65", "page_number": 65, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167, § 3º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:15:53.253120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=65", "doc_key": "2ec7aeacae05f1fe8d99bd56e4440340"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f1f7cb08db2861b22f93dee483e04879f0b71eac80123ba5ce65a06fef96fd74'),
  ('cpiuris2025::5bab59643e945277338a239462e60af2', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Subvenções Econômicas e Ajuda Financeira a Empresas Lucrativas', '## Subvenções Econômicas e Ajuda Financeira a Empresas Lucrativas

Despesas correntes do orçamento público são consideradas subvenções econômicas, incluindo ajuda financeira a empresas lucrativas, salvo autorização expressa em lei especial.

### Conceitos
- **Subvenção Econômica**: ajuda financeira pública para empresa lucrativa
- **Despesa Corrente**: despesa do orçamento público que pode ser autorizada anualmente
- **Ajuda Financeira**: financiamento público para empresa lucrativa

### Referências legais
- Art. 19 da Lei de Orçamento
- Art. 12 da Lei n.º 4.320/1964

### Dicas de prova
- Distinção entre despesas correntes e capital
- Importância do artigo 19 da Lei de Orçamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 19 da Lei de Orçamento", "Art. 12 da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:16:53.051730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=66", "doc_key": "5bab59643e945277338a239462e60af2"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '19ee5ecbf7bef7e5a525fe9338e94580ea48bb4c3841db65f32aa8a7f724e3b9'),
  ('cpiuris2025::3e91b69ccaaaa87250f4ec87016924d2', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Despesas públicas são aquelas destinadas à manutenção da máquina do Estado, incluindo pagamento de pessoal, despesas de consumo e juros. Podem ser subdivididas em despesas de custeio e transferências correntes.

### Conceitos
- **Despesa Pública**: Despesa destinada à manutenção da máquina do Estado
- **Despesas de Custo**: Despesas que envolvem uma contraprestação ao pagamento realizado pelo Estado
- **Transferências Correntes**: Despesas que não correspondem à contraprestação em bens e serviços pelo pagamento público efetuado
- **Subvenções Sociais**: Subvenções destinadas a instituições públicas ou privadas de caráter assistencial ou cultural, sem finalidade lucrativa
- **Subvenções Econômicas**: Subvenções destinadas a empresas públicas ou privadas de caráter industrial, comercial, agrícola ou pastoril

### Referências legais
- Art. 12, § 1º, Lei n.º 4.320/1964
- Art. 12, § 2º, Lei n.º 4.320/1964
- Art. 16, Lei n.º 4.320/1964
- Art. 17, Lei n.º 4.320/1964
- Art. 18, Lei n.º 4.320/1964

### Dicas de prova
- Entenda a distinção entre despesas de custeio e transferências correntes
- Conheça as subvenções sociais e econômicas e suas finalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 12, § 1º, Lei n.º 4.320/1964", "Art. 12, § 2º, Lei n.º 4.320/1964", "Art. 16, Lei n.º 4.320/1964", "Art. 17, Lei n.º 4.320/1964", "Art. 18, Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:17:55.499804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=66", "doc_key": "3e91b69ccaaaa87250f4ec87016924d2"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2b3d2e3f691fb6c503bf133bd668e5b8f91ab52b741c8cace3d546707d3a65b1'),
  ('cpiuris2025::38a1af83ad274bac8a8cb7f5f10e0c12', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

As despesas públicas são classificadas em despesas correntes e despesas de capital, sendo as últimas aquelas capazes de gerar acréscimo patrimonial para o Estado.

### Conceitos
- **Despesa Pública**: Gasto realizado pelo poder público
- **Despesas Correntes**: Gastos periódicos e regulares do governo
- **Despesas de Capital**: Investimentos realizados para aumentar a capacidade produtiva ou melhorar a infraestrutura do Estado
- **Investimento**: Aquisição de bens, obras ou serviços com o objetivo de aumentar a capacidade produtiva ou melhorar a infraestrutura do Estado
- **Inversão Financeira**: Operações realizadas para aumentar o capital ou melhorar a liquidez do governo
- **Transferência de Capital**: Aquisição de bens, obras ou serviços com o objetivo de reduzir a dívida pública ou aumentar a capacidade patrimonial do Estado

### Referências legais
- Art. 12 da Lei nº 4.320/1964
- Súmula 646 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre despesas correntes e de capital.
- Conheça as categorias econômicas para investimentos, inversões financeiras e transferências de capital.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.67", "page_number": 67, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 12 da Lei nº 4.320/1964", "Súmula 646 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:18:42.357978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=67", "doc_key": "38a1af83ad274bac8a8cb7f5f10e0c12"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '480a990c2f29566b469ed451f70516d3885f597d03e7a6ed72b6287afa93618a'),
  ('cpiuris2025::444986944cda7fc85f3e14ac4640b56f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Empenho', '## Despesas Públicas e Empenho

O empenho é o ato que cria obrigação de pagamento pendente ou não de implemento de condição, reservando recursos orçamentários para determinada finalidade pública.

### Conceitos
- **Despesa Pública**: Gasto realizado pelo Estado
- **Empenho**: Ato que cria obrigação de pagamento pendente ou não de implemento de condição
- **Nota de Empenho**: Documento comprobatório após o empenho, indicando nome do credor e importância da despesa
- **Dotação Orçamentária**: Reserva de recursos orçamentários para determinada finalidade pública
- **Liquidação**: Etapa administrativa do gasto propriamente dito
- **Pagamento**: Etapa final do processo de despesa pública
- **Lei Orçamentária**: Leis que regulam o orçamento público, como PPA, LDO e LOA
- **Previsão Constitucional**: Art. 167, II da Constituição Brasileira

### Referências legais
- Art. 58 da Lei n.º 4.320/1964
- Art. 60 da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a diferença entre empenho e dotação orçamentária
- Conheça o papel da nota de empenho no processo de despesa pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 58 da Lei n.º 4.320/1964", "Art. 60 da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:19:39.159368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=68", "doc_key": "444986944cda7fc85f3e14ac4640b56f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a53d2433d205506e1780ea28493c58f22398a5c16b3ef17e872c28727f498e31'),
  ('cpiuris2025::2ade6bdade7d0e48fecf63c715dcaede', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Substituição do contrato administrativo', '## Substituição do contrato administrativo

A Administração pode substituir o contrato administrativo por uma nota de empenho, previsto no art. 95 da Lei n.º 14.133/2021, mas há exceções, como permitido pelo art. 60, § 1º, da Lei n.º 4.320/64.

### Conceitos
- **Nota de empenho**: Documento que autoriza a despesa antes do pagamento total
- **Contrato administrativo**: Acordo entre a Administração e o licitante vencedor
- **Substituição do contrato**: Mudança do contrato administrativo por uma nota de empenho

### Referências legais
- Art. 95 da Lei n.º 14.133/2021
- Art. 60, § 1º da Lei n.º 4.320/64

### Dicas de prova
- Entenda a diferença entre nota de empenho e contrato administrativo
- Conheça as hipóteses que permitem a substituição do contrato administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 95 da Lei n.º 14.133/2021", "Art. 60, § 1º da Lei n.º 4.320/64"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:19:53.124921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=68", "doc_key": "2ade6bdade7d0e48fecf63c715dcaede"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '26f139d2bbb973ec2edcc3aa0e48e89923eb8e9a1bda46628c9bff81af605165'),
  ('cpiuris2025::d23d7842f2c06d8700907215343d40e8', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Reforço e Anulação de Empenho', '## Reforço e Anulação de Empenho

O reforço do empenho pode ser insuficiente para arcar com a despesa firmada, sendo o valor anulado apenas parcialmente. Caso o empenho exceda o valor do ajuste, é anulado apenas parcialmente.

### Conceitos
- **Reforço de Empenho**: Aumento do valor do empenho para arcar com a despesa firmada
- **Anulação de Empenho**: Atividade que reverte a importância anulada ao saldo orçamentário

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- REsp. 894.726/RJ

### Dicas de prova
- Distinção entre reforço e anulação de empenho
- Importância do valor do ajuste no cálculo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["REsp. 894.726/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T07:20:43.020418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=69", "doc_key": "d23d7842f2c06d8700907215343d40e8"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '19c1db55b6f1c2e67d3270478f35fa89fcf77c86cba9f0da1668dc877e573165'),
  ('cpiuris2025::bcc91d562cbd3e3da144df587ae70351', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Empenho Público', '## Empenho Público

O empenho público é dividido em três espécies: ordinário, por estimativa e global. O empenho pode ser cancelado total ou parcialmente, independentemente do direito subjetivo do credor.

### Conceitos
- **Liquidez**: A capacidade de se pagar imediatamente
- **Certaeza**: A segurança de que o valor da despesa será pago
- **Exigibilidade**: A obrigação de pagamento do Estado
- **Despesas normais**: Gastos previamente conhecidos e pagos em uma só parcela
- **Estimativa**: Uma noção do montante da despesa, sem precisão certa
- **Créditos orçamentários**: Gastos previamente determinados e pagos em parcelas

### Referências legais
- Art. 60, § 2º, da Lei n.º 4.320/1964
- Art. 59, § 1º, da Lei n.º 4.320/1964

### Jurisprudência
- Súmula 332 do STJ

### Dicas de prova
- Entenda a diferença entre liquidez, certeza e exigibilidade no contexto do empenho público
- Conheça as espécies de empenho público (ordinário, por estimativa e global)
- Aprenda a distinguir entre despesas normais e estimativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 60, § 2º, da Lei n.º 4.320/1964", "Art. 59, § 1º, da Lei n.º 4.320/1964"], "jurisprudence": ["Súmula 332 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T07:20:48.360286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=69", "doc_key": "bcc91d562cbd3e3da144df587ae70351"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '3149df7aefc284312931cf006d0f1f87fea4aba9df0db43177bbb3d32553693a'),
  ('cpiuris2025::55c84a3d691495c2398e310fa926894a', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Ordem cronológica de pagamento de obrigações', '## Ordem cronológica de pagamento de obrigações

O pagamento de obrigações deve seguir a ordem cronológica das datas de exigibilidade, salvo razões de interesse público e prévia justificativa.

### Conceitos
- **ordem cronológica**: sequência lógica de pagamento de obrigações
- **exigibilidade**: data em que a obrigação deve ser paga
- **razões de interesse público**: motivos legítimos que justificam exceção à ordem cronológica

### Referências legais
- Art. 114, Lei n.º 14.133/2021
- Art. 337-H, Código Penal (Lei n.º 14.133/2021)

### Dicas de prova
- Perguntas sobre ordem cronológica de pagamento podem ser difíceis, mas é importante entender a estrutura das leis e regulamentos.
- A discriminação entre razões de interesse público e exceções à ordem cronológica é crucial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 114, Lei n.º 14.133/2021", "Art. 337-H, Código Penal (Lei n.º 14.133/2021)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:22:50.192298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=70", "doc_key": "55c84a3d691495c2398e310fa926894a"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'daa97dd3956e53b8aad53fb280c329174ef8264136e4ba4691c95e3c28ccd2b3'),
  ('cpiuris2025::a4b4aca288a0c774fc8942b3027bcb5b', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Liquidação de Despesas Públicas', '## Liquidação de Despesas Públicas

A liquidação de despesa pública consiste na verificação do direito adquirido pelo credor, com base nos títulos e documentos comprobatórios do crédito. O objetivo é apurar a origem, objeto, importância e quem deve ser pago.

### Conceitos
- **Liquidação**: Verificação do direito adquirido pelo credor
- **Despesa Pública**: Gasto realizado pela Administração Pública
- **Credor**: Parte que tem direito a ser pago
- **Títulos e Documentos Comprobatórios**: Provas do crédito, como contratos e recibos

### Referências legais
- Art. 63 da Lei n.º 4.320/1964
- Art. 67 da Lei n.º 8.666/1993
- Art. 117 da Lei n.º 14.133/2021

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre liquidação e pagamento de despesa pública
- Conheça os requisitos para a liquidação da despesa, como a presença do fiscal do contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 63 da Lei n.º 4.320/1964", "Art. 67 da Lei n.º 8.666/1993", "Art. 117 da Lei n.º 14.133/2021"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:23:22.786687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=70", "doc_key": "a4b4aca288a0c774fc8942b3027bcb5b"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '1021209251b1e75b9ce1daafae174d01de7c5d64dcb18f8ae561fe40de0fb387'),
  ('cpiuris2025::02b42753dc6b2cdd066b052fb81bd7e7', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Regime Contábil da Despesa', '## Despesas Públicas e Regime Contábil da Despesa

O regime contábil da despesa é dividido em três espécies: regime de caixa, regime de competência e regime misto. O regime de caixa é aplicado às receitas e ao regime de competência é aplicado às despesas.

### Conceitos
- **Despesa Pública**: Gasto realizado pelo poder público
- **Regime Contábil da Despesa**: Procedimento utilizado para registrar fatos ocorridos no âmbito da ciência contábil
- **Regime de Caixa**: Aplicado às receitas e despesas que ocorrem durante o exercício financeiro
- **Regime de Competência**: Aplicado às despesas que se correlacionam ao exercício em que foram empenhadas
- **Regime Misto**: Utilizado pela contabilidade pública brasileira, que combina os dois regimes anteriores

### Referências legais
- Art. 35 da Lei n.º 4.320/1964
- Art. 50 da LRF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre o regime de caixa e o regime de competência
- Conheça as características do regime misto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 35 da Lei n.º 4.320/1964", "Art. 50 da LRF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:23:37.454189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=71", "doc_key": "02b42753dc6b2cdd066b052fb81bd7e7"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '620aa15f60054fb0c81c243ea9cff9a4565a31a8ab69d945f06a1db27ad8d4e0'),
  ('cpiuris2025::c75e26d690b7681be6509289cba5baaa', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Prazo para pagamento de restos a pagar', '## Prazo para pagamento de restos a pagar

O prazo para pagamento de restos a pagar não é específico na Lei n.º 4.320/1964, mas sim deve ser pago durante o exercício financeiro subsequente até 31 de dezembro do ano seguinte à realização do empenho.

### Conceitos
- **Restos a pagar**: Despesas não liquidadas e pendentes de pagamento
- **Empenho**: Atividade financeira que envolve a garantia de pagamento de uma despesa

### Referências legais
- Art. 33 da Lei n.º 4.320/1964
- Decreto n.º 93.872/1986

### Jurisprudência
- Al 631.841/SP
- Relator Min. Celso de Mello, Julgamento 24/04/2009

### Dicas de prova
- Diferenciar entre restos a pagar processados e não processados
- Entender o conceito de empenho e sua relação com o pagamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 33 da Lei n.º 4.320/1964", "Decreto n.º 93.872/1986"], "jurisprudence": ["Al 631.841/SP", "Relator Min. Celso de Mello, Julgamento 24/04/2009"], "confidence": 0.8, "extracted_at": "2026-05-30T07:24:43.386621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=71", "doc_key": "c75e26d690b7681be6509289cba5baaa"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '85a059546de17b04c6537abb92fd3800aa8b65ab476877107f6bd61ed9e6f06f'),
  ('cpiuris2025::1bfed8831fbbb60b1d73389a51d8769e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Disponibilidade de Caixa e Responsabilidade do Governante', '## Disponibilidade de Caixa e Responsabilidade do Governante

A disponibilidade de caixa é determinada considerando os encargos e despesas compromissadas a pagar até o final do exercício, vedando a inscrição no último ano do mandato sem apoio financeiro. A Lei Complementar nº 178/2021 alterou o artigo 42 da Lei Complementar nº 101/2000.

### Conceitos
- **Disponibilidade de Caixa**: A capacidade do governo de pagar suas obrigações
- **Encargos e Despesas**: Obrigações e gastos comprometidos a serem pagos até o final do exercício
- **Vedação**: Proibição ou restrição de uma ação ou comportamento
- **Responsabilidade do Governante**: A responsabilidade do governante por suas ações e decisões

### Referências legais
- Art. 359-C do Código Penal
- Lei Complementar nº 178/2021
- Lei Complementar nº 101/2000

### Jurisprudência
- 34 STJ, 2a Turma, REsp 1141021 (21/08/2012)

### Dicas de prova
- Entenda a relação entre disponibilidade de caixa e responsabilidade do governante
- Conheça as alterações feitas pela Lei Complementar nº 178/2021 no artigo 42 da Lei Complementar nº 101/2000', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 359-C do Código Penal", "Lei Complementar nº 178/2021", "Lei Complementar nº 101/2000"], "jurisprudence": ["34 STJ, 2a Turma, REsp 1141021 (21/08/2012)"], "confidence": 0.8, "extracted_at": "2026-05-30T07:26:05.943190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=72", "doc_key": "1bfed8831fbbb60b1d73389a51d8769e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd0e0b8e19451304b71832cbfc402accd64e09dc0775a8db9753f4f016a8cde78'),
  ('cpiuris2025::b48f1e59625e6bf2c4352f5d9d4e5c5d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Restos a Pagar', '## Restos a Pagar

Despesas públicas que não foram arrecadadas em um exercício financeiro devem ser canceladas se não houver liquidação dentro do mesmo. A prescrição corre a partir da data de inscrição, mas pode ser interrompida com o cancelamento dos restos a pagar.

### Conceitos
- **Restos a Pagar**: Despesas públicas não arrecadadas em um exercício financeiro
- **Prescrição**: Processo pelo qual uma obrigação passa a ser considerada extinta sem que haja sido pagada
- **Cancelamento de Restos a Pagar**: Ação que interrompe a prescrição e cancela os restos a pagar
- **Inscrição em Restos a Pagar**: Atividade administrativa que registra despesas públicas não arrecadadas

### Referências legais
- Art. 68 do Decreto n.º 93.872/1986
- Art. 70 do Decreto n.º 93.872/1986
- Art. 22, § 2º, ''b'' do Decreto n.º 93.872/1986
- Art. 36, parágrafo único da Lei n.º 4.320/1964

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre prescrição e cancelamento de restos a pagar
- Conheça as regras para inscrição em restos a pagar e como elas afetam a prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 68 do Decreto n.º 93.872/1986", "Art. 70 do Decreto n.º 93.872/1986", "Art. 22, § 2º, ''b'' do Decreto n.º 93.872/1986", "Art. 36, parágrafo único da Lei n.º 4.320/1964"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:26:11.062419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=72", "doc_key": "b48f1e59625e6bf2c4352f5d9d4e5c5d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'caedcbd4fa400ab4219160c328fba000028caf596eddf4bde289b78c0988f4bb'),
  ('cpiuris2025::be7ac11071256965550d360df6a622fe', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Regime de Adiantamento', '## Despesas Públicas e Regime de Adiantamento

A vedação prevista no artigo 42 da LRF deixará de existir em 2023, e o art. 50, V, determina que as operações de crédito sejam escrituradas para evidenciar a dívida pública. O regime de adiantamento é medida excepcional de pagamento aplicável a despesas de pequena monta, com regras específicas sobre a concessão e utilização do numerário.

### Conceitos
- **Despesas Públicas**: Gastos realizados pelo Estado ou por entidades públicas
- **Regime de Adiantamento**: Medida excepcional de pagamento aplicável a despesas de pequena monta
- **Vedação**: Restrição ou proibição de uma ação ou prática
- **Dívida Pública**: Sobrancelho que representa o valor do gasto público

### Referências legais
- Art. 42 da LRF
- Art. 50, V da LRF

### Dicas de prova
- Entenda a diferença entre despesas públicas e regime de adiantamento
- Conheça as regras específicas sobre a concessão e utilização do numerário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 42 da LRF", "Art. 50, V da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:27:06.339174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=73", "doc_key": "be7ac11071256965550d360df6a622fe"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6997b5bf5000882555216af070fc3cb7e4890f8c13da36e5f1333bc0aeddcb6a'),
  ('cpiuris2025::439f464c81637537848ef902414a71eb', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Contratos Verbais e Licitações', '## Contratos Verbais e Licitações

Rege-se o contrato verbal com a Administração apenas em casos de pequenas compras de pronto pagamento, acima de 5% do limite estabelecido na Lei n.º 8.666/1993.

### Conceitos
- **Contrato Verbal**: Acordo feito sem escritura formal
- **Licitação**: Processo público para a contratação de bens ou serviços
- **Lei n.º 8.666/1993**: Regulamenta as licitações e contratos da Administração Pública

### Referências legais
- Art. 60, parágrafo único, da Lei n.º 8.666/1993

### Dicas de prova
- Distinção entre contrato verbal e licitação
- Importância do valor das compras de pronto pagamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 60, parágrafo único, da Lei n.º 8.666/1993"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-30T07:27:50.837899+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=73", "doc_key": "439f464c81637537848ef902414a71eb"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '36b9ad796882d7f91408112882cb8b81ba63c2d356fb6d9588de8f69475bbdb7'),
  ('cpiuris2025::4a1cdddc5f0d5319ccf9d015320a0bff', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas - DEA (Despesas de Exercícios Anteriores)', '## Despesas Públicas - DEA (Despesas de Exercícios Anteriores)

As despesas de exercícios anteriores (DEA) são despesas resultantes de compromissos assumidos em exercício anterior, mas pagas em exercícios posteriores. Elas são vinculadas ao exercício anterior de empenho e não àquele do pagamento.

### Conceitos
- **DEA**: Despesas de Exercícios Anteriores
- **Competência**: Regime contábil aplicável às despesas públicas
- **Art. 37, da Lei n.º 4.320/1964**: Dispositivo que estabelece as regras para o pagamento de despesas de exercícios encerrados

### Referências legais
- Art. 37, da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a diferença entre DEA e restos a pagar
- Conheça o artigo 37 da Lei n.º 4.320/1964', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 37, da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:28:22.026628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=74", "doc_key": "4a1cdddc5f0d5319ccf9d015320a0bff"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6af5e79754848571b4f42b0921c2e46b1ee2111375d630e55594f64215a7dbdd'),
  ('cpiuris2025::1599cdb0ef6ada8956e1aa5d67fa0bdd', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Pagamento de compromissos reconhecidos após o encerramento do exercício correspondente', '## Pagamento de compromissos reconhecidos após o encerramento do exercício correspondente

A Administração pode realizar pagamentos mesmo sem dotação orçamentária se atende à legislação vigente, especialmente em casos de benefícios de servidor que foram requeridos após o período de despesas referentes ao ano anterior.

### Conceitos
- **Dotação DEA**: parte do orçamento destinada a despesas especiais
- **Compromissos reconhecidos**: obrigações de pagamento criadas em virtude de lei, mas não reconhecidas até o encerramento do exercício correspondente
- **Pagamento antecipado**: realização de pagamento antes da data prevista

### Referências legais
- Art. 22, § 2º, Decreto n.º 93.872/1986

### Dicas de prova
- Entenda a diferença entre dotação orçamentária e despesas especiais
- Conheça o conceito de compromissos reconhecidos após o encerramento do exercício correspondente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 22, § 2º, Decreto n.º 93.872/1986"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:29:05.372699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=74", "doc_key": "1599cdb0ef6ada8956e1aa5d67fa0bdd"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'dd68e5428a950b0d35672bf30770b9d5afc3721298248d1bc20fa697e38490d4'),
  ('cpiuris2025::e95ac834005f3c131fe3d66e44fc1dab', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas decorrentes de exercícios anteriores e precatórios', '## Despesas decorrentes de exercícios anteriores e precatórios

As despesas decorrentes de exercícios anteriores são consideradas despesas extraorçamentárias, enquanto os precatórios são um sistema próprio de execução e pagamento de dívidas utilizados pelo Estado.

### Conceitos
- **Despesa orçamentária**: despesa prevista no orçamento
- **Despesa extraorçamentária**: despesa não prevista no orçamento
- **Pretório**: ordem judicial expedida em face da Fazenda Pública

### Referências legais
- Art. 100 da Constituição Federal
- EC n.º 113 e 114

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre despesas orçamentárias e extraorçamentárias
- Entender o conceito de precatório e sua finalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da Constituição Federal", "EC n.º 113 e 114"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T07:29:51.684624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=75", "doc_key": "e95ac834005f3c131fe3d66e44fc1dab"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c04226659440f29a1f936eaa9c5e0ccb953c8c4c30eb6ae01476d9fee2d9c9c9'),
  ('cpiuris2025::ca62c0291965d3237b6a1a9c2da95d39', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Pagamento de dívidas judiciais em orçamento público', '## Pagamento de dívidas judiciais em orçamento público

O montante pago deve ser suficiente para o pagamento do débito pleiteado, sendo fixado no orçamento posterior à elaboração.

### Conceitos
- **Pretório**: Precedente judicial
- **Orçamento público**: Mês em que as despesas são alocadas
- **Pagamento de dívidas judiciais**: Satisfação do débito pleiteado

### Referências legais
- Art. 100 da CF/88

### Dicas de prova
- Entenda a ordem cronológica de apresentação dos precatórios
- Conheça o princípio da não designação de casos ou pessoas nas dotações orçamentárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:29:59.246922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=75", "doc_key": "ca62c0291965d3237b6a1a9c2da95d39"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '1db4a77ebe8f39b033794bc71053f2b5fa5a9c5a44279bdce6a691183c76ffa6'),
  ('cpiuris2025::51fa252b92e12cf3daa21b7d22084d5c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Regulamentação da Fazenda Pública na execução fundada em título extrajudicial, incluindo a citação para opor embargos e o pagamento de precatório.

### Conceitos
- **Pretório**: Ato pelo qual se concede ao exequente o direito de receber uma quantia determinada
- **Requisição de pequeno valor**: Ato pelo qual se concede ao exequente o direito de receber uma quantia menor que o valor do crédito
- **Embargos**: Ações apresentadas pela Fazenda Pública para impugnar a execução
- **Precatório**: Ato pelo qual se concede ao exequente o direito de receber uma quantia determinada, após a rejeição das arguições da executada

### Referências legais
- Art. 535 do Código de Processo Civil
- Art. 910 do Código de Processo Civil

### Jurisprudência
- Súmula 311 do STJ

### Dicas de prova
- Entenda a diferença entre precatório e requisição de pequeno valor
- Conheça o prazo para opor embargos e o pagamento de precatório
- Aprenda a importância da inclusão orçamentária para o pagamento de precatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 535 do Código de Processo Civil", "Art. 910 do Código de Processo Civil"], "jurisprudence": ["Súmula 311 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T07:31:31.812968+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=76", "doc_key": "51fa252b92e12cf3daa21b7d22084d5c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b0221a696619d63373ba26cde43328e52d3762a7cc5e6b02704179f017bebada'),
  ('cpiuris2025::f8370c8bd17a7c25ee3c76573e20314d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Pretório Alimentar e Comum', '## Pretório Alimentar e Comum

Os precatórios podem ser comuns ou alimentares. Os precatórios comuns são definidos por exclusão, enquanto os precatórios alimentares são definidos pela CF/88 e têm prioridade sobre todos os demais débitos.

### Conceitos
- **Pretório Alimentar**: Verba que tem como destino a subsistência do credor e de sua família
- **Pretório Comum**: Verba que não se enquadra em nenhuma das categorias de verbas alimentares
- **CF/88**: Constituição Federal de 1988, que estabelece as regras para a classificação e prioridade dos precatórios

### Referências legais
- Art. 100 da CF/88
- Art. 2º do Código Tributário Nacional

### Jurisprudência
- RE 123456
- Súmula 40 STJ

### Dicas de prova
- Entenda a distinção entre precatório alimentar e comum
- Aprenda a aplicar o art. 100 da CF/88 para classificar os precatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da CF/88", "Art. 2º do Código Tributário Nacional"], "jurisprudence": ["RE 123456", "Súmula 40 STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T07:32:08.051526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=77", "doc_key": "f8370c8bd17a7c25ee3c76573e20314d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '8a18d8b6b1fcfb48bbce869a49c9c37c2e1c40ef0e08d31901a040deb0645ef4'),
  ('cpiuris2025::375841cd3346feb3bde1af84e101e670', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Pretório de natureza alimentícia e superpreferência', '## Pretório de natureza alimentícia e superpreferência

O § 3º do artigo determina que o restante do precatório será pago na ordem cronológica de apresentação do precatório, com hipóteses de superpreferência para pessoas idosas, portadores de doenças graves ou deficiência.

### Conceitos
- **Pretório**: precatório de natureza alimentícia
- **Superpreferência**: prioridade especial para certos credores
- **RPV**: Valor Real do Prazo
- **Fila**: ordem cronológica de apresentação do precatório

### Referências legais
- Art. 100, § 2º
- Súmula 432/STJ

### Jurisprudência
- RE 123456
- ADIs 4357 e 4425/STF

### Dicas de prova
- Entenda a noção de superpreferência e sua aplicação
- Conheça o limite do valor da RPV para a fila de superpreferência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100, § 2º", "Súmula 432/STJ"], "jurisprudence": ["RE 123456", "ADIs 4357 e 4425/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:32:52.620367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=77", "doc_key": "375841cd3346feb3bde1af84e101e670"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '5160b3933d6c2c182b4bb914adffde7b385759089d71bbefddecb3046bf19a8e'),
  ('cpiuris2025::cdd46ae7025a14f33d438c63f520d9b4', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Inclusão orçamentária de verba para precatórios', '## Inclusão orçamentária de verba para precatórios

A inclusão orçamentária da verba necessária para o pagamento dos precatórios do exercício seguinte é alterada para 2 de abril, não mais 1º de julho, de acordo com a Emenda Constitucional n.º 114/2021.

### Conceitos
- **Pretório**: Verba necessária para o pagamento de dívidas públicas
- **Administração Pública Direta**: Ente público que exerce atividades de interesse público
- **Autarquias**: Entes públicos que exercem atividades específicas
- **Fundações Públicas**: Entes públicos que exploram serviços públicos de competência típica Estatal
- **Atividade Econômica Lucrativa**: Exercício de atividade econômica com intuito de lucro

### Referências legais
- Art. 100 da CF/88
- Emenda Constitucional n.º 114/2021

### Jurisprudência
- {''RE'': ''393.032'', ''Data'': ''27/10/2009''}
- {''RE'': ''938.837'', ''Data'': ''19/04/2017''}

### Dicas de prova
- Distinção entre Administração Pública Direta e outras entidades públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da CF/88", "Emenda Constitucional n.º 114/2021"], "jurisprudence": ["{''RE'': ''393.032'', ''Data'': ''27/10/2009''}", "{''RE'': ''938.837'', ''Data'': ''19/04/2017''}"], "confidence": 0.8, "extracted_at": "2026-05-30T07:33:16.146118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=76", "doc_key": "cdd46ae7025a14f33d438c63f520d9b4"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'effce8785306e79997413b3b1e837801f2bf5f25622d34f065128c66a2c91735'),
  ('cpiuris2025::3fe838e9040189b95ced73c9440218fe', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Pagamento de Precedório', '## Pagamento de Precedório

O pagamento de precatório é sujeito a limites estabelecidos pela Constituição, incluindo o limite do triplo do valor da Renda Pública Vitalícia (RPV), que deve ser observado em cada precatório isoladamente.

### Conceitos
- **Fracionamento**: Divisão do valor do precatório em partes menores, sem extensão a outros títulos do mesmo credor.
- **Superpreferência**: Direito de receber o pagamento do precatório antes dos demais titulares

### Referências legais
- Art. 100, § 2º, da CF/88
- Súmula 598 do STF

### Jurisprudência
- RE 840.435/RS
- Tema 598

### Dicas de prova
- Entenda a noção de fracionamento e superpreferência em relação ao pagamento de precatório.
- Conheça as regras estabelecidas pela Constituição para o pagamento de precatórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100, § 2º, da CF/88", "Súmula 598 do STF"], "jurisprudence": ["RE 840.435/RS", "Tema 598"], "confidence": 0.8, "extracted_at": "2026-05-30T07:35:24.087338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=78", "doc_key": "3fe838e9040189b95ced73c9440218fe"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6bf60c253f5a10d2ac1257fe505d82b6a04d0413cddf43092cea4c51a7054873'),
  ('cpiuris2025::651a3f2f945f54b8b9cfa2495070d549', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Definição de pequeno valor e precatório judiciário', '## Definição de pequeno valor e precatório judiciário

A Constituição Federal estabelece que os débitos ou obrigações com valor igual ou inferior a certa quantidade em salários-mínimos podem ser considerados de pequeno valor, permitindo o pagamento por meio de precatório judiciário.

### Conceitos
- **pequeno valor**: Valor mínimo para os débitos ou obrigações que podem ser considerados de pequeno valor
- **precatório judiciário**: Mecanismo pelo qual a Fazenda pública paga dívidas com valor inferior a um determinado valor

### Referências legais
- Art. 87 do Ato das Disposições Constitucionais Transitórias
- Art. 78 do Ato das Disposições Constitucionais Transitórias
- § 3º do art. 100 da Constituição Federal

### Jurisprudência
- 41 STJ. 1ª Turma. AgInt no RMS 44.792/RO
- 42 STJ. 1ª Turma. AgInt no RMS 61014-RO

### Dicas de prova
- Entenda a diferença entre o valor mínimo e o valor máximo para os débitos ou obrigações que podem ser considerados de pequeno valor
- Conheça o mecanismo do precatório judiciário e como ele se aplica às Fazendas públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 87 do Ato das Disposições Constitucionais Transitórias", "Art. 78 do Ato das Disposições Constitucionais Transitórias", "§ 3º do art. 100 da Constituição Federal"], "jurisprudence": ["41 STJ. 1ª Turma. AgInt no RMS 44.792/RO", "42 STJ. 1ª Turma. AgInt no RMS 61014-RO"], "confidence": 0.8, "extracted_at": "2026-05-30T07:35:55.975617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=78", "doc_key": "651a3f2f945f54b8b9cfa2495070d549"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f3f8f64d5f439645fefbdb70ac8b517a5d1b45ddf9a425d24fcb48192478403d'),
  ('cpiuris2025::e17e54f4fd8883423890fcd6d07c04b9', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Piso de Pequeno Valor (RPV) e Limites para Pagamento', '## Piso de Pequeno Valor (RPV) e Limites para Pagamento

O piso de pequeno valor é definido pela Lei n.º 10.259/2001, fixado em 60 salários-mínimos. Os entes federativos podem editar leis reduzindo o valor, mas devem respeitar sua efetiva capacidade econômica.

### Conceitos
- **Piso de Pequeno Valor**: Valor mínimo para pagamento de despesas públicas
- **RPV**: Requisição de Pequeno Valor, processo judicial para cobrança de pequenas dívidas públicas
- **Capacidade Econômica**: Habilidade do ente federativo para pagar suas obrigações
- **Lei Orçamentária**: Lei que estabelece o orçamento anual da União, dos estados e municípios
- **Reserva de Iniciativa Legislativa**: Princípio que determina a iniciativa legislativa para certas matérias

### Referências legais
- Art. 100, § 4º da CF/88
- Súmula 326 do STF

### Jurisprudência
- ADI 5706
- Tema de Repercussão Geral 1.326

### Dicas de prova
- Entenda a definição do piso de pequeno valor e sua importância nos pagamentos públicos.
- Conheça a capacidade econômica dos entes federativos e como ela afeta o pagamento de RPV.
- Aprenda a distinguir entre leis orçamentárias e outras formas de legislação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100, § 4º da CF/88", "Súmula 326 do STF"], "jurisprudence": ["ADI 5706", "Tema de Repercussão Geral 1.326"], "confidence": 0.8, "extracted_at": "2026-05-30T07:36:23.036256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=79", "doc_key": "e17e54f4fd8883423890fcd6d07c04b9"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '5ecb76b3c15ab8141bc08c5f78785b18afba4d97f2289159cac0f6221148f69a'),
  ('cpiuris2025::ab4a0e38d1df58ad23411530450fbcfd', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Obrigação de Pequeno Valor (RPV) e Função Administrativa do Tribunal', '## Obrigação de Pequeno Valor (RPV) e Função Administrativa do Tribunal

A iniciativa legislativa para definição de RPV não é exclusiva do chefe do Poder Executivo. O valor a ser considerado deve ser definido pela parcela individual devida a cada litigante, com correção monetária no período entre cálculo e expedição.

### Conceitos
- **Obrigação de Pequeno Valor (RPV)**: obrigação que pode ser pagada em pequenas quantias
- **Litisconsórcio Ativo**: situação em que mais de uma pessoa é responsável pelo mesmo débito
- **Função Administrativa do Tribunal**: comunicação à Fazenda Pública sobre existência de obrigação para processamento dos precatórios

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 729107
- ADI 5100
- RE 579.431

### Dicas de prova
- Entenda a diferença entre RPV e litisconsórcio ativo.
- Conheça a função administrativa do Tribunal em relação aos precatórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 729107", "ADI 5100", "RE 579.431"], "confidence": 0.8, "extracted_at": "2026-05-30T07:37:37.239037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=79", "doc_key": "ab4a0e38d1df58ad23411530450fbcfd"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e263d12d9ce7a7050ffbd69271333934b8b20ee93c5e40a0d83133bf7918b960'),
  ('cpiuris2025::457a2ddbec49f8ef0b2778e1988b7ca9', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Precedência', '## Despesas Públicas e Precedência

A despesa pública é consignada no orçamento como despesa pública a ser paga no exercício financeiro seguinte, de acordo com o art. 100, § 6º, da CF/88.

### Conceitos
- **Despesa Pública**: Gasto público autorizado pela Constituição
- **Pretendência**: Direito de receber o valor do crédito antes de outros credores
- **Precedência**: Ordem em que os credores devem ser pagos
- **Fracionamento**: Divisão do valor da execução para fins de enquadramento de parcela do total
- **Suplementação**: Aumento do valor do crédito

### Referências legais
- Art. 100, § 6º, CF/88
- Art. 100, § 7º, CF/88
- Art. 100, § 8º, CF/88

### Jurisprudência
- Súmula Vinculante 17

### Dicas de prova
- Entenda a diferença entre despesa pública e precedência
- Conheça as regras de fracionamento e suplementação de precatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100, § 6º, CF/88", "Art. 100, § 7º, CF/88", "Art. 100, § 8º, CF/88"], "jurisprudence": ["Súmula Vinculante 17"], "confidence": 0.8, "extracted_at": "2026-05-30T07:38:15.632087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=80", "doc_key": "457a2ddbec49f8ef0b2778e1988b7ca9"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '73684c074c6228d559348a25bcf77d63c473f2aea5f45cc6c9afecb404871a7f'),
  ('cpiuris2025::1035dd539b400c3912730c5730f60430', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Juros Moratórios e Precatórios', '## Juros Moratórios e Precatórios

Resumo objetivo: Juros moratórios incidem a partir da data de inadimplemento do Estado, além de juros de mora no período entre cálculos e requisição de pequeno valor (RPV) ou precatório. A STF considerou inconstitucional o uso do índice oficial de remuneração básica da caderneta de poupança para atualização monetária dos precatórios.

### Conceitos
- **Juros Moratórios**: incidem a partir da data de inadimplemento do Estado
- **Juros de Mora**: incidem no período entre cálculos e requisição de pequeno valor (RPV) ou precatório
- **Atualização Monetária dos Precatórios**: consideração inconstitucional do uso do índice oficial de remuneração básica da caderneta de poupança

### Referências legais
- Art. 100, § 12, da CF/88

### Jurisprudência
- RE 579.431
- ADIs 4357 e 4425
- Súmula N STF

### Dicas de prova
- Distinção entre juros moratórios e de mora
- Entendimento do critério de atualização monetária dos precatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100, § 12, da CF/88"], "jurisprudence": ["RE 579.431", "ADIs 4357 e 4425", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:38:41.296066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=80", "doc_key": "1035dd539b400c3912730c5730f60430"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '590a4d68194937e8fc23a54a5126fd31f7479bb7481b8547a2c6acfb568bf878'),
  ('cpiuris2025::d9da67e2875a42caa650c99d276ca32d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Índice de correção monetária para condenações em desfavor da Fazenda Pública', '## Índice de correção monetária para condenações em desfavor da Fazenda Pública

A partir da EC nº 113/2021, a SELIC é o índice de correção monetária aplicado nas condenações em desfavor da Fazenda Pública, independentemente da natureza da condenação.

### Conceitos
- **SELIC**: Sistema Especial de Liquidação e de Custódia
- **índice de correção monetária**: método utilizado para atualizar valores de condenações em desfavor da Fazenda Pública
- **precatório**: direito do credor à realização de uma ação judicial para receber o valor devido
- **cessão de precatórios**: transferência parcial ou total de créditos em precatórios para terceiros

### Referências legais
- Art. 3º da EC nº 113/2021
- Art. 5º da EC nº 113/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre SELIC e juros de mora
- Conheça o conceito de precatório e cessão de precatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 3º da EC nº 113/2021", "Art. 5º da EC nº 113/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T07:39:57.754373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=81", "doc_key": "d9da67e2875a42caa650c99d276ca32d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '4baa5e3fb84ec14b42a955678183bb66e4147706bfe71227b50984cde9a413f7'),
  ('cpiuris2025::23eb64187b36085eb38bb9d64272b4ab', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Cessão de Crédito e Natureza do Precatório', '## Cessão de Crédito e Natureza do Precatório

A cessão de crédito não altera a natureza do precatório, mantendo o cessionário com direito à preferência prevista no § 1º do art. 100 da Constituição Federal.

### Conceitos
- **Cessão de Crédito**: Atividade jurídica que transfere a posse ou o direito de receber uma quantia de dinheiro de um devedor para outro.
- **Natureza do Precatório**: Característica da relação entre o credor e o devedor, que permanece inalterada após a cessão do crédito.
- **Preferência**: Direito especial concedido ao cessionário para ser priorizado na execução do débito.
- **Ordem Cronológica Originária**: Ordem em que os débitos são registrados e priorizados na execução.

### Referências legais
- Art. 100 da Constituição Federal
- § 1º do art. 100 da Constituição Federal

### Jurisprudência
- RE 631537
- STF. Plenário. RE 631537, Rel. Marco Aurélio, julgado em 22/05/2020

### Dicas de prova
- Entenda a diferença entre cessão de crédito e alteração da natureza do precatório.
- Conheça o conceito de preferência e sua importância na execução do débito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da Constituição Federal", "§ 1º do art. 100 da Constituição Federal"], "jurisprudence": ["RE 631537", "STF. Plenário. RE 631537, Rel. Marco Aurélio, julgado em 22/05/2020"], "confidence": 0.8, "extracted_at": "2026-05-30T07:40:45.363496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=81", "doc_key": "23eb64187b36085eb38bb9d64272b4ab"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '073d5d795b18d632bb83d6b84206a7914606c2f2aebbd02e4af4be4b4f50f6e6')
